// Page gate for /admin/cyrus/**. Server only.
//   1. role: requireArea(<the tab's area>) (lib/cyrus/admin/perms.ts) - redirects like every admin page;
//   2. private preview: the REAL signed-in account must be on the "modbuilder" allowlist, else a plain
//      404 (the section is indistinguishable from a route that does not exist), like /admin/mod-builder.
// The admin layout already refuses impersonation.
import { notFound } from "next/navigation";
import { getHost, type HostUser } from "../host";
import { CYRUS_ADMIN_TABS, type CyrusAdminTab } from "./perms";

export async function requireCyrusAdmin(tab: CyrusAdminTab): Promise<HostUser> {
  const area = CYRUS_ADMIN_TABS.find((t) => t.id === tab)!.area;
  const host = getHost();
  const user = await host.auth.requireArea(area);
  if (!(await host.access.isPreviewUser(await host.auth.realUser(), "modbuilder"))) notFound();
  return user;
}

export async function cyrusAdminMetadata(title: string) {
  const host = getHost();
  const ok = await host.access.isPreviewUser(await host.auth.realUser().catch(() => null), "modbuilder");
  return { title: ok ? `Cyrus · ${title}` : "Page not found", robots: { index: false, follow: false } };
}
// Cyrus admin (/admin/cyrus): who may see each tab and take each action. Pure decisions (server-side:
// it reuses lib/rbac.ts, which imports auth). Unit-tested in test/cyrus-admin.test.ts.
//
// Every tab and every write maps to one admin Area (lib/rbac.ts), so the Cyrus screens follow the
// same role model as the rest of the admin portal:
//   fleet    (ADMIN)            builds, service health, AI cost, cancel / re-run
//   billing  (BILLING + ADMIN)  token balances, grants, refunds, comps
//   support  (SUPPORT + ADMIN)  community moderation (reports, hidden posts, takedowns, suspensions)
//   platform (ADMIN)            game status, networking review + kill switch, Cyrus settings
// On top of the role, the whole section is behind the "modbuilder" private-preview allowlist
// (lib/preview-access.ts), like /admin/mod-builder and /admin/cyrus-tokens, until Cyrus launches.
import type { Role } from "@prisma/client";
import { canAccess, type Area } from "../../rbac";

export const CYRUS_ADMIN_BASE = "/admin/cyrus";

export type CyrusAdminTab = "overview" | "builds" | "users" | "games" | "community" | "library" | "audit";

export const CYRUS_ADMIN_TABS: { id: CyrusAdminTab; label: string; href: string; area: Area }[] = [
  { id: "overview", label: "Overview", href: CYRUS_ADMIN_BASE, area: "fleet" },
  { id: "builds", label: "Builds", href: `${CYRUS_ADMIN_BASE}/builds`, area: "fleet" },
  { id: "users", label: "Users & tokens", href: `${CYRUS_ADMIN_BASE}/users`, area: "billing" },
  { id: "games", label: "Games & models", href: `${CYRUS_ADMIN_BASE}/games`, area: "platform" },
  { id: "community", label: "Community", href: `${CYRUS_ADMIN_BASE}/community`, area: "support" },
  { id: "library", label: "Library & safety", href: `${CYRUS_ADMIN_BASE}/library`, area: "fleet" },
  { id: "audit", label: "Audit & settings", href: `${CYRUS_ADMIN_BASE}/audit`, area: "platform" },
];

/** Every write the Cyrus admin can make, with the Area it needs. */
export const CYRUS_ADMIN_ACTIONS = {
  "build.cancel": "fleet",
  "build.rerun": "fleet",
  "build.refund": "billing",
  "build.refund.undo": "billing",
  "tokens.grant": "billing",
  "tokens.revoke": "billing",
  "tokens.comp": "billing",
  "user.suspend": "support",
  "user.unsuspend": "support",
  "report.hide": "support",
  "report.dismiss": "support",
  "post.unhide": "support",
  "page.takedown": "support",
  "page.restore": "support",
  "network.review": "platform",
  "network.killswitch": "platform",
  "game.status": "platform",
  "setting.set": "platform",
} as const satisfies Record<string, Area>;

export type CyrusAdminAction = keyof typeof CYRUS_ADMIN_ACTIONS;

export const isCyrusAdminAction = (v: unknown): v is CyrusAdminAction => typeof v === "string" && v in CYRUS_ADMIN_ACTIONS;

export function canCyrusAdmin(role: Role, action: CyrusAdminAction): boolean {
  return canAccess(role, CYRUS_ADMIN_ACTIONS[action]);
}

export function canSeeCyrusTab(role: Role, tab: CyrusAdminTab): boolean {
  const t = CYRUS_ADMIN_TABS.find((x) => x.id === tab);
  return !!t && canAccess(role, t.area);
}

export function visibleCyrusTabs(role: Role) {
  return CYRUS_ADMIN_TABS.filter((t) => canAccess(role, t.area));
}

/** The first tab a role may open (null = none: the section is not for this role). */
export function landingCyrusTab(role: Role) {
  return visibleCyrusTabs(role)[0] ?? null;
}

// Cyrus admin: a safe, display-only reading of the build service's GET /health, plus the model tier
// mapping and the efficiency knobs. PURE and client-safe; unit-tested in test/cyrus-admin.test.ts.
//
// /health carries no secrets today, but this module whitelists the fields it shows anyway, so a
// future service field (a token, a URL with credentials) can never reach the page by accident.
// Admin-only: the underlying model names below are never shown to customers.
import { CYRUS_MODELS } from "../models";

export type ServiceSnapshot = {
  reachable: boolean;
  image: string | null;
  promptVersion: string | null;
  knowledge: string | null;
  running: number | null;
  queued: number | null;
  concurrency: number | null;
  auth: string | null;
  versions: string[];
  /** Feature flags / knobs the running service reports (0.4: images, live; 0.5 adds the efficiency knobs). */
  features: { key: string; value: string }[];
  /** Routing config the service reports (complexity thresholds and per-class models). */
  routing: { key: string; value: string }[];
  /** Tier -> model, when the service reports it (no version does yet; see TIER_DEFAULTS). */
  tiers: Record<string, string> | null;
};

const SECRETISH = /(key|token|secret|pass|auth_?header|cookie|bearer|credential)/i;

function scalar(v: unknown): string | null {
  if (v === null || v === undefined) return null;
  if (typeof v === "string") return v.slice(0, 120);
  if (typeof v === "number" || typeof v === "boolean") return String(v);
  return null;
}

function flat(obj: unknown, prefix = "", depth = 0): { key: string; value: string }[] {
  if (!obj || typeof obj !== "object" || depth > 2) return [];
  const out: { key: string; value: string }[] = [];
  for (const [k, v] of Object.entries(obj as Record<string, unknown>)) {
    const key = prefix ? `${prefix}.${k}` : k;
    if (SECRETISH.test(k)) continue;
    const s = scalar(v);
    if (s !== null) {
      if (/^(sk-|ey[A-Za-z0-9_-]{20,})/.test(s)) continue; // looks like a credential: never shown
      out.push({ key, value: s });
    } else if (Array.isArray(v)) out.push({ key, value: v.map(scalar).filter(Boolean).join(", ").slice(0, 200) });
    else out.push(...flat(v, key, depth + 1));
  }
  return out.slice(0, 60);
}

export function readHealth(h: unknown): ServiceSnapshot {
  if (!h || typeof h !== "object" || (h as { ok?: unknown }).ok !== true) {
    return { reachable: false, image: null, promptVersion: null, knowledge: null, running: null, queued: null, concurrency: null, auth: null, versions: [], features: [], routing: [], tiers: null };
  }
  const r = h as Record<string, unknown>;
  const num = (v: unknown) => (typeof v === "number" && Number.isFinite(v) ? v : null);
  const tiersRaw = r.tiers && typeof r.tiers === "object" ? (r.tiers as Record<string, unknown>) : null;
  const tiers = tiersRaw ? Object.fromEntries(Object.entries(tiersRaw).map(([k, v]) => [k, scalar(v) ?? ""]).filter(([, v]) => v)) : null;
  const auth = scalar(r.auth);
  return {
    reachable: true,
    image: scalar(r.image),
    promptVersion: scalar(r.promptVersion),
    knowledge: scalar(r.knowledge),
    running: num(r.running),
    queued: num(r.queued),
    concurrency: num(r.concurrency),
    // Only the MODE ("api_key" | "subscription" | "none"), never a value.
    auth: auth && /^[a-z_]{1,20}$/.test(auth) ? auth : null,
    versions: Array.isArray(r.versions) ? r.versions.map(scalar).filter((x): x is string => !!x).slice(0, 20) : [],
    features: flat(r.features),
    routing: flat(r.routing),
    tiers: tiers && Object.keys(tiers).length ? tiers : null,
  };
}

/**
 * The service's built-in tier defaults (services/modbuilder/route.js TIERS, overridable on the VM
 * with MB_TIER_KATARA/SAKA/YAKKO). Shown labelled as "service defaults from source" because the
 * running service does not report its effective mapping; the observed column (models that really
 * ran, from the build records) is the ground truth.
 */
export const TIER_DEFAULTS: Record<string, { model: string; env: string }> = {
  katara: { model: "claude-haiku-4-5-20251001", env: "MB_TIER_KATARA" },
  saka: { model: "claude-sonnet-5", env: "MB_TIER_SAKA" },
  yakko: { model: "claude-opus-5", env: "MB_TIER_YAKKO" },
};

/** List prices, USD per million tokens (services/modbuilder/usage.js PRICES, 2026-09). Reference only. */
export const MODEL_PRICES: Record<string, { in: number; out: number }> = {
  "claude-haiku-4-5": { in: 1, out: 5 },
  "claude-sonnet-5": { in: 2, out: 10 },
  "claude-sonnet-5-5": { in: 2, out: 10 },
  "claude-opus-5": { in: 5, out: 25 },
  "claude-opus-5-5": { in: 4, out: 20 },
};

export const shortModel = (m: string | null | undefined) => String(m || "").replace(/-\d{8}$/, "");

export function priceFor(model: string): { in: number; out: number } | null {
  return MODEL_PRICES[shortModel(model)] ?? null;
}

/** Observed tier -> model counts from build records' AI calls. Pure. */
export function observedTierModels(builds: { tier: string | null; calls: { model: string; resolvedModel?: string | null }[] }[]): Record<string, { model: string; calls: number }[]> {
  const by: Record<string, Map<string, number>> = {};
  for (const b of builds) {
    const t = b.tier ?? "auto";
    by[t] ??= new Map();
    for (const c of b.calls) {
      const m = shortModel(c.resolvedModel || c.model);
      if (!m) continue;
      by[t].set(m, (by[t].get(m) ?? 0) + 1);
    }
  }
  return Object.fromEntries(Object.entries(by).map(([t, m]) => [t, [...m.entries()].map(([model, calls]) => ({ model, calls })).sort((a, b) => b.calls - a.calls)]));
}

/** The efficiency knobs documented for service 0.5 (docs "AI Mod Builder: efficiency"). */
export const EFFICIENCY_KNOBS: { env: string; feature?: string; default: string; what: string }[] = [
  { env: "MB_AUTOFIX", feature: "autofix", default: "on", what: "Deterministic fixes (imports, renamed constants, final main class) before a model repair." },
  { env: "MB_LEAN_TOOLS", feature: "leanTools", default: "on", what: "Fresh builds get Read/Write/Edit only (no Glob/Grep)." },
  { env: "MB_EFFORT", feature: "effort", default: "off (model default)", what: "Same reasoning effort on every call of a build. Needs an eval before turning on." },
  { env: "MB_CACHE_TTL", feature: "cacheTtl", default: "CLI default (1h)", what: "Prompt cache TTL. 5m only pays off above ~15 builds/hour on one version + model." },
  { env: "MB_DEDUPE", feature: "dedupe", default: "off", what: "Reuse an identical earlier request's source (no AI call, 0 tokens). The repeat key is recorded either way." },
  { env: "MB_MAX_TURNS_REPAIR", feature: "maxTurnsRepair", default: "25", what: "Turn cap for a repair call (generation keeps MB_MAX_TURNS 60)." },
  { env: "MB_ROUTING", default: "on", what: "Complexity routing between models when the customer did not pick a tier." },
  { env: "MB_CONCURRENCY", default: "2", what: "Builds that run at once on the build VM." },
];

/** Customer-facing model names, in order. */
export const CYRUS_MODEL_NAMES = CYRUS_MODELS.map((m) => ({ id: m.id, name: m.name, blurb: m.blurb }));
// Cyrus admin audit trail. Every write made from /admin/cyrus lands here, in the existing AuditLog
// table (no schema change): action `cyrus.admin.<action>`, category "cyrus_admin", target = what it
// was done to, detail = JSON { before, after, note }. The Audit tab lists these rows together with
// the older Cyrus admin actions written by /admin/cyrus-tokens and /admin/cyrus-mods.
import { getHost } from "../host";
import type { CyrusAdminAction } from "./perms";

export const CYRUS_AUDIT_CATEGORY = "cyrus_admin";
export const CYRUS_AUDIT_PREFIX = "cyrus.admin.";

/** Admin actions written by the older Cyrus admin pages (shown in the same list). */
export const LEGACY_CYRUS_ADMIN_ACTIONS = [
  "cyrus.tokens.grant",
  "cyrus.tokens.revoke",
  "cyrus.tokens.tier",
  "cyrus.tokens.settings",
  "cyrusmods.launch",
  "cyrusmods.report.hide",
  "cyrusmods.report.dismiss",
  "cyrusmods.page.hide",
  "cyrusmods.page.unhide",
  "cyrus.lifecycle.setting",
];

export type AuditDetail = { before?: unknown; after?: unknown; note?: string };

const MAX = 4000;

/** JSON for AuditLog.detail, trimmed so one row can never be huge. Pure. */
export function auditDetail(d: AuditDetail): string {
  const s = JSON.stringify({ before: d.before ?? null, after: d.after ?? null, ...(d.note ? { note: d.note.slice(0, 300) } : {}) });
  if (s.length <= MAX) return s;
  return JSON.stringify({ before: "(trimmed)", after: "(trimmed)", note: (d.note ?? "").slice(0, 300), size: s.length });
}

/** Read AuditLog.detail back (our JSON, or a legacy free-text detail). Pure. */
export function readAuditDetail(raw: string | null): AuditDetail & { text?: string } {
  if (!raw) return {};
  if (raw.startsWith("{")) {
    try {
      const v = JSON.parse(raw) as Record<string, unknown>;
      if (v && typeof v === "object" && ("before" in v || "after" in v)) return { before: v.before, after: v.after, note: typeof v.note === "string" ? v.note : undefined };
    } catch { /* legacy text */ }
  }
  return { text: raw };
}

export async function cyrusAudit(i: { actorId: string; action: CyrusAdminAction; target: string; before?: unknown; after?: unknown; note?: string }): Promise<void> {
  await getHost().audit
    .append({ userId: i.actorId, action: CYRUS_AUDIT_PREFIX + i.action, category: CYRUS_AUDIT_CATEGORY, target: i.target.slice(0, 200), detail: auditDetail(i) })
    .catch((e) => console.error("[cyrus-admin] audit write failed", i.action, (e as Error).message));
}
// Cyrus admin: shared DB readers for the /admin/cyrus pages. Server only. Read-only.
import type { ModBuild } from "@prisma/client";
import { cyrusDb as db } from "../db";
import { readCyrusMeta } from "../meta";
import type { BuildLite } from "./metrics";
import { getHost } from "../host";

/** The game a build was for. ModBuild is the Minecraft build service's table; a future game id in the meta wins. */
export function gameOfBuild(row: Pick<ModBuild, "cyrus">): string {
  const g = row.cyrus && typeof row.cyrus === "object" && !Array.isArray(row.cyrus) ? (row.cyrus as Record<string, unknown>).game : null;
  return typeof g === "string" && /^[a-z0-9]{2,20}$/.test(g) ? g : "minecraft";
}

/** The Cyrus model of a build: the one picked (meta), else the token hold's model, else "auto" (service routing). */
export function modelOfBuild(row: Pick<ModBuild, "cyrus">, holdModel?: string | null): string {
  return readCyrusMeta(row.cyrus).model ?? holdModel ?? "auto";
}

export const LITE_SELECT = { id: true, userId: true, status: true, errorCode: true, costUsd: true, durationMs: true, createdAt: true, cyrus: true } as const;

export function toLite(row: Pick<ModBuild, "id" | "userId" | "status" | "errorCode" | "costUsd" | "durationMs" | "createdAt" | "cyrus">, holdModel?: string | null): BuildLite {
  return { id: row.id, userId: row.userId, status: row.status, errorCode: row.errorCode, costUsd: row.costUsd || 0, durationMs: row.durationMs, createdAt: row.createdAt, model: modelOfBuild(row, holdModel), game: gameOfBuild(row) };
}

export async function emailMap(ids: string[]): Promise<Map<string, string>> {
  const uniq = [...new Set(ids.filter(Boolean))];
  if (!uniq.length) return new Map();
  const users = await getHost().users.emails(uniq);
  return new Map(users.map((u) => [u.id, u.email]));
}

export async function holdsFor(buildIds: string[]) {
  if (!buildIds.length) return new Map<string, { model: string; amount: number; status: string; charged: number | null; costUsd: number | null }>();
  const rows = await db.cyrusTokenReservation.findMany({ where: { buildId: { in: buildIds } }, select: { buildId: true, model: true, amount: true, status: true, charged: true, costUsd: true } });
  return new Map(rows.map((r) => [r.buildId, r]));
}
// Cyrus admin: read data that other v6 branches add (Prisma models, library files) without a
// compile-time dependency on them. Before their merge these return null and the tab shows an honest
// "arrives with the <branch> merge" state; after the merge they read the real rows unchanged.
// Server only.
import { readFile } from "node:fs/promises";
import { join } from "node:path";
import { cyrusDb as db } from "../db";

type AnyDelegate = {
  findMany: (args?: unknown) => Promise<Record<string, unknown>[]>;
  count: (args?: unknown) => Promise<number>;
};

/** A Prisma model delegate by name, or null when this build's schema has no such model. */
export function optionalModel(name: string): AnyDelegate | null {
  try {
    const d = (db as unknown as Record<string, unknown>)[name];
    return d && typeof (d as AnyDelegate).findMany === "function" ? (d as AnyDelegate) : null;
  } catch {
    return null;
  }
}

export async function optionalFindMany(name: string, args: unknown): Promise<Record<string, unknown>[] | null> {
  const m = optionalModel(name);
  if (!m) return null;
  try {
    return await m.findMany(args);
  } catch {
    return null; // model exists in the client but the table is not pushed yet
  }
}

// ---------------------------------------------------------------------------
// Pattern library (library branch). It ships a JSON index next to the service.
// ---------------------------------------------------------------------------

export type LibraryPattern = { id: string; title: string; category: string; versions: string[]; verified: boolean; status: string; checkedAt: string | null; license: string | null };

const LIBRARY_INDEX_CANDIDATES = ["services/modbuilder/library/index.json", "services/modbuilder/library.json", "data/cyrus-library/index.json"];

/** PURE: read an index file's JSON into patterns, whatever exact field names the library uses. */
export function readLibraryIndex(v: unknown): LibraryPattern[] {
  const list = Array.isArray(v) ? v : v && typeof v === "object" && Array.isArray((v as { patterns?: unknown }).patterns) ? (v as { patterns: unknown[] }).patterns : [];
  const out: LibraryPattern[] = [];
  for (const x of list) {
    if (!x || typeof x !== "object") continue;
    const r = x as Record<string, unknown>;
    const ver = (r.verification && typeof r.verification === "object" ? r.verification : {}) as Record<string, unknown>;
    const status = String(ver.status ?? r.status ?? (ver.verified === true || r.verified === true ? "verified" : "unverified"));
    const versions = Array.isArray(ver.versions) ? ver.versions : Array.isArray(r.versions) ? r.versions : [];
    out.push({
      id: String(r.id ?? "").slice(0, 80),
      title: String(r.title ?? r.id ?? "").slice(0, 120),
      category: String(r.category ?? "uncategorised").slice(0, 40),
      versions: versions.map(String).slice(0, 20),
      verified: status === "verified",
      status,
      checkedAt: typeof (ver.date ?? ver.checkedAt) === "string" ? String(ver.date ?? ver.checkedAt) : null,
      license: typeof (r.license ?? (r.source as Record<string, unknown> | undefined)?.license) === "string" ? String(r.license ?? (r.source as Record<string, unknown>).license) : null,
    });
  }
  return out.filter((p) => p.id);
}

export async function loadLibraryIndex(): Promise<{ patterns: LibraryPattern[]; source: string } | null> {
  for (const rel of LIBRARY_INDEX_CANDIDATES) {
    try {
      const raw = await readFile(join(process.cwd(), rel), "utf8");
      return { patterns: readLibraryIndex(JSON.parse(raw)), source: rel };
    } catch { /* next */ }
  }
  return null;
}
