      <Section title="Builds per day" sub="Last 30 days, UTC, by outcome. Refused = stopped by the safety check; cancelled = stopped by the customer or Nxeon.">
        {counts.total === 0 ? <Empty>No builds in the last 30 days.</Empty> : <DayBars days={perDay(lite, 30, now)} />}
      </Section>

      <div className="grid min-w-0 gap-0 xl:grid-cols-2 xl:gap-6">
        <Section title="By game" sub="Rates are over finished builds. Only Minecraft has a real build pipeline today.">
