export type LibraryAdminView = {
  total: number;
  byKind: Record<string, number>; byTier: Record<string, number>; byStatus: Record<string, number>;
  matrix: { kind: string; tier: string; status: string; n: number }[];
  holdQueue: { id: string; kind: string; title: string; tier: string; reason: string | null; flags: string[]; contributor: string | null; reports: number }[];
