// The REAL wiring of the library backend (SERVER ONLY): env switches (./flags.ts), Cyrus' own database through
// lib/cyrus/db.ts (the host seam), the studio viewer + plan lookup the studios already use, the host rate limiter.
// Nothing is built when the backend is off; an object store is only created when CYRUS_LIBRARY_STORE is local / s3.
import { cyrusDb } from "../../db";
import { getHost } from "../../host";
import { studioPlanOf, studioViewer } from "../../studios/deps";
import { libraryFlags, type Env } from "./flags";
import { spawnTool } from "./derive";
import type { LibraryHttpDeps } from "./http";
import { LibraryStore } from "./library-store";
import { LocalObjectStore, S3ObjectStore, StagingSource, type LibraryObjectStore } from "./objects";
import { createPgCatalog, prismaSql } from "./pg";

export function libraryObjectStore(env: Env = process.env): LibraryObjectStore | null {
  const f = libraryFlags(env);
  if (f.store === "local") return f.localDir ? new LocalObjectStore(f.localDir) : null;
  if (f.store === "s3") {
    const need = ["CYRUS_LIBRARY_S3_ENDPOINT", "CYRUS_LIBRARY_S3_BUCKET", "CYRUS_LIBRARY_S3_ACCESS_KEY_ID", "CYRUS_LIBRARY_S3_SECRET_ACCESS_KEY"];
    if (need.some((k) => !env[k])) return null;
    return new S3ObjectStore({
      endpoint: env.CYRUS_LIBRARY_S3_ENDPOINT!, bucket: env.CYRUS_LIBRARY_S3_BUCKET!, region: env.CYRUS_LIBRARY_S3_REGION || "auto",
      credentials: { accessKeyId: env.CYRUS_LIBRARY_S3_ACCESS_KEY_ID!, secretAccessKey: env.CYRUS_LIBRARY_S3_SECRET_ACCESS_KEY! }, prefix: env.CYRUS_LIBRARY_S3_PREFIX || undefined,
    });
  }
  return null;
}

/** The Postgres catalog over Cyrus' own tables (CyrusCatalogEntry & co; the migrations must have been applied). */
export const pgLibrary = () => createPgCatalog(prismaSql(cyrusDb), { fuzzy: true });

export function libraryHttpDeps(env: Env = process.env): LibraryHttpDeps {
  const flags = libraryFlags(env);
  let backend: ReturnType<LibraryHttpDeps["backend"]> | undefined;
  return {
    flags,
    viewer: async () => { const v = await studioViewer(); return v ? { userId: v.userId } : null; },
    planOf: studioPlanOf(env),
    rateLimit: (key, max, windowMs) => getHost().rateLimit.check(key, { max, windowMs }),
    backend() {
      if (backend !== undefined) return backend;
      const objects = flags.enabled ? libraryObjectStore(env) : null;
      if (!objects) return (backend = null);
      const pg = pgLibrary();
      const store = new LibraryStore({ objects, staging: flags.stagingDir ? new StagingSource(flags.stagingDir) : null, records: pg.records, tools: { ...flags.tools, run: spawnTool } });
      return (backend = { index: pg.index, catalog: pg.store, store, records: pg.records });
    },
  };
}
