export async function deleteStaffAccount(userId: string): Promise<{ ok?: boolean; error?: string }> {
  const admin = await requireAdmin();
  if (userId === admin.id) return { error: "You can't remove your own access." };

  const target = await requireStaffTarget(userId);
  if (!target) return { error: "User not found." };

  if (target.role === "ADMIN") {
    const adminCount = await db.user.count({ where: { role: "ADMIN" } });
    if (adminCount <= 1) return { error: "Can't remove the last remaining admin account." };
  }

  await db.$transaction([
    db.user.update({ where: { id: userId }, data: { suspended: true, sessionVersion: { increment: 1 } } }),
    db.staffGrant.deleteMany({ where: { userId } }),
    db.staffIpAllow.deleteMany({ where: { userId } }),
    db.staffMailboxGrant.deleteMany({ where: { userId } }),
  ]);
  await db.auditLog.create({
    data: { userId: admin.id, action: "staff.delete", detail: `${target.email} (was ${target.role})` },
  });

  revalidatePath(`/admin/staff/${userId}`);
  revalidatePath("/admin/staff");
  return { ok: true };
}

