// Cyrus account suspensions (admin, /admin/cyrus/users and /community). PURE helpers + a small
// server reader. No schema change: the list lives in ONE Setting, `cyrus_suspensions`, a JSON array.
//
// Scopes:
//   build      the account cannot start new Cyrus builds (lib/modbuilder/create.ts asks this)
//   community  the account cannot post, report or publish in the Cyrus community
// A suspension can end on a date (`until`) or stay until lifted. Lifting removes the entry; every
// change is audited with before/after (lib/cyrus/admin/audit.ts), so it is reversible.

import { getHost } from "./host";
export const CYRUS_SUSPENSIONS_KEY = "cyrus_suspensions";
export type SuspensionScope = "build" | "community";
export const SUSPENSION_SCOPES: SuspensionScope[] = ["build", "community"];

export type Suspension = { userId: string; scopes: SuspensionScope[]; reason: string; by: string; at: string; until: string | null };

const isScope = (v: unknown): v is SuspensionScope => v === "build" || v === "community";

/** Parse the stored JSON (never throws; bad entries are dropped). */
export function parseSuspensions(raw: string | null | undefined): Suspension[] {
  let v: unknown;
  try {
    v = JSON.parse(raw || "[]");
  } catch {
    return [];
  }
  if (!Array.isArray(v)) return [];
  const out: Suspension[] = [];
  for (const x of v) {
    if (!x || typeof x !== "object") continue;
    const r = x as Record<string, unknown>;
    if (typeof r.userId !== "string" || !/^[A-Za-z0-9_-]{1,64}$/.test(r.userId)) continue;
    const scopes = Array.isArray(r.scopes) ? [...new Set(r.scopes.filter(isScope))] : [];
    if (!scopes.length) continue;
    out.push({
      userId: r.userId,
      scopes,
      reason: String(r.reason ?? "").slice(0, 300),
      by: String(r.by ?? "").slice(0, 64),
      at: typeof r.at === "string" ? r.at : new Date(0).toISOString(),
      until: typeof r.until === "string" && !Number.isNaN(Date.parse(r.until)) ? r.until : null,
    });
  }
  return out;
}

export function activeSuspension(list: Suspension[], userId: string, scope: SuspensionScope, now: Date): Suspension | null {
  return list.find((s) => s.userId === userId && s.scopes.includes(scope) && (!s.until || Date.parse(s.until) > now.getTime())) ?? null;
}

/** Add or replace one account's entry (pure). */
export function upsertSuspension(list: Suspension[], s: Suspension): Suspension[] {
  return [...list.filter((x) => x.userId !== s.userId), s];
}

export function removeSuspension(list: Suspension[], userId: string): Suspension[] {
  return list.filter((x) => x.userId !== userId);
}

/** Drop entries whose end date has passed (keeps the Setting small). */
export function pruneSuspensions(list: Suspension[], now: Date): Suspension[] {
  return list.filter((s) => !s.until || Date.parse(s.until) > now.getTime());
}

export async function loadSuspensions(): Promise<Suspension[]> {
  try {
    const stored = await getHost().settings.readStored([CYRUS_SUSPENSIONS_KEY]);
    return parseSuspensions(stored[CYRUS_SUSPENSIONS_KEY]);
  } catch {
    return [];
  }
}

