  if (stuck.length) out.push({ level: "red", code: "stuck", text: `${stuck.length} build(s) still running after ${i.stuckAfterMin ?? 30} min (oldest ${stuck.map((b) => b.id).slice(0, 3).join(", ")}). Cancel them from the build page.`, href: "/admin/cyrus/builds?outcome=running" });
