  const lost = i.recentFailed.filter((b) => b.errorCode && LOST_CODES.includes(b.errorCode) && i.now.getTime() - b.createdAt.getTime() < DAY);
  if (lost.length) out.push({ level: "amber", code: "lost", text: `${lost.length} build(s) in the last 24 h failed because the portal could not reach the builder (${[...new Set(lost.map((b) => b.errorCode))].join(", ")}).`, href: "/admin/cyrus/builds?outcome=failed&days=1" });
  if (i.orphanHolds.length) out.push({ level: "amber", code: "holds", text: `${i.orphanHolds.length} token hold(s) belong to builds that already finished (settle did not run). Open the build to see it.`, href: `/admin/cyrus/builds/${i.orphanHolds[0].buildId}` });
  if (i.openReports) out.push({ level: "amber", code: "reports", text: `${i.openReports} community report(s) waiting for review.`, href: "/admin/cyrus/community" });
  return out;
}

// ---------------------------------------------------------------------------
// Abuse signals (per user, derived from real rows)
// ---------------------------------------------------------------------------

export type AbuseSignal = { level: "red" | "amber"; code: string; text: string };

export function abuseSignals(i: {
  builds30d: { status: string; errorCode: string | null; costUsd: number }[];
  reportsAgainst: number;
  hiddenPosts: number;
  usedToday: number;
  dailyCap: number;
  writeoffTokens: number;
}): AbuseSignal[] {
  const out: AbuseSignal[] = [];
  const c = countOutcomes(i.builds30d);
  if (c.refused >= 3) out.push({ level: "red", code: "refusals", text: `${c.refused} builds refused by the safety check in 30 days` });
  else if (c.refused > 0) out.push({ level: "amber", code: "refusals", text: `${c.refused} build(s) refused by the safety check in 30 days` });
  if (c.finished >= 5 && (c.failed + c.refused) / c.finished >= 0.6) out.push({ level: "amber", code: "failrate", text: `${Math.round(((c.failed + c.refused) / c.finished) * 100)}% of ${c.finished} finished builds failed or were refused` });
  if (i.dailyCap > 0 && i.usedToday >= i.dailyCap) out.push({ level: "amber", code: "cap", text: `At today's token cap (${i.usedToday} of ${i.dailyCap})` });
  if (i.reportsAgainst >= 3) out.push({ level: "red", code: "reports", text: `${i.reportsAgainst} community reports against their posts` });
  else if (i.reportsAgainst > 0) out.push({ level: "amber", code: "reports", text: `${i.reportsAgainst} community report(s) against their posts` });
  if (i.hiddenPosts > 0) out.push({ level: "amber", code: "hidden", text: `${i.hiddenPosts} of their posts are hidden` });
  if (i.writeoffTokens > 0) out.push({ level: "amber", code: "writeoff", text: `${i.writeoffTokens} tokens of AI cost written off (cost above what they held)` });
  return out;
}

