"use server";

/**
 * Cyrus admin core (r40) writes: view-as, ban (with optional propagation to the Nxeon account), GDPR erasure.
 * Same contract as lib/actions-cyrus-admin.ts: role area per action (lib/cyrus/admin/perms.ts), the REAL account on the
 * "modbuilder" preview list, never while impersonating, audited before/after (category cyrus_admin), redirect back
 * with ?ok= / ?err=. Lives outside lib/cyrus because it uses Nxeon's own account controls (impersonation cookie,
 * User.suspended); the Cyrus-only logic is in lib/cyrus/admin/ops.ts and gdpr.ts.
 */
import { notFound, redirect } from "next/navigation";
import type { User } from "@prisma/client";
import { db } from "./db";
import { impersonating, realUser, setImpersonation } from "./auth";
import { recordAudit } from "./audit";
import { requireArea } from "./rbac";
import { isPreviewUser } from "./preview-access";
import { CYRUS_ADMIN_ACTIONS, CYRUS_ADMIN_BASE, canCyrusAdmin, type CyrusAdminAction } from "./cyrus/admin/perms";
import { cyrusAudit } from "./cyrus/admin/audit";
import { BAN_PREFIX, canViewAs, isBan } from "./cyrus/admin/ops";
import { gdprErase, gdprEraseEnabled, gdprPlanFor } from "./cyrus/admin/gdpr";
import { CYRUS_SUSPENSIONS_KEY, loadSuspensions, pruneSuspensions, removeSuspension, upsertSuspension } from "./cyrus/suspensions";

const str = (fd: FormData, k: string, max = 300) => String(fd.get(k) ?? "").trim().slice(0, max);
const ticked = (fd: FormData, k: string) => fd.get(k) === "1" || fd.get(k) === "on";

function go(fd: FormData, kind: "ok" | "err", msg: string): never {
  const b = String(fd.get("back") ?? "");
  const base = b.startsWith(CYRUS_ADMIN_BASE) && !b.includes("//") && b.length < 300 ? b : `${CYRUS_ADMIN_BASE}/users`;
  const [p, q = ""] = base.split("?");
  const params = new URLSearchParams(q);
  params.delete("ok"); params.delete("err");
  params.set(kind, msg.slice(0, 300));
  redirect(`${p}?${params.toString()}`);
}

async function guard(action: CyrusAdminAction): Promise<User> {
  const admin = await requireArea(CYRUS_ADMIN_ACTIONS[action]);
  if (await impersonating()) redirect("/dashboard");
  if (!(await isPreviewUser(await realUser(), "modbuilder"))) notFound();
  return admin;
}

async function target(fd: FormData) {
  const v = str(fd, "userId", 64);
  if (!/^[A-Za-z0-9_-]{1,64}$/.test(v)) return null;
  return db.user.findUnique({ where: { id: v }, select: { id: true, email: true, role: true, suspended: true } });
}

/** View the customer's Cyrus screens as them (Nxeon impersonation, 2 h, ADMIN only, never staff). Audited on both trails. */
export async function adminCyrusViewAs(fd: FormData) {
  const admin = await guard("user.viewas");
  const t = await target(fd);
  const ok = canViewAs(admin, t);
  if (!ok.ok) go(fd, "err", ok.error);
  const reason = str(fd, "reason", 200);
  if (reason.length < 3) go(fd, "err", "Give a short reason (support ticket id or why): it is kept in the audit log.");
  await cyrusAudit({ actorId: admin.id, action: "user.viewas", target: `user:${t!.id}`, after: { email: t!.email, expires: "2h" }, note: reason });
  await recordAudit(admin.id, "admin.impersonate_start", `${t!.email}`);
  await setImpersonation(t!.id);
  redirect("/dashboard/cyrus");
}

/** Ban from Cyrus: every scope, no end date. With "also suspend the Nxeon account" (ADMIN), the person is signed out everywhere. */
export async function adminCyrusBan(fd: FormData) {
  const admin = await guard("user.ban");
  const t = await target(fd);
  if (!t) go(fd, "err", "No such account.");
  if (t.id === admin.id) go(fd, "err", "You can't ban yourself.");
  if (t.role !== "CUSTOMER") go(fd, "err", "Staff accounts are managed in Nxeon staff settings, not here.");
  const reason = str(fd, "reason", 280);
  if (reason.length < 3) go(fd, "err", "Give a reason (kept in the audit log).");
  if (!ticked(fd, "confirm")) go(fd, "err", "Tick the box to confirm the ban.");
  const propagate = ticked(fd, "nxeon");
  if (propagate && !canCyrusAdmin(admin.role, "user.ban.nxeon")) go(fd, "err", "Only an admin can also suspend the Nxeon account.");
  const now = new Date();
  const list = pruneSuspensions(await loadSuspensions(), now);
  const before = list.find((s) => s.userId === t.id) ?? null;
  const entry = { userId: t.id, scopes: ["build", "community"] as ("build" | "community")[], reason: BAN_PREFIX + reason, by: admin.id, at: now.toISOString(), until: null };
  await db.setting.upsert({ where: { key: CYRUS_SUSPENSIONS_KEY }, update: { value: JSON.stringify(upsertSuspension(list, entry)) }, create: { key: CYRUS_SUSPENSIONS_KEY, value: JSON.stringify(upsertSuspension(list, entry)) } });
  await cyrusAudit({ actorId: admin.id, action: "user.ban", target: `user:${t.id}`, before, after: entry, note: reason });
  if (propagate && !t.suspended) {
    // Nxeon's own lockout: realUser() refuses suspended accounts and the session version bump ends live sessions.
    await db.user.update({ where: { id: t.id }, data: { suspended: true, sessionVersion: { increment: 1 } } });
    await recordAudit(admin.id, "cyrus.admin.nxeon_suspend", `${t.email}: ${reason}`.slice(0, 300));
    await cyrusAudit({ actorId: admin.id, action: "user.ban.nxeon", target: `user:${t.id}`, before: { nxeonSuspended: false }, after: { nxeonSuspended: true }, note: reason });
  }
  go(fd, "ok", `${t.email} banned from Cyrus${propagate ? " and the Nxeon account suspended" : ""}.`);
}

/** Lift a ban. Lifting the Nxeon suspension is a separate tick (ADMIN). */
export async function adminCyrusUnban(fd: FormData) {
  const admin = await guard("user.unban");
  const t = await target(fd);
  if (!t) go(fd, "err", "No such account.");
  const list = await loadSuspensions();
  const before = list.find((s) => s.userId === t.id) ?? null;
  const nx = ticked(fd, "nxeon");
  if (!isBan(before) && !(nx && t.suspended)) go(fd, "err", "That account is not banned.");
  if (nx && !canCyrusAdmin(admin.role, "user.unban.nxeon")) go(fd, "err", "Only an admin can lift a Nxeon account suspension.");
  if (isBan(before)) {
    const next = removeSuspension(list, t.id);
    if (next.length) await db.setting.update({ where: { key: CYRUS_SUSPENSIONS_KEY }, data: { value: JSON.stringify(next) } });
    else await db.setting.deleteMany({ where: { key: CYRUS_SUSPENSIONS_KEY } });
    await cyrusAudit({ actorId: admin.id, action: "user.unban", target: `user:${t.id}`, before, after: null, note: str(fd, "note") });
  }
  if (nx && t.suspended) {
    await db.user.update({ where: { id: t.id }, data: { suspended: false } });
    await recordAudit(admin.id, "cyrus.admin.nxeon_unsuspend", `${t.email}`);
    await cyrusAudit({ actorId: admin.id, action: "user.unban.nxeon", target: `user:${t.id}`, before: { nxeonSuspended: true }, after: { nxeonSuspended: false }, note: str(fd, "note") });
  }
  go(fd, "ok", `Ban lifted for ${t.email}${nx ? " (Nxeon account active again)" : ""}.`);
}

/** GDPR erasure of the person's Cyrus data. Off unless CYRUS_GDPR_ERASE=1; the email must be typed back. */
export async function adminCyrusGdprErase(fd: FormData) {
  const admin = await guard("user.gdpr.erase");
  const t = await target(fd);
  if (!t) go(fd, "err", "No such account.");
  if (!gdprEraseEnabled()) go(fd, "err", "Erasure is switched off on this server (CYRUS_GDPR_ERASE). The plan above is a dry run.");
  if (str(fd, "typed", 200).toLowerCase() !== (t.email ?? "").toLowerCase()) go(fd, "err", "Type the account's email exactly to confirm the erasure.");
  const reason = str(fd, "reason", 200);
  if (reason.length < 3) go(fd, "err", "Give the request reference (kept in the audit log).");
  const plan = await gdprPlanFor(t.id);
  const res = await gdprErase(t.id);
  await cyrusAudit({ actorId: admin.id, action: "user.gdpr.erase", target: `user:${t.id}`, before: { delete: plan.delete, anonymise: plan.anonymise, retain: plan.retain }, after: { deleted: res.deleted, anonymised: res.anonymised, retained: res.retained, anonId: res.anonId }, note: reason });
  go(fd, "ok", `Cyrus data erased for ${t.email}: ${Object.values(res.deleted).reduce((a, b) => a + b, 0)} rows deleted, ${Object.values(res.anonymised).reduce((a, b) => a + b, 0)} anonymised; financial rows kept.`);
}

