// Cyrus admin r40: the account-level controls on Users & tokens (view-as, ban + Nxeon propagation, GDPR export / erase).
// Server component; every button posts to lib/actions-cyrus-admin-core.ts, which re-checks the role on its own.
import { db } from "@/lib/db";
import type { Role } from "@prisma/client";
import { canCyrusAdmin } from "@/lib/cyrus/admin/perms";
import { isBan } from "@/lib/cyrus/admin/ops";
import { gdprEraseEnabled, gdprPlanFor } from "@/lib/cyrus/admin/gdpr";
import { loadSuspensions } from "@/lib/cyrus/suspensions";
import { adminCyrusBan, adminCyrusGdprErase, adminCyrusUnban, adminCyrusViewAs } from "@/lib/actions-cyrus-admin-core";
import { Badge } from "@/components/ui/primitives";
import { Hidden, Section, TableWrap, n, tdRow, thCls } from "./ui";

export async function AccountControls({ userId, role, back }: { userId: string; role: Role; back: string }) {
  const u = await db.user.findUnique({ where: { id: userId }, select: { id: true, email: true, role: true, suspended: true } });
  if (!u) return null;
  const can = {
    viewAs: canCyrusAdmin(role, "user.viewas"), ban: canCyrusAdmin(role, "user.ban"), nx: canCyrusAdmin(role, "user.ban.nxeon"),
    exp: canCyrusAdmin(role, "user.gdpr.export"), erase: canCyrusAdmin(role, "user.gdpr.erase"),
  };
  if (!can.viewAs && !can.ban && !can.exp) return null;
  const ban = (await loadSuspensions()).find((s) => s.userId === u.id) ?? null;
  const banned = isBan(ban);
  const plan = can.exp ? await gdprPlanFor(u.id).catch(() => null) : null;
  const eraseOn = gdprEraseEnabled();
  const staff = u.role !== "CUSTOMER";
  return (
    <Section title="Account controls" sub="View as the customer, ban, and data requests. Each one is audited; staff accounts are refused." right={<div className="flex flex-wrap gap-2">{banned ? <Badge tone="red">banned from Cyrus</Badge> : null}{u.suspended ? <Badge tone="red">Nxeon account suspended</Badge> : <Badge tone="slate">Nxeon account active</Badge>}</div>}>
      <div className="grid min-w-0 gap-4 lg:grid-cols-3">
        {can.viewAs && (
          <form action={adminCyrusViewAs} className="card flex flex-col gap-2">
            <h3 className="text-sm font-semibold">View as</h3>
            <Hidden name="userId" value={u.id} /><Hidden name="back" value={back} />
            <input name="reason" placeholder="Ticket id or reason (required)" className="input text-sm" required minLength={3} />
            <button className="btn-secondary text-sm" disabled={staff}>Open their Cyrus screens</button>
            <p className="text-xs text-slate-500">Nxeon impersonation, 2 hours, admins only. Not available on admin.cyrus.my (Nxeon refuses it on the Cyrus host).</p>
          </form>
        )}
        {can.ban && (
          banned || u.suspended ? (
            <form action={adminCyrusUnban} className="card flex flex-col gap-2">
              <h3 className="text-sm font-semibold">Lift ban</h3>
              <Hidden name="userId" value={u.id} /><Hidden name="back" value={back} />
              {ban ? <p className="text-xs text-slate-400">{ban.reason}</p> : null}
              {can.nx && u.suspended ? <label className="flex items-center gap-2 text-sm"><input type="checkbox" name="nxeon" value="1" /> Also lift the Nxeon account suspension</label> : null}
              <input name="note" placeholder="Why (audit log)" className="input text-sm" />
              <button className="btn-secondary text-sm">Lift</button>
            </form>
          ) : (
            <form action={adminCyrusBan} className="card flex flex-col gap-2">
              <h3 className="text-sm font-semibold">Ban from Cyrus</h3>
              <Hidden name="userId" value={u.id} /><Hidden name="back" value={back} />
              <input name="reason" placeholder="Reason (required)" className="input text-sm" required minLength={3} />
              {can.nx ? <label className="flex items-center gap-2 text-sm"><input type="checkbox" name="nxeon" value="1" /> Also suspend the Nxeon account (signs them out everywhere)</label> : null}
              <label className="flex items-center gap-2 text-sm"><input type="checkbox" name="confirm" value="1" required /> I confirm this ban</label>
              <button className="btn-danger text-sm" disabled={staff}>Ban</button>
            </form>
          )
        )}
        {can.exp && (
          <div className="card flex flex-col gap-2">
            <h3 className="text-sm font-semibold">Data request (GDPR)</h3>
            <a className="btn-secondary text-center text-sm" href={`/api/admin/cyrus/gdpr?user=${encodeURIComponent(u.id)}`}>Download Cyrus data (JSON)</a>
            {plan ? <p className="text-xs text-slate-400">Erasure plan: {n(plan.delete)} rows deleted, {n(plan.anonymise)} anonymised, {n(plan.retain)} financial rows kept.</p> : null}
            {can.erase && (
              <form action={adminCyrusGdprErase} className="flex flex-col gap-2">
                <Hidden name="userId" value={u.id} /><Hidden name="back" value={back} />
                <input name="reason" placeholder="Request reference" className="input text-sm" disabled={!eraseOn} />
                <input name="typed" placeholder="Type their email to confirm" className="input text-sm" disabled={!eraseOn} autoComplete="off" />
                <button className="btn-danger text-sm" disabled={!eraseOn}>Erase Cyrus data</button>
                {!eraseOn ? <p className="text-xs text-slate-500">Erasure is off on this server (CYRUS_GDPR_ERASE). Dry run only.</p> : null}
              </form>
            )}
          </div>
        )}
      </div>
      {plan ? (
        <details className="mt-3">
          <summary className="cursor-pointer text-xs text-slate-400">Erasure plan per table</summary>
          <TableWrap>
            <table className="w-full text-xs">
              <thead><tr className={thCls}><th>Table</th><th>Policy</th><th className="text-right">Rows</th><th>Why</th></tr></thead>
              <tbody>{plan.rows.map((r) => <tr key={r.model} className={tdRow}><td className="font-mono">{r.model}</td><td>{r.policy}</td><td className="text-right tabular-nums">{r.rows === null ? "no table" : n(r.rows)}</td><td className="text-slate-400">{r.why}</td></tr>)}</tbody>
            </table>
          </TableWrap>
        </details>
      ) : null}
    </Section>
  );
}

