// Cyrus admin r40 (admin + ops features): pure logic. No DB, no network.
import "./_cyrus-server-only-shim";
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { canCyrusAdmin } from "../lib/cyrus/admin/perms";
import { BAN_PREFIX, CYRUS_GDPR_TABLES, canViewAs, flightLabel, flightSummary, gdprPlan, isBan, readEvalBaseline, revenueFromLedger, topErrors, ANON_USER } from "../lib/cyrus/admin/ops";
import { gdprEraseEnabled } from "../lib/cyrus/admin/gdpr";

const flight = (verdict: string, state = "done") => ({ testFlight: { schema: 1, state, verdict, checks: [], version: "1.21.11", flights: 1, busyRetries: 0, at: "2026-10-11T00:00:00Z" } });

describe("r40 admin core: revenue", () => {
  it("counts only purchases with a real amount; test mode apart; plan vs top-up", () => {
    const r = revenueFromLedger([
      { kind: "purchase", source: "topup", meta: { paidCents: 500, livemode: true } },
      { kind: "purchase", source: "plan", meta: { amountPaid: 1500, livemode: true } },
      { kind: "purchase", source: "topup", meta: { paidCents: 999, livemode: false } },
      { kind: "purchase", source: "topup", meta: {} },
      { kind: "grant", source: "admin", meta: { paidCents: 100000 } },
      { kind: "purchase", source: "topup", meta: { paidCents: -5 } },
    ]);
    assert.deepEqual(r, { topupCents: 500, planCents: 1500, totalCents: 2000, purchases: 2, testCents: 999, unknown: 2 });
  });
  it("empty input is zero, never invented", () => {
    assert.equal(revenueFromLedger([]).totalCents, 0);
  });
});

describe("r40 admin core: flights, errors, eval", () => {
  it("flight summary counts succeeded builds only and never treats not-run as passed", () => {
    const c = flightSummary([
      { status: "succeeded", cyrus: flight("passed") },
      { status: "succeeded", cyrus: flight("failed") },
      { status: "succeeded", cyrus: flight("not_run", "not_run") },
      { status: "succeeded", cyrus: flight("not_run", "queued") },
      { status: "succeeded", cyrus: null },
      { status: "failed", cyrus: flight("passed") },
    ]);
    assert.deepEqual(c, { passed: 1, failed: 1, incomplete: 0, notRun: 1, pending: 1, none: 1, total: 5 });
    assert.equal(flightLabel(flight("not_run", "gave_up").testFlight ? flight("not_run", "gave_up") : null), "not run");
    assert.equal(flightLabel(null), null);
  });
  it("top errors groups failed builds by code, most common first", () => {
    const t = (id: string, code: string | null, h: number) => ({ id, status: "failed", errorCode: code, createdAt: new Date(Date.UTC(2026, 9, 11, h)) });
    const e = topErrors([t("a", "compile", 1), t("b", "compile", 3), t("c", null, 2), { ...t("d", "x", 1), status: "succeeded" }]);
    assert.deepEqual(e.map((x) => [x.code, x.n, x.sampleId]), [["compile", 2, "b"], ["unknown", 1, "c"]]);
  });
  it("eval baseline: null until a real baseline exists", () => {
    assert.equal(readEvalBaseline(null), null);
    assert.equal(readEvalBaseline({ totals: {} }), null);
    assert.deepEqual(readEvalBaseline({ tag: "first1", spentUsd: 9.7, totals: { finalPassPct: 81, fullPassPct: 60, prompts: 90 } }), { tag: "first1", at: null, prompts: 90, finalPassPct: 81, fullPassPct: 60, spentUsd: 9.7 });
  });
});

describe("r40 admin core: users", () => {
  it("ban = every scope, no end date, ban prefix", () => {
    const s = { userId: "u", scopes: ["build", "community"] as ("build" | "community")[], reason: BAN_PREFIX + "fraud", by: "a", at: "", until: null };
    assert.equal(isBan(s), true);
    assert.equal(isBan({ ...s, until: "2030-01-01" }), false);
    assert.equal(isBan({ ...s, scopes: ["build"] }), false);
    assert.equal(isBan({ ...s, reason: "fraud" }), false);
    assert.equal(isBan(null), false);
  });
  it("view-as refuses staff, yourself and unknown accounts", () => {
    assert.deepEqual(canViewAs({ id: "a" }, { id: "u", role: "CUSTOMER" }), { ok: true });
    assert.equal(canViewAs({ id: "a" }, { id: "a", role: "CUSTOMER" }).ok, false);
    assert.equal(canViewAs({ id: "a" }, { id: "s", role: "SUPPORT" }).ok, false);
    assert.equal(canViewAs({ id: "a" }, null).ok, false);
  });
  it("roles: view-as, Nxeon propagation and GDPR are ADMIN only; support may ban in Cyrus", () => {
    for (const a of ["user.viewas", "user.ban.nxeon", "user.unban.nxeon", "user.gdpr.export", "user.gdpr.erase"] as const) {
      assert.equal(canCyrusAdmin("ADMIN", a), true, a);
      assert.equal(canCyrusAdmin("SUPPORT", a), false, a);
      assert.equal(canCyrusAdmin("BILLING", a), false, a);
    }
    assert.equal(canCyrusAdmin("SUPPORT", "user.ban"), true);
    assert.equal(canCyrusAdmin("CUSTOMER" as never, "user.ban"), false);
  });
  it("GDPR plan: financial tables are retained, counts summed per policy, missing tables shown as null", () => {
    const counts: Record<string, number | null> = Object.fromEntries(CYRUS_GDPR_TABLES.map((t) => [t.model, 1]));
    counts.cyrusCreator = null;
    const p = gdprPlan(counts);
    for (const m of ["cyrusTokenLedger", "cyrusTokenLot", "cyrusTokenReservation", "cyrusPlan", "cyrusTokenAccount"]) assert.equal(p.rows.find((r) => r.model === m)!.policy, "retain", m);
    assert.equal(p.retain, 5);
    assert.equal(p.rows.find((r) => r.model === "cyrusCreator")!.rows, null);
    assert.equal(p.delete + p.anonymise + p.retain, CYRUS_GDPR_TABLES.length - 1);
  });
  it("GDPR erasure is off unless CYRUS_GDPR_ERASE=1; anon ids are stable per salt and not the user id", () => {
    assert.equal(gdprEraseEnabled({}), false);
    assert.equal(gdprEraseEnabled({ CYRUS_GDPR_ERASE: "true" }), false);
    assert.equal(gdprEraseEnabled({ CYRUS_GDPR_ERASE: "1" }), true);
    assert.equal(ANON_USER("u1", "s"), ANON_USER("u1", "s"));
    assert.notEqual(ANON_USER("u1", "s"), ANON_USER("u1", "t"));
    assert.ok(!ANON_USER("u1", "s").includes("u1"));
  });
});

