export interface LibraryRecords {
  derivatives: {
    get(entryId: string, recipe: RecipeId): Promise<DerivativeRow | null>;
    put(row: DerivativeRow): Promise<void>;
    touch(entryId: string, recipe: RecipeId, at: Date): Promise<void>;
    unusedSince(cutoff: Date, limit: number): Promise<DerivativeRow[]>;
    forEntry(entryId: string): Promise<DerivativeRow[]>;
    delete(entryId: string, recipe: RecipeId): Promise<void>;
    /** rows still pointing at an object (a derivative object may be shared by identical outputs) */
    refs(objectKey: string): Promise<number>;
  };
  uses: {
    upsert(row: Omit<UseRow, "createdAt" | "updatedAt" | "upstream"> & { upstream?: CatalogStatus }, at: Date): Promise<UseRow>;
    get(projectId: string, slotId: string): Promise<UseRow | null>;
    forEntry(entryId: string): Promise<UseRow[]>;
    /** sets `upstream` on every use of the entry; returns how many dependents were marked */
    markUpstream(entryId: string, status: CatalogStatus, at: Date): Promise<number>;
  };
  reports: {
    /** one open report per (entry, reporter): a second one from the same reporter is not counted again */
    add(r: Omit<ReportRow, "id" | "status" | "resolvedAt" | "resolvedBy">): Promise<{ row: ReportRow; created: boolean }>;
    open(entryId?: string, limit?: number): Promise<ReportRow[]>;
    /** AC-5: one reporter's reports (any status) created since `since`, newest first, at most 500 */
    byReporter(reporter: string, since: Date): Promise<ReportRow[]>;
    resolve(entryId: string, status: "actioned" | "dismissed", by: string, at: Date): Promise<number>;
  };
  log: {
    append(r: Omit<ModerationRow, "id">): Promise<ModerationRow>;
    list(q: { actions?: readonly ModAction[]; entryId?: string; limit?: number }): Promise<ModerationRow[]>;
  };
  fingerprints: {
    put(r: FingerprintRow): Promise<void>;
    /** every row of the kind + method whose fp shares at least one 16-bit band with `fp` (hex), or equals it (facts) */
    candidates(kind: CatalogKind, method: FingerprintRow["method"], fp: string): Promise<FingerprintRow[]>;
  };
}

lib/cyrus/library/v2/filters.ts:86:export async function runContentFilters(e: CatalogEntry, ctx: FilterContext, filters: readonly ContentFilter[] = defaultFilters()): Promise<FilterDecision> {
export function defaultFilters(): ContentFilter[] {
  return [
    {
      id: "eligibility",
      check(e, ctx) {
        if (e.licence.tier !== "user-contributed") return [];
        const ok = libraryEligible({ legalClass: e.legalClass, provenance: { source: ctx.provenanceSource ?? "user", derivedFrom: [...(ctx.derivedFrom ?? [])] } });
        return ok ? [] : [{ rule: "eligibility", severity: "reject", field: "legalClass", match: e.legalClass, message: "not eligible for the community library (imported, uploaded, template or derived content)" }];
      },
    },
    {
      id: "not-an-asset",
      check: (e) => (e.enrichment.gaps.includes("pack preview image") ? [{ rule: "not-an-asset", severity: "reject" as const, field: "path", match: e.provenance.path ?? "", message: "pack cover / preview image, not an asset" }] : []),
    },
    wordListFilter("adult", R.adult, () => "reject", "adult content terms"),
    wordListFilter("extremist", R.extremist, (_e, ctx) => (ctx.strict ? "reject" : "hold"), "extremist symbol terms"),
    wordListFilter("real-weapon", R.realWeapons, (_e, ctx) => (ctx.strict ? "hold" : "flag"), "named after a real firearm model (trademark): owner review", ["title", "shortDescription", "tags", "freeTags", "path"]),
    wordListFilter("trademark", R.trademarks, (e, ctx) => {
      const prompts = e.categories.primary === "ui/input-prompts";
      return prompts || !ctx.strict ? "flag" : "hold";
    }, "names a trademark or a game's own content (stub list): owner review"),
    // community assets with gore are HELD for the owner (r26, task: hold queue for trademark / real-weapon / mature); pack assets only flagged
    wordListFilter("mature-violence", R.matureViolence, (_e, ctx) => (ctx.strict ? "hold" : "flag"), "gore / blood (mature violence): owner review for community assets"),
    wordListFilter("drugs", R.drugs, (_e, ctx) => (ctx.strict ? "hold" : "flag"), "drug references"),
  ];
}

const RANK: Record<FilterSeverity, number> = { flag: 0, hold: 1, reject: 2 };

/** pending-checks -> published | held | removed. Entries already held/removed are never auto-published. */
