// Cyrus r31: the studios' AUTOMATIC contribution hook (owner decision: assets made in Cyrus join the library, no opt-in).
// A studio save hands in what it made; this runs contributeAsset (./contribute.ts: eligibility, dedupe, strict filters,
// hold queue) in the background and NEVER fails or slows the save. Off unless CYRUS_LIBRARY_BACKEND=1 +
// CYRUS_LIBRARY_CONTRIBUTE=1 + a URL secret (the opaque contributor id is an HMAC of the user id with it) + an object
// store. Wired: the Texture Studio save (the rendered PNG). Not wired: sound (no portal-side render), model / meshgen
// (no glb export path), motion (presets are not studio files yet).
// HOST SEAM: no Nxeon imports beyond the library runtime (lib/cyrus).
import { createHmac } from "node:crypto";
import { minecraftAssetProfile } from "../../adapters/minecraft";
import type { AssetManifest } from "../../assets3d/manifest";
import { contributeAsset, type ContributionInput, type ContributionOutcome } from "./contribute";
import { libraryFlags, type Env } from "./flags";
import { libraryHttpDeps, libraryObjectStore } from "./runtime";

export type StudioContribution = Omit<ContributionInput, "contributorId" | "manifest"> & { userId: string; manifest: Pick<AssetManifest, "legalClass" | "provenance"> };
export type Contributor = (c: StudioContribution) => void;

export const contributorIdOf = (secret: string, userId: string) => `u_${createHmac("sha256", secret).update(`cyrus-contrib:${userId}`).digest("hex").slice(0, 40)}`;

/** The hook, or undefined when contribution is off (the studios then do nothing extra). */
export function studioContributor(env: Env = process.env, onOutcome?: (o: ContributionOutcome) => void): Contributor | undefined {
  const flags = libraryFlags(env);
  if (!flags.contribute || !flags.urlSecret) return undefined;
  const secret = flags.urlSecret;
  const http = libraryHttpDeps(env);
  return (c) => {
    void (async () => {
      const b = http.backend();
      const objects = libraryObjectStore(env);
      if (!b || !objects) return;
      const { userId, ...rest } = c;
      const o = await contributeAsset({ ...rest, contributorId: contributorIdOf(secret, userId) }, { enabled: true, catalog: b.catalog, index: b.index, objects, records: b.records, profiles: [minecraftAssetProfile], now: () => new Date() });
      onOutcome?.(o);
    })().catch((e) => console.error("[cyrus-library] contribution:", (e as Error).message));
  };
}

