// Cyrus legal cases (r40): the takedown / DMCA log and the counter-notice workflow. PURE state machine, unit-tested in
// test/cyrus-admin-r40.test.ts; the admin actions (lib/actions-cyrus-admin-library.ts) persist cases in CyrusLegalCase
// and run the library takedown / restore through lib/cyrus/library/backend/moderation.ts.
//
// Flow (modelled on 17 U.S.C. 512(g); NOT legal advice: the owner's lawyer confirms the wording and the periods):
//   notice_received --takedown--> taken_down --counter--> counter_received --restore (10..14 business days)--> restored
//   notice_received --reject (incomplete / invalid notice)--> closed
//   any open state  --withdraw (claimant withdraws)--> closed;   counter_received --suit (claimant sues)--> closed
// A restore before the 10th business day after the counter-notice is refused; after the 14th the case is flagged late.
// Restoring a library asset puts it back to HELD (moderation.restore), never straight to published.

export type LegalCaseStatus = "notice_received" | "taken_down" | "counter_received" | "restored" | "closed";
export type LegalEvent = "takedown" | "reject" | "counter" | "restore" | "suit" | "withdraw";
export const LEGAL_EVENTS: LegalEvent[] = ["takedown", "reject", "counter", "restore", "suit", "withdraw"];
export const COUNTER_MIN_BUSINESS_DAYS = 10;
export const COUNTER_MAX_BUSINESS_DAYS = 14;

export type LegalHistory = { at: string; by: string; event: LegalEvent | "notice"; note: string | null };
export type LegalCase = {
  id: string; kind: "dmca" | "trademark" | "other"; status: LegalCaseStatus;
  target: string; entryId: string | null; claimant: string; claimantContact: string | null; work: string;
  noticeAt: Date; takedownAt: Date | null; counterAt: Date | null; counterBy: string | null; counterStatement: string | null;
