// Cyrus admin r40: library moderation helpers. PURE parts (near-duplicate ranking, contribution stats) + the server
// wiring of the moderation deps (Cyrus' own Postgres tables through lib/cyrus/db.ts; no object store needed to decide).
import { hamming64, NEAR_HAMMING } from "../library/backend/fingerprint";
import type { ModerationDeps } from "../library/backend/moderation";

export type FpRow = { entryId: string; kind: string; method: string; fp: string };
export type NearDup = { entryId: string; method: string; distance: number; exact: boolean };

/** Rank candidate fingerprints against one entry's own: same kind + method; facts = equal only; 64-bit = Hamming <= max. */
export function nearDuplicates(self: FpRow, candidates: FpRow[], max = NEAR_HAMMING): NearDup[] {
  const out: NearDup[] = [];
  for (const c of candidates) {
    if (c.entryId === self.entryId || c.kind !== self.kind || c.method !== self.method) continue;
    if (self.method === "facts") { if (c.fp === self.fp) out.push({ entryId: c.entryId, method: c.method, distance: 0, exact: true }); continue; }
    if (!/^[0-9a-f]{16}$/.test(c.fp) || !/^[0-9a-f]{16}$/.test(self.fp)) continue;
    const d = hamming64(self.fp, c.fp);
    if (d <= max) out.push({ entryId: c.entryId, method: c.method, distance: d, exact: d === 0 });
  }
  return out.sort((a, b) => a.distance - b.distance || a.entryId.localeCompare(b.entryId)).slice(0, 50);
}

export type ContribRow = { contributorId: string | null; status: string; kind: string; createdAt: Date };
export type ContribStats = {
  total: number; byStatus: Record<string, number>; byKind: Record<string, number>; contributors: number;
  top: { contributorId: string; n: number; held: number; removed: number }[];
  perDay: { day: string; n: number }[]; holdRate: number | null;
};

/** Community contribution stats (user-contributed rows only), `days` per-day buckets ending today (UTC). */
export function contributionStats(rows: ContribRow[], now: Date, days = 30): ContribStats {
  const byStatus: Record<string, number> = {}, byKind: Record<string, number> = {};
  const per = new Map<string, { n: number; held: number; removed: number }>();
  const dayN = new Map<string, number>();
  for (const r of rows) {
    byStatus[r.status] = (byStatus[r.status] ?? 0) + 1;
    byKind[r.kind] = (byKind[r.kind] ?? 0) + 1;
    if (r.contributorId) {
      const p = per.get(r.contributorId) ?? { n: 0, held: 0, removed: 0 };
      p.n++; if (r.status === "held") p.held++; if (r.status === "removed") p.removed++;
      per.set(r.contributorId, p);
    }
    const k = r.createdAt.toISOString().slice(0, 10);
    dayN.set(k, (dayN.get(k) ?? 0) + 1);
  }
  const perDay: { day: string; n: number }[] = [];
  for (let i = days - 1; i >= 0; i--) {
    const k = new Date(now.getTime() - i * 86_400_000).toISOString().slice(0, 10);
    perDay.push({ day: k, n: dayN.get(k) ?? 0 });
  }
  const decided = (byStatus.published ?? 0) + (byStatus.held ?? 0) + (byStatus.removed ?? 0);
  return {
    total: rows.length, byStatus, byKind, contributors: per.size,
    top: [...per.entries()].map(([contributorId, v]) => ({ contributorId, ...v })).sort((a, b) => b.n - a.n).slice(0, 20),
    perDay, holdRate: decided ? (byStatus.held ?? 0) / decided : null,
  };
}

/** Moderation deps over the real tables. Server only (lazy import keeps this module's pure parts DB-free). */
export async function moderationDeps(): Promise<ModerationDeps> {
  const { pgLibrary } = await import("../library/backend/runtime");
  const pg = pgLibrary();
  return { catalog: pg.store, index: pg.index, records: pg.records, now: () => new Date() };
}

