  params.delete("ok"); params.delete("err");
  params.set(kind, msg.slice(0, 300));
  redirect(`${p}?${params.toString()}`);
}

async function guard(action: CyrusAdminAction, fd: FormData): Promise<User> {
  const admin = await requireArea(CYRUS_ADMIN_ACTIONS[action]);
  if (await impersonating()) redirect("/dashboard");
  if (!(await isPreviewUser(await realUser(), "modbuilder"))) notFound();
  if (!libraryFlags().enabled) go(fd, "err", "The library backend is off (CYRUS_LIBRARY_BACKEND).");
  return admin;
}

const by = (u: User) => `owner:${u.id}`;

function entryOf(fd: FormData) {
  const id = str(fd, "entryId", 64);
  return SHA.test(id) ? id : null;
}

/** Hold queue: approve (held -> published), reject (held -> removed, not legal), remove (any -> removed, optionally legal). */
export async function adminCyrusLibraryDecide(fd: FormData) {
  const decision = str(fd, "decision", 10);
  const action: CyrusAdminAction = decision === "approve" ? "library.release" : decision === "reject" ? "library.reject" : decision === "remove" ? "library.takedown" : decision === "restore" ? "library.restore" : "library.release";
  const admin = await guard(action, fd);
  const id = entryOf(fd);
  if (!id) go(fd, "err", "Bad asset id.");
  const note = str(fd, "note", 280);
  const d = await moderationDeps();
  if (decision === "approve") {
    const r = await release(d, { entryId: id, by: by(admin), note: note || undefined });
    if (!r.ok) go(fd, "err", r.error);
    await cyrusAudit({ actorId: admin.id, action, target: `library:${id}`, before: { status: "held" }, after: { status: "published" }, note });
    go(fd, "ok", `Approved: “${r.entry.title}” is published.`);
  }
  if (decision === "reject" || decision === "remove") {
    if (note.length < 3) go(fd, "err", "Give a reason (kept in the moderation log).");
    const legal = decision === "remove" && (fd.get("legal") === "1" || fd.get("legal") === "on");
    const r = await takedown(d, { entryId: id, by: by(admin), reason: decision === "reject" ? `rejected: ${note}` : note, legal });
    if (!r.ok) go(fd, "err", r.error);
    await cyrusAudit({ actorId: admin.id, action, target: `library:${id}`, after: { status: "removed", legal, dependents: r.dependents, purged: r.purged }, note });
    go(fd, "ok", `${decision === "reject" ? "Rejected" : "Removed"}: “${r.entry.title}”. ${r.dependents} project(s) using it keep their own copy.`);
  }
  if (decision === "restore") {
    if (note.length < 3) go(fd, "err", "Give a reason.");
    const r = await restore(d, { entryId: id, by: by(admin), reason: note });
    if (!r.ok) go(fd, "err", r.error);
    await cyrusAudit({ actorId: admin.id, action, target: `library:${id}`, before: { status: "removed" }, after: { status: "held" }, note });
    go(fd, "ok", `Restored to the hold queue: “${r.entry.title}”.`);
  }
  go(fd, "err", "Pick approve, reject, remove or restore.");
}

/** Dismiss open reports on an asset (it stays as it is; the moderation log records the dismissal). */
export async function adminCyrusLibraryDismissReports(fd: FormData) {
  const admin = await guard("library.reports.dismiss", fd);
  const id = entryOf(fd);
  if (!id) go(fd, "err", "Bad asset id.");
  const d = await moderationDeps();
  const now = new Date();
  const n = await d.records.reports.resolve(id, "dismissed", by(admin), now);
  if (n) await d.records.log.append({ entryId: id, action: "dismiss", from: null, to: null, by: by(admin), reason: str(fd, "note", 280) || null, legal: false, dependents: 0, at: now });
  await cyrusAudit({ actorId: admin.id, action: "library.reports.dismiss", target: `library:${id}`, after: { dismissed: n }, note: str(fd, "note") });
  go(fd, "ok", n ? `${n} report(s) dismissed.` : "No open reports on that asset.");
}

/** Real-weapon / trademark list editor: add or remove one term. Applies to NEW contributions (existing rows unchanged). */
export async function adminCyrusLibraryListEdit(fd: FormData) {
  const admin = await requireArea(CYRUS_ADMIN_ACTIONS["library.lists"]);
  if (await impersonating()) redirect("/dashboard");
  if (!(await isPreviewUser(await realUser(), "modbuilder"))) notFound();
  const list = str(fd, "list", 20) as FilterListName;
  if (!FILTER_LIST_NAMES.includes(list)) go(fd, "err", "Pick a list.");
  const op = str(fd, "op", 10);
  const term = str(fd, "term", 60).toLowerCase();
  if (!validFilterTerm(term)) go(fd, "err", "A term is 1-60 letters, digits, spaces or . ' & + -");
  const row = await db.setting.findUnique({ where: { key: FILTER_LISTS_SETTING } });
  const ov = parseFilterOverrides(row?.value);
  const cur = { add: [...(ov[list]?.add ?? [])], remove: [...(ov[list]?.remove ?? [])] };
  const before = JSON.parse(JSON.stringify(cur));
  if (op === "add") { cur.remove = cur.remove.filter((t) => t !== term); if (!cur.add.includes(term)) cur.add.push(term); }
  else if (op === "remove") { cur.add = cur.add.filter((t) => t !== term); if (!cur.remove.includes(term)) cur.remove.push(term); }
  else if (op === "reset") { cur.add = cur.add.filter((t) => t !== term); cur.remove = cur.remove.filter((t) => t !== term); }
  else go(fd, "err", "Pick add, remove or reset.");
  const next = { ...ov, [list]: cur };
  const value = JSON.stringify(next);
  await db.setting.upsert({ where: { key: FILTER_LISTS_SETTING }, update: { value }, create: { key: FILTER_LISTS_SETTING, value } });
  await cyrusAudit({ actorId: admin.id, action: "library.lists", target: `setting:${FILTER_LISTS_SETTING}:${list}`, before, after: cur, note: `${op} ${term}` });
  go(fd, "ok", `${list === "realWeapons" ? "Real-weapon" : "Trademark"} list: ${op} “${term}”. Applies to new contributions.`);
}

// ── legal cases ─────────────────────────────────────────────────────────────

/** Log a new notice (DMCA / trademark / other). Nothing is taken down until the "takedown" step. */
export async function adminCyrusLegalOpen(fd: FormData) {
  const admin = await requireArea(CYRUS_ADMIN_ACTIONS["legal.case"]);
  if (await impersonating()) redirect("/dashboard");
  if (!(await isPreviewUser(await realUser(), "modbuilder"))) notFound();
  const at = str(fd, "noticeAt", 10);
  const v = validateNotice({ kind: str(fd, "kind", 12), target: str(fd, "target", 120), claimant: str(fd, "claimant", 200), claimantContact: str(fd, "contact", 200), work: str(fd, "work", 1000), noticeAt: /^\d{4}-\d{2}-\d{2}$/.test(at) ? new Date(`${at}T12:00:00Z`) : null });
  if (!v.ok) go(fd, "err", v.error);
  const id = `lc_${randomBytes(8).toString("hex")}`;
  try {
    await db.cyrusLegalCase.create({ data: { id, ...v.value, status: "notice_received", history: [{ at: new Date().toISOString(), by: by(admin), event: "notice", note: null }] } });
  } catch {
    go(fd, "err", "The legal-case table is not migrated yet (prisma/manual-migrations/2026-10-11-cyrus-legal-cases.sql).");
  }
  await cyrusAudit({ actorId: admin.id, action: "legal.case", target: `legal:${id}`, after: { event: "notice", kind: v.value.kind, target: v.value.target, claimant: v.value.claimant } });
  go(fd, "ok", `Case ${id} opened. Next: take down or reject.`);
}

/** Move a case on (takedown, reject, counter, restore, suit, withdraw); runs the library takedown / restore with it. */
export async function adminCyrusLegalEvent(fd: FormData) {
  const admin = await requireArea(CYRUS_ADMIN_ACTIONS["legal.case"]);
  if (await impersonating()) redirect("/dashboard");
  if (!(await isPreviewUser(await realUser(), "modbuilder"))) notFound();
  const ev = str(fd, "event", 12) as LegalEvent;
  if (!LEGAL_EVENTS.includes(ev)) go(fd, "err", "Unknown step.");
  const id = str(fd, "caseId", 40);
  const row = await db.cyrusLegalCase.findUnique({ where: { id } }).catch(() => null);
  if (!row) go(fd, "err", "No such case.");
  const c: LegalCase = caseFromRow(row as unknown as Record<string, unknown>);
  const now = new Date();
  const t = legalTransition(c, ev, { by: by(admin), at: now, note: str(fd, "note", 500), counterBy: str(fd, "counterBy", 80), statement: str(fd, "statement", 4000) });
  if (!t.ok) go(fd, "err", t.error);
  if (t.library) {
    if (!libraryFlags().enabled) go(fd, "err", "The library backend is off (CYRUS_LIBRARY_BACKEND): the asset cannot be changed, so the case did not move.");
    const d = await moderationDeps();
    const r = t.library === "takedown"
      ? await takedown(d, { entryId: c.entryId!, by: by(admin), reason: `${c.kind} notice ${c.id} (${c.claimant})`, legal: true })
      : await restore(d, { entryId: c.entryId!, by: by(admin), reason: `${ev === "withdraw" ? "notice withdrawn" : "counter-notice period passed"} (${c.id})` });
    if (!r.ok && !(r.code === "bad_state")) go(fd, "err", `Library: ${r.error}`);
  }
  const n = t.next;
  await db.cyrusLegalCase.update({ where: { id }, data: { status: n.status, takedownAt: n.takedownAt, counterAt: n.counterAt, counterBy: n.counterBy, counterStatement: n.counterStatement, restoreEligibleAt: n.restoreEligibleAt, closedAt: n.closedAt, outcome: n.outcome, history: n.history as never } });
  await cyrusAudit({ actorId: admin.id, action: "legal.case", target: `legal:${id}`, before: { status: c.status }, after: { status: n.status, event: ev, library: t.library, late: !!t.late }, note: str(fd, "note") });
  go(fd, "ok", `Case ${id}: ${ev} done (now ${n.status.replace("_", " ")})${t.late ? ". Note: restored after the 14 business-day window" : ""}.`);
}
