import { Empty, Flash, Hidden, Section, TableWrap, n, pct, tdRow, thCls, when } from "@/components/admin/cyrus/ui";

export const dynamic = "force-dynamic";
export async function generateMetadata(): Promise<Metadata> {
  return cyrusAdminMetadata("Library hold queue");
}

const BACK = "/admin/cyrus/library/holds";

async function NearDupPanel({ id }: { id: string }) {
  const self = await cyrusDb.cyrusLibraryFingerprint.findUnique({ where: { entryId: id } }).catch(() => null);
  if (!self) return <Section title="Near duplicates" sub={<span className="font-mono">{id.slice(0, 16)}</span>}><Empty>No fingerprint for this asset (only community contributions are fingerprinted).</Empty></Section>;
  const d = await moderationDeps();
  const cands = await d.records.fingerprints.candidates(self.kind as never, self.method as never, self.fp);
  const near = nearDuplicates(self, cands);
  const entries = near.length ? await d.catalog.getMany(near.map((x) => x.entryId)) : [];
  const byId = new Map(entries.map((e) => [e.id, e]));
  return (
    <Section title="Near duplicates" sub={<>Same {self.kind}, {self.method} fingerprint within the near threshold of <span className="font-mono">{id.slice(0, 16)}</span>. Exact = same fingerprint.</>}>
      {near.length === 0 ? <Empty>No near copies found.</Empty> : (
        <TableWrap>
          <table className="w-full text-sm">
            <thead><tr className={thCls}><th>Asset</th><th>Status</th><th className="text-right">Distance</th><th>Decide</th></tr></thead>
            <tbody>{near.map((x) => { const e = byId.get(x.entryId); return (
              <tr key={x.entryId} className={tdRow}>
                <td><div>{e?.title ?? "(missing)"}</div><div className="font-mono text-[11px] text-slate-500">{x.entryId.slice(0, 16)}</div></td>
                <td>{e?.status ?? "–"}</td>
                <td className="text-right tabular-nums">{x.exact ? "exact" : x.distance}</td>
                <td>{e && e.status !== "removed" ? (
                  <form action={adminCyrusLibraryDecide} className="flex flex-wrap gap-1">
                    <Hidden name="entryId" value={x.entryId} /><Hidden name="decision" value="remove" /><Hidden name="back" value={`${BACK}?dup=${id}`} />
                    <input name="note" placeholder="Reason" className="input w-36 text-xs" required minLength={3} />
                    <button className="btn-danger text-xs">Remove copy</button>
                  </form>
                ) : null}</td>
              </tr>
            ); })}</tbody>
          </table>
        </TableWrap>
      )}
    </Section>
  );
}

/**
 * Cyrus r40: the owner's hold queue for AUTOMATIC library contributions (real-weapon, trademark, extremist, drugs, mature
 * violence, near-copies of removed assets, quality hard fails) with approve / reject / remove, open reports, the
 * moderation log with restore, near-duplicate lookup and contribution stats. Off while CYRUS_LIBRARY_BACKEND is unset
 * or its tables do not exist.
 */
export default async function LibraryHolds({ searchParams }: { searchParams: Promise<Record<string, string | string[] | undefined>> }) {
  await requireCyrusAdmin("library");
  const sp = await searchParams;
  const dup = typeof sp.dup === "string" && /^[0-9a-f]{64}$/.test(sp.dup) ? sp.dup : null;
  const on = libraryFlags().enabled;
  const v = on ? await libraryAdminRead({ limit: 100 }).catch((e: Error) => ({ error: e.message })) : null;
  if (!v || "error" in v) {
    return <div><LibraryNav current="holds" /><Flash sp={sp} /><Section title="Library hold queue"><Empty>{!on ? "The library backend is off (CYRUS_LIBRARY_BACKEND). Nothing to review until it is switched on and its tables are migrated." : `Could not read the library tables: ${(v as { error: string }).error.slice(0, 200)}`}</Empty></Section></div>;
  }
  const now = new Date();
  const contrib = await cyrusDb.cyrusCatalogEntry.findMany({ where: { tier: "user-contributed" }, select: { contributorId: true, status: true, kind: true, createdAt: true }, take: 20000 }).catch(() => []);
  const stats = contributionStats(contrib, now, 14);
  const max = Math.max(1, ...stats.perDay.map((d) => d.n));
  return (
    <div className="space-y-6">
      <LibraryNav current="holds" />
      <Flash sp={sp} />
      <div className="grid grid-cols-2 gap-3 lg:grid-cols-4">
        <StatCard label="Entries" value={n(v.total)} />
        <StatCard label="Held" value={n(v.byStatus.held ?? 0)} />
        <StatCard label="Open reports" value={n(v.openReports)} />
        <StatCard label="Mods using removed assets" value={n(v.dependentsOfRemoved)} delta="they keep their own copy" />
      </div>
      {dup ? <NearDupPanel id={dup} /> : null}
      <Section title={`Hold queue (${v.holdQueue.length})`} sub="Approve publishes it (hold flags become cleared:<rule>, still visible). Reject removes it (not a legal takedown). Each decision is logged and audited.">
        {v.holdQueue.length === 0 ? <Empty>Nothing is waiting for review.</Empty> : (
          <ul className="space-y-3">{v.holdQueue.map((h) => (
            <li key={h.id} className="rounded-lg border border-white/[0.08] p-3">
              <div className="flex flex-wrap items-start justify-between gap-2">
                <div className="min-w-0">
                  <p className="font-medium">{h.title}</p>
                  <p className="font-mono text-[11px] text-slate-500">{h.id.slice(0, 16)} · {h.kind} · {h.tier} · {h.contributor ?? "library"}</p>
                  <p className="mt-1 text-sm text-slate-300">{h.reason ?? "–"}</p>
                  <div className="mt-1 flex flex-wrap gap-1">{h.flags.map((f) => <Badge key={f} tone={f.startsWith("hold:") ? "amber" : "slate"}>{f}</Badge>)}{h.reports ? <Badge tone="red">{h.reports} report(s)</Badge> : null}</div>
                </div>
                <Link className="btn-ghost text-xs" href={`${BACK}?dup=${h.id}`}>Near copies</Link>
              </div>
              <div className="mt-2 flex flex-wrap gap-2">
                <form action={adminCyrusLibraryDecide} className="flex flex-wrap gap-1">
                  <Hidden name="entryId" value={h.id} /><Hidden name="decision" value="approve" /><Hidden name="back" value={BACK} />
                  <input name="note" placeholder="Note (optional)" className="input w-40 text-xs" />
                  <button className="btn-primary text-xs">Approve</button>
                </form>
                <form action={adminCyrusLibraryDecide} className="flex flex-wrap gap-1">
                  <Hidden name="entryId" value={h.id} /><Hidden name="decision" value="reject" /><Hidden name="back" value={BACK} />
                  <input name="note" placeholder="Why rejected" className="input w-40 text-xs" required minLength={3} />
                  <button className="btn-danger text-xs">Reject</button>
                </form>
                {h.reports ? (
                  <form action={adminCyrusLibraryDismissReports}><Hidden name="entryId" value={h.id} /><Hidden name="back" value={BACK} /><button className="btn-secondary text-xs">Dismiss reports</button></form>
                ) : null}
              </div>
            </li>
          ))}</ul>
        )}
      </Section>
      <Section title="Contributions" sub="Automatic community contributions (user-contributed rows). Contributor ids are opaque (HMAC of the account id).">
        {stats.total === 0 ? <Empty>No community contributions yet.</Empty> : (
          <div className="grid gap-4 lg:grid-cols-2">
            <div className="text-sm">
              <p>{n(stats.total)} contributions from {n(stats.contributors)} contributors · hold rate {pct(stats.holdRate)}</p>
              <p className="mt-1 text-xs text-slate-400">{Object.entries(stats.byStatus).map(([k, x]) => `${k} ${x}`).join(" · ")}</p>
              <p className="text-xs text-slate-400">{Object.entries(stats.byKind).map(([k, x]) => `${k} ${x}`).join(" · ")}</p>
              <div className="mt-3 flex h-16 items-end gap-1" aria-label="Contributions per day, 14 days">{stats.perDay.map((d) => <div key={d.day} title={`${d.day}: ${d.n}`} className="flex-1 rounded-sm bg-white/30" style={{ height: `${Math.max(2, (d.n / max) * 100)}%` }} />)}</div>
            </div>
            <TableWrap>
              <table className="w-full text-xs">
                <thead><tr className={thCls}><th>Contributor</th><th className="text-right">Assets</th><th className="text-right">Held</th><th className="text-right">Removed</th></tr></thead>
                <tbody>{stats.top.map((t) => <tr key={t.contributorId} className={tdRow}><td className="font-mono">{t.contributorId.slice(0, 18)}</td><td className="text-right">{t.n}</td><td className="text-right">{t.held}</td><td className="text-right">{t.removed}</td></tr>)}</tbody>
              </table>
            </TableWrap>
          </div>
        )}
      </Section>
      <Section title="Takedown and moderation log" sub="Removed assets can go back to the hold queue (never straight to published). Legal cases: Takedowns & DMCA.">
        {v.takedownLog.length === 0 ? <Empty>No moderation actions yet.</Empty> : (
          <TableWrap>
            <table className="w-full text-sm">
              <thead><tr className={thCls}><th>When</th><th>Entry</th><th>Action</th><th>By</th><th>Reason</th><th className="text-right">Dependents</th><th /></tr></thead>
              <tbody>{v.takedownLog.map((l, i) => (
                <tr key={i} className={tdRow}>
                  <td className="whitespace-nowrap text-xs">{when(l.at)}</td><td className="font-mono text-[11px]">{l.entryId.slice(0, 16)}</td>
                  <td>{l.action}{l.legal ? <Badge tone="red">legal</Badge> : null}</td><td className="text-xs">{l.by}</td><td className="text-xs">{l.reason ?? "–"}</td><td className="text-right">{l.dependents}</td>
                  <td>{l.action === "takedown" && !l.legal ? (
                    <form action={adminCyrusLibraryDecide} className="flex gap-1"><Hidden name="entryId" value={l.entryId} /><Hidden name="decision" value="restore" /><Hidden name="back" value={BACK} /><input name="note" placeholder="Why" className="input w-24 text-xs" required minLength={3} /><button className="btn-secondary text-xs">Restore</button></form>
                  ) : null}</td>
                </tr>
              ))}</tbody>
            </table>
          </TableWrap>
        )}
      </Section>
    </div>
  );
}

