import type { Metadata } from "next";
import { requireCyrusAdmin, cyrusAdminMetadata } from "@/lib/cyrus/admin/gate";
import { cyrusDb } from "@/lib/cyrus/db";
import { caseFromRow, COUNTER_MAX_BUSINESS_DAYS, COUNTER_MIN_BUSINESS_DAYS, legalDue, type LegalCase } from "@/lib/cyrus/admin/dmca";
import { adminCyrusLegalEvent, adminCyrusLegalOpen } from "@/lib/actions-cyrus-admin-library";
import { Badge } from "@/components/ui/primitives";
import { LibraryNav } from "@/components/admin/cyrus/LibraryNav";
import { Empty, Flash, Hidden, Kv, Section, when } from "@/components/admin/cyrus/ui";

export const dynamic = "force-dynamic";
export async function generateMetadata(): Promise<Metadata> {
  return cyrusAdminMetadata("Takedowns and DMCA");
}

const BACK = "/admin/cyrus/library/legal";
const TONE: Record<LegalCase["status"], "red" | "amber" | "green" | "slate"> = { notice_received: "red", taken_down: "amber", counter_received: "amber", restored: "green", closed: "slate" };

function Step({ c, ev, label, danger, children }: { c: LegalCase; ev: string; label: string; danger?: boolean; children?: React.ReactNode }) {
  return (
    <form action={adminCyrusLegalEvent} className="flex flex-col gap-1 sm:flex-row sm:flex-wrap sm:items-center">
      <Hidden name="caseId" value={c.id} /><Hidden name="event" value={ev} /><Hidden name="back" value={BACK} />
      {children}
      <input name="note" placeholder="Note" className="input text-xs sm:w-44" />
      <button className={`${danger ? "btn-danger" : "btn-secondary"} text-xs`}>{label}</button>
    </form>
  );
}

/** Cyrus r40: legal notices (DMCA / trademark), the takedown they cause, and the counter-notice workflow. */
export default async function LegalCases({ searchParams }: { searchParams: Promise<Record<string, string | string[] | undefined>> }) {
  await requireCyrusAdmin("library");
  const sp = await searchParams;
  const rows = await cyrusDb.cyrusLegalCase.findMany({ orderBy: { noticeAt: "desc" }, take: 200 }).catch(() => null);
  const cases = rows?.map((r) => caseFromRow(r as unknown as Record<string, unknown>)) ?? [];
  const due = legalDue(cases, new Date());
  return (
    <div className="space-y-6">
      <LibraryNav current="legal" />
      <Flash sp={sp} />
      {rows === null ? <Section title="Takedowns & DMCA"><Empty>The legal-case table is not migrated yet (prisma/manual-migrations/2026-10-11-cyrus-legal-cases.sql). Library takedowns still work from the hold queue.</Empty></Section> : null}
      <Section title="Due" sub={`Restore is allowed ${COUNTER_MIN_BUSINESS_DAYS} business days after a counter-notice and expected by day ${COUNTER_MAX_BUSINESS_DAYS}, unless the claimant has filed an action. Public holidays are not counted for you. Not legal advice: the wording and periods need the owner's lawyer.`}>
        {due.length === 0 ? <Empty>Nothing due.</Empty> : <ul className="space-y-1 text-sm">{due.map((d) => <li key={d.id + d.text} className="flex gap-2"><Badge tone={d.level}>{d.level === "red" ? "now" : "can act"}</Badge><span className="font-mono text-xs">{d.id}</span><span>{d.text}</span></li>)}</ul>}
      </Section>
      <Section title="Log a notice" sub="Records the notice only. The asset stays up until you take the takedown step.">
        <form action={adminCyrusLegalOpen} className="grid gap-2 sm:grid-cols-2">
          <Hidden name="back" value={BACK} />
          <select name="kind" className="input text-sm" defaultValue="dmca" aria-label="Kind"><option value="dmca">DMCA (copyright)</option><option value="trademark">Trademark</option><option value="other">Other</option></select>
          <input name="target" placeholder="Library asset id (sha256) or page:<slug> / mod:<id>" className="input text-sm" required />
          <input name="claimant" placeholder="Claimant (name / company)" className="input text-sm" required />
          <input name="contact" placeholder="Claimant contact (email / address)" className="input text-sm" />
          <input name="noticeAt" type="date" className="input text-sm" aria-label="Received on" />
          <textarea name="work" placeholder="The work they claim, as described in the notice" className="input text-sm sm:col-span-2" rows={2} required />
          <button className="btn-primary text-sm sm:col-span-2 sm:w-40">Open case</button>
        </form>
      </Section>
      <Section title={`Cases (${cases.length})`}>
        {cases.length === 0 ? <Empty>No legal cases logged.</Empty> : (
          <ul className="space-y-3">{cases.map((c) => (
            <li key={c.id} className="rounded-lg border border-white/[0.08] p-3">
              <div className="mb-2 flex flex-wrap items-center gap-2"><Badge tone={TONE[c.status]}>{c.status.replace("_", " ")}</Badge><span className="text-sm font-medium">{c.kind.toUpperCase()} · {c.claimant}</span><span className="font-mono text-xs text-slate-500">{c.id} · {c.target.slice(0, 30)}</span></div>
              <Kv rows={[["Work", c.work], ["Notice", when(c.noticeAt)], ["Taken down", when(c.takedownAt)], ["Counter-notice", c.counterAt ? `${when(c.counterAt)}${c.counterBy ? ` by ${c.counterBy}` : ""}` : "–"], ["Restore from", c.restoreEligibleAt ? c.restoreEligibleAt.toISOString().slice(0, 10) : "–"], ["Outcome", c.outcome ?? "open"]]} />
              <div className="mt-2 space-y-2">
                {c.status === "notice_received" && <><Step c={c} ev="takedown" label="Take down" danger /><Step c={c} ev="reject" label="Reject notice" /></>}
                {c.status === "taken_down" && <Step c={c} ev="counter" label="Log counter-notice"><input name="counterBy" placeholder="From (contributor / account)" className="input text-xs sm:w-44" /><textarea name="statement" placeholder="Counter-notice statement" className="input text-xs sm:w-72" rows={1} required /></Step>}
                {c.status === "counter_received" && <><Step c={c} ev="restore" label="Restore (to hold queue)" /><Step c={c} ev="suit" label="Claimant sued: keep down" /></>}
                {(c.status === "notice_received" || c.status === "taken_down" || c.status === "counter_received") && <Step c={c} ev="withdraw" label="Claimant withdrew" />}
              </div>
              {c.history.length ? <details className="mt-2"><summary className="cursor-pointer text-xs text-slate-400">History ({c.history.length})</summary><ul className="mt-1 space-y-0.5 text-xs text-slate-400">{c.history.map((h, i) => <li key={i}>{h.at.slice(0, 16).replace("T", " ")} · {h.event} · {h.by}{h.note ? ` · ${h.note}` : ""}</li>)}</ul></details> : null}
            </li>
          ))}</ul>
        )}
      </Section>
    </div>
  );
}
