import type { Metadata } from "next";
import { requireCyrusAdmin, cyrusAdminMetadata } from "@/lib/cyrus/admin/gate";
import { getHost } from "@/lib/cyrus/host";
import { effectiveFilterLists, FILTER_LIST_NAMES, FILTER_LISTS_SETTING, parseFilterOverrides } from "@/lib/cyrus/library/v2/filters";
import { adminCyrusLibraryListEdit } from "@/lib/actions-cyrus-admin-library";
import { Badge } from "@/components/ui/primitives";
import { LibraryNav } from "@/components/admin/cyrus/LibraryNav";
import { Flash, Hidden, Section } from "@/components/admin/cyrus/ui";

export const dynamic = "force-dynamic";
export async function generateMetadata(): Promise<Metadata> {
  return cyrusAdminMetadata("Library filter lists");
}

const LABEL = { realWeapons: "Real-weapon names", trademarks: "Trademarks" } as const;
const WHAT = {
  realWeapons: "A community asset named after a real firearm model is HELD for review (the proprietary library is flagged only).",
  trademarks: "A community asset that names a trademark or a game's own content is HELD (input-prompt packs: flagged). The shipped list is a stub for legal to extend.",
} as const;

/** Cyrus r40: edit the real-weapon and trademark lists the library's content filters use (new contributions only). */
export default async function FilterLists({ searchParams }: { searchParams: Promise<Record<string, string | string[] | undefined>> }) {
  await requireCyrusAdmin("library");
  const sp = await searchParams;
  const stored = await getHost().settings.readStored([FILTER_LISTS_SETTING]).catch(() => ({} as Record<string, string>));
  const ov = parseFilterOverrides(stored[FILTER_LISTS_SETTING]);
  const eff = effectiveFilterLists(ov);
  const back = "/admin/cyrus/library/lists";
  return (
    <div className="space-y-6">
      <LibraryNav current="lists" />
      <Flash sp={sp} />
      {FILTER_LIST_NAMES.map((name) => {
        const added = new Set(ov[name]?.add ?? []);
        return (
          <Section key={name} title={`${LABEL[name]} (${eff[name].length})`} sub={<>{WHAT[name]} Edits apply to new contributions; assets already decided keep their status. Shipped terms live in lib/cyrus/library/v2/filter-rules.json.</>}>
            <form action={adminCyrusLibraryListEdit} className="mb-3 flex flex-wrap gap-2">
              <Hidden name="list" value={name} /><Hidden name="op" value="add" /><Hidden name="back" value={back} />
              <input name="term" placeholder="Add a term" className="input text-sm sm:w-64" required maxLength={60} />
              <button className="btn-primary text-sm">Add</button>
            </form>
            <ul className="flex flex-wrap gap-1.5">{eff[name].map((t) => (
              <li key={t}>
                <form action={adminCyrusLibraryListEdit} className="inline-flex items-center gap-1 rounded-full border border-white/10 py-0.5 pl-2.5 pr-1 text-xs">
                  <Hidden name="list" value={name} /><Hidden name="op" value={added.has(t) ? "reset" : "remove"} /><Hidden name="term" value={t} /><Hidden name="back" value={back} />
                  <span>{t}</span>{added.has(t) ? <Badge tone="brand">added</Badge> : null}
                  <button className="rounded-full px-1.5 text-slate-400 hover:text-white" aria-label={`Remove ${t}`}>×</button>
                </form>
              </li>
            ))}</ul>
            {(ov[name]?.remove ?? []).length ? (
              <div className="mt-3 text-xs text-slate-400">Removed shipped terms: {(ov[name]?.remove ?? []).map((t) => (
                <form key={t} action={adminCyrusLibraryListEdit} className="mr-1 inline">
                  <Hidden name="list" value={name} /><Hidden name="op" value="reset" /><Hidden name="term" value={t} /><Hidden name="back" value={back} />
                  <button className="underline">{t} (put back)</button>
                </form>
              ))}</div>
            ) : null}
          </Section>
        );
      })}
    </div>
  );
}
