// ── (2) library moderation ─────────────────────────────────────────────────
import { addBusinessDays, legalDue, legalTransition, validateNotice, type LegalCase } from "../lib/cyrus/admin/dmca";
import { defaultFilters, effectiveFilterLists, parseFilterOverrides, validFilterTerm } from "../lib/cyrus/library/v2/filters";
import { contributionStats, nearDuplicates } from "../lib/cyrus/admin/library-mod";
import rules from "../lib/cyrus/library/v2/filter-rules.json";

const SHA = "a".repeat(64);
const baseCase = (o: Partial<LegalCase> = {}): LegalCase => ({ id: "lc_1", kind: "dmca", status: "notice_received", target: `library:${SHA}`, entryId: SHA, claimant: "ACME", claimantContact: null, work: "Logo", noticeAt: new Date("2026-10-01T12:00:00Z"), takedownAt: null, counterAt: null, counterBy: null, counterStatement: null, restoreEligibleAt: null, closedAt: null, outcome: null, history: [], ...o });

describe("r40 library: legal cases", () => {
  it("business days skip weekends", () => {
    assert.equal(addBusinessDays(new Date("2026-10-09T12:00:00Z"), 1).toISOString().slice(0, 10), "2026-10-12"); // Fri -> Mon
    assert.equal(addBusinessDays(new Date("2026-10-12T12:00:00Z"), 10).toISOString().slice(0, 10), "2026-10-26");
  });
  it("validates notices and normalises the target", () => {
    const v = validateNotice({ kind: "dmca", target: SHA, claimant: "ACME", work: "Our logo" });
    assert.ok(v.ok && v.value.target === `library:${SHA}` && v.value.entryId === SHA);
    assert.equal(validateNotice({ kind: "dmca", target: "https://x", claimant: "ACME", work: "Our logo" }).ok, false);
    assert.equal(validateNotice({ kind: "spam", target: SHA, claimant: "ACME", work: "Our logo" }).ok, false);
    const p = validateNotice({ kind: "trademark", target: "page:my-mod", claimant: "ACME", work: "brand" });
    assert.ok(p.ok && p.value.entryId === null);
  });
  it("takedown -> counter -> restore only after 10 business days; library actions follow", () => {
    const at = new Date("2026-10-12T12:00:00Z");
    const t1 = legalTransition(baseCase(), "takedown", { by: "owner:a", at });
    assert.ok(t1.ok && t1.next.status === "taken_down" && t1.library === "takedown");
    if (!t1.ok) return;
    assert.equal(legalTransition(t1.next, "counter", { by: "owner:a", at, statement: "short" }).ok, false);
    const t2 = legalTransition(t1.next, "counter", { by: "owner:a", at, statement: "I made this myself and I consent to jurisdiction." });
    assert.ok(t2.ok && t2.next.status === "counter_received" && t2.library === null);
    if (!t2.ok) return;
    assert.equal(t2.next.restoreEligibleAt!.toISOString().slice(0, 10), "2026-10-26");
    const early = legalTransition(t2.next, "restore", { by: "owner:a", at: new Date("2026-10-20T12:00:00Z") });
    assert.equal(early.ok, false);
    const ok = legalTransition(t2.next, "restore", { by: "owner:a", at: new Date("2026-10-27T12:00:00Z") });
    assert.ok(ok.ok && ok.next.status === "restored" && ok.library === "restore" && !ok.late);
    const late = legalTransition(t2.next, "restore", { by: "owner:a", at: new Date("2026-11-10T12:00:00Z") });
    assert.ok(late.ok && late.late === true);
    const suit = legalTransition(t2.next, "suit", { by: "owner:a", at });
    assert.ok(suit.ok && suit.next.status === "closed" && suit.library === null);
    assert.equal(ok.ok && ok.next.history.length, 3);
  });
  it("illegal steps are refused; reject needs a reason; withdraw after takedown restores", () => {
    assert.equal(legalTransition(baseCase(), "restore", { by: "o", at: new Date() }).ok, false);
    assert.equal(legalTransition(baseCase(), "reject", { by: "o", at: new Date() }).ok, false);
    assert.ok(legalTransition(baseCase(), "reject", { by: "o", at: new Date(), note: "incomplete notice" }).ok);
    const w = legalTransition(baseCase({ status: "taken_down" }), "withdraw", { by: "o", at: new Date() });
    assert.ok(w.ok && w.library === "restore");
    const w0 = legalTransition(baseCase(), "withdraw", { by: "o", at: new Date() });
    assert.ok(w0.ok && w0.library === null);
    assert.equal(legalTransition(baseCase({ status: "closed" }), "withdraw", { by: "o", at: new Date() }).ok, false);
  });
  it("due list: open notices, restorable and late counter-notices", () => {
    const now = new Date("2026-11-10T12:00:00Z");
    const d = legalDue([baseCase(), baseCase({ id: "lc_2", status: "counter_received", counterAt: new Date("2026-10-12T12:00:00Z"), restoreEligibleAt: new Date("2026-10-26T12:00:00Z") }), baseCase({ id: "lc_3", status: "closed" })], now);
    assert.deepEqual(d.map((x) => [x.id, x.level]), [["lc_1", "red"], ["lc_2", "red"]]);
  });
});

describe("r40 library: filter lists, near copies, stats", () => {
  it("overrides add and remove terms; bad input is dropped", () => {
    const ov = parseFilterOverrides(JSON.stringify({ realWeapons: { add: ["Zorg 9", "<script>", "zorg 9"], remove: [rules.realWeapons[0]] }, nope: {} }));
    assert.deepEqual(ov.realWeapons!.add, ["zorg 9"]);
    const eff = effectiveFilterLists(ov);
    assert.ok(eff.realWeapons.includes("zorg 9"));
    assert.ok(!eff.realWeapons.includes(rules.realWeapons[0]));
    assert.equal(eff.trademarks.length, rules.trademarks.length);
    assert.deepEqual(parseFilterOverrides("not json"), {});
    assert.equal(validFilterTerm("ak-47"), true);
    assert.equal(validFilterTerm("a|b"), false);
    assert.equal(validFilterTerm(""), false);
  });
  it("defaultFilters uses the edited list", () => {
    const f = defaultFilters({ realWeapons: { add: ["zorg 9"] } }).find((x) => x.id === "real-weapon")!;
    const e = { title: "Zorg 9 pistol", shortDescription: "", tags: [], freeTags: [], provenance: { path: "", pack: "" }, categories: { primary: "x" }, licence: { tier: "user-contributed" } } as never;
    assert.equal((f.check(e, { strict: true }) as { severity: string }[])[0]?.severity, "hold");
    const plain = defaultFilters().find((x) => x.id === "real-weapon")!;
    assert.equal((plain.check(e, { strict: true }) as unknown[]).length, 0);
  });
  it("near duplicates: same kind+method, Hamming threshold, facts exact only", () => {
    const self = { entryId: "s", kind: "texture", method: "dhash64", fp: "0000000000000000" };
    const r = nearDuplicates(self, [
      { entryId: "a", kind: "texture", method: "dhash64", fp: "0000000000000003" },
      { entryId: "b", kind: "texture", method: "dhash64", fp: "ffffffffffffffff" },
      { entryId: "c", kind: "sound", method: "dhash64", fp: "0000000000000000" },
      { entryId: "s", kind: "texture", method: "dhash64", fp: "0000000000000000" },
      { entryId: "d", kind: "texture", method: "dhash64", fp: "0000000000000000" },
    ]);
    assert.deepEqual(r.map((x) => [x.entryId, x.distance]), [["d", 0], ["a", 2]]);
    assert.deepEqual(nearDuplicates({ entryId: "s", kind: "model", method: "facts", fp: "t1" }, [{ entryId: "x", kind: "model", method: "facts", fp: "t1" }, { entryId: "y", kind: "model", method: "facts", fp: "t2" }]).map((x) => x.entryId), ["x"]);
  });
  it("contribution stats", () => {
    const now = new Date("2026-10-11T12:00:00Z");
    const s = contributionStats([
      { contributorId: "u_a", status: "published", kind: "texture", createdAt: now },
      { contributorId: "u_a", status: "held", kind: "texture", createdAt: now },
      { contributorId: "u_b", status: "removed", kind: "sound", createdAt: new Date("2026-10-10T01:00:00Z") },
    ], now, 3);
    assert.equal(s.total, 3); assert.equal(s.contributors, 2);
    assert.deepEqual(s.top[0], { contributorId: "u_a", n: 2, held: 1, removed: 0 });
    assert.deepEqual(s.perDay.map((d) => d.n), [0, 1, 2]);
    assert.ok(Math.abs(s.holdRate! - 1 / 3) < 1e-9);
    assert.equal(contributionStats([], now).holdRate, null);
  });
});
