function svcViewOfRow(row: { id: string; status: string; error: string | null; result: unknown; jarName: string | null; jarSize: number | null; jarSha256: string | null }): SvcView {
  const res = (row.result ?? {}) as { warnings?: string[]; safety?: SvcView["safety"]; errorDetail?: string | null };
