                const cur = value.get(s.key);
                const live = merged(s.owner);
                return (
                  <li key={s.key} className="flex flex-col gap-2 py-3 lg:flex-row lg:items-start lg:justify-between">
                    <div className="min-w-0 lg:max-w-[55%]">
                      <p className="flex flex-wrap items-center gap-2 text-sm font-medium">{s.label}{s.risky ? <Badge tone="amber">risky</Badge> : null}{!live ? <Badge tone="slate">{s.owner} branch not merged yet</Badge> : null}</p>
                      <p className="font-mono text-[11px] text-slate-500">{s.key}</p>
                      <p className="mt-0.5 text-xs text-slate-400">{s.description}</p>
                      <p className="mt-0.5 text-xs text-slate-500">Now: <span className="font-mono">{cur === undefined ? `${s.default || "(unset)"} (default)` : cur.length > 80 ? `${cur.slice(0, 80)}…` : cur}</span></p>
