                    {s.editAt ? (
                      <Link className="btn-secondary self-start text-xs" href={s.editAt}>Edit on {s.editAt.replace("/admin/", "")}</Link>
                    ) : canEdit ? (
                      <form action={adminCyrusSetSetting} className="flex flex-col gap-1.5 lg:w-[40%]">
                        <Hidden name="key" value={s.key} /><Hidden name="back" value="/admin/cyrus/audit" />
