"use server";

/**
 * Cyrus admin r40: the launch pair and the kill switches. Same contract as lib/actions-cyrus-admin.ts (role area,
 * preview list, never impersonating, audited before/after, redirect back with ?ok= / ?err=).
 *   launch pair  cyrus_studio_public_enabled + cyrus_tok_live are written together, in one transaction, after a typed
 *                confirmation (LAUNCH CYRUS / CLOSE CYRUS). Neither can be changed alone (settings-catalog editAt).
 *   kill switch  killing is one click (the safe direction); resuming needs the confirm box.
 */
import { notFound, redirect } from "next/navigation";
import type { User } from "@prisma/client";
import { db } from "./db";
import { impersonating, realUser } from "./auth";
import { requireArea } from "./rbac";
import { isPreviewUser } from "./preview-access";
import { CYRUS_ADMIN_ACTIONS, CYRUS_ADMIN_BASE, type CyrusAdminAction } from "./cyrus/admin/perms";
import { cyrusAudit } from "./cyrus/admin/audit";
import { KILL_SWITCHES, LAUNCH_PAIR, killWrite, launchPairFlip, launchPairState } from "./cyrus/admin/flags";
import { clearTokenConfigCache } from "./cyrus/tokens/config";

const FLAGS = `${CYRUS_ADMIN_BASE}/flags`;
const str = (fd: FormData, k: string, max = 300) => String(fd.get(k) ?? "").trim().slice(0, max);

function go(kind: "ok" | "err", msg: string, hash = ""): never {
  redirect(`${FLAGS}?${new URLSearchParams({ [kind]: msg.slice(0, 300) }).toString()}${hash}`);
}

async function guard(action: CyrusAdminAction): Promise<User> {
  const admin = await requireArea(CYRUS_ADMIN_ACTIONS[action]);
  if (await impersonating()) redirect("/dashboard");
  if (!(await isPreviewUser(await realUser(), "modbuilder"))) notFound();
  return admin;
}

async function stored(keys: readonly string[]) {
  const rows = await db.setting.findMany({ where: { key: { in: [...keys] } } });
  return Object.fromEntries(rows.map((r) => [r.key, r.value])) as Record<string, string>;
}

export async function adminCyrusLaunchPair(fd: FormData) {
  const admin = await guard("flag.launch");
  const on = fd.get("on") === "1";
  const before = launchPairState(await stored(LAUNCH_PAIR));
  const f = launchPairFlip(on, str(fd, "typed", 40));
  if (!f.ok) go("err", f.error, "#launch");
  await db.$transaction(f.writes.map((w) => w.value === null ? db.setting.deleteMany({ where: { key: w.key } }) : db.setting.upsert({ where: { key: w.key }, update: { value: w.value }, create: { key: w.key, value: w.value } })));
  clearTokenConfigCache();
  const after = launchPairState(await stored(LAUNCH_PAIR));
  await cyrusAudit({ actorId: admin.id, action: "flag.launch", target: `setting:${LAUNCH_PAIR.join("+")}`, before, after, note: str(fd, "note") });
  go("ok", on ? "Cyrus is public and the token economy is live (both switches on)." : "Cyrus is back to private preview (both switches off).", "#launch");
}

export async function adminCyrusKill(fd: FormData) {
  const admin = await guard("flag.kill");
  const k = KILL_SWITCHES.find((x) => x.id === str(fd, "id", 20));
  if (!k) go("err", "Unknown switch.", "#kill");
  const kill = fd.get("kill") === "1";
  const w = killWrite(k, kill, fd.get("confirm") === "1" || fd.get("confirm") === "on");
  if (!w.ok) go("err", w.error, "#kill");
  const before = (await stored([k.key]))[k.key] ?? null;
  if (w.value === null) await db.setting.deleteMany({ where: { key: w.key } });
  else await db.setting.upsert({ where: { key: w.key }, update: { value: w.value }, create: { key: w.key, value: w.value } });
  await cyrusAudit({ actorId: admin.id, action: "flag.kill", target: `setting:${k.key}`, before: before ?? "(unset)", after: w.value ?? "(unset)", note: `${kill ? "kill" : "resume"}: ${str(fd, "note")}` });
  go("ok", `${k.label}: ${kill ? "stopped" : "running again"}.`, "#kill");
}
EOF
