import { adminCyrusSetSetting } from "@/lib/actions-cyrus-admin";
import { Badge } from "@/components/ui/primitives";
import { Confirm, Empty, Flash, Hidden, Section, TableWrap, tdRow, thCls, when } from "@/components/admin/cyrus/ui";

export const dynamic = "force-dynamic";
export async function generateMetadata(): Promise<Metadata> {
  return cyrusAdminMetadata("Flags and kill switches");
}

const short = (v: unknown) => { const s = v === null || v === undefined ? "–" : typeof v === "string" ? v : JSON.stringify(v); return s.length > 80 ? `${s.slice(0, 80)}…` : s; };

/** Cyrus r40: every Cyrus switch in one place: the launch pair, kill switches, feature settings, env flags, history. */
export default async function CyrusFlags({ searchParams }: { searchParams: Promise<Record<string, string | string[] | undefined>> }) {
  await requireCyrusAdmin("flags");
  const me = (await realUser())!;
  const sp = await searchParams;
  const boolDefs = CYRUS_SETTINGS.filter((s) => s.type === "bool" && s.group !== "kill" && !(LAUNCH_PAIR as readonly string[]).includes(s.key));
  const keys = [...new Set([...LAUNCH_PAIR, ...KILL_SWITCHES.map((k) => k.key), ...boolDefs.map((s) => s.key)])];
  const [rows, history] = await Promise.all([
    db.setting.findMany({ where: { key: { in: keys } } }),
    db.auditLog.findMany({ where: { action: { in: FLAG_HISTORY_ACTIONS } }, orderBy: { createdAt: "desc" }, take: 40 }),
  ]);
  const stored = Object.fromEntries(rows.map((r) => [r.key, r.value])) as Record<string, string>;
  const pair = launchPairState(stored);
  const emails = await emailMap(history.map((h) => h.userId ?? ""));
  const can = { launch: canCyrusAdmin(me.role, "flag.launch"), kill: canCyrusAdmin(me.role, "flag.kill"), set: canCyrusAdmin(me.role, "setting.set") };
  const env = CYRUS_ENV_FLAGS.map((f) => envFlagState(f, process.env));
  const groups = Object.keys(ENV_GROUP_LABEL) as EnvGroup[];

  return (
    <div>
      <Flash sp={sp} />
      <Section id="launch" title="Launch pair" sub="cyrus_studio_public_enabled (anyone verified can build) and cyrus_tok_live (the token economy) always move together. Neither can be changed alone." right={pair.on ? <Badge tone="green">public + live</Badge> : pair.consistent ? <Badge tone="slate">private preview</Badge> : <Badge tone="red">out of step</Badge>}>
        <div className="grid gap-3 text-sm sm:grid-cols-2">
          <p><span className="font-mono text-xs text-slate-500">cyrus_studio_public_enabled</span> <b>{pair.studioPublic ? "on" : "off"}</b></p>
          <p><span className="font-mono text-xs text-slate-500">cyrus_tok_live</span> <b>{pair.tokensLive ? "on" : "off"}</b></p>
        </div>
        {!pair.consistent ? <p className="mt-2 text-sm text-red-300">The two switches disagree (set outside this page). The studio stays closed until both are on (publicMayBuild); use the switch below to bring them back together.</p> : null}
        {can.launch ? (
          <form action={adminCyrusLaunchPair} className="mt-3 grid gap-2 sm:flex sm:flex-wrap sm:items-end">
            <Hidden name="on" value={pair.on ? "0" : "1"} />
            <input name="typed" placeholder={`Type ${pair.on ? LAUNCH_CONFIRM_OFF : LAUNCH_CONFIRM_ON}`} className="input text-sm sm:w-56" autoComplete="off" required aria-label="Typed confirmation" />
            <input name="note" placeholder="Why (audit log)" className="input text-sm sm:w-64" />
            <button className={`${pair.on ? "btn-secondary" : "btn-danger"} text-sm`}>{pair.on ? "Close Cyrus (both off)" : "Launch Cyrus (both on)"}</button>
          </form>
        ) : <p className="mt-2 text-xs text-slate-500">Your role can see the pair but not flip it.</p>}
      </Section>

      <Section id="kill" title="Kill switches" sub="Stopping is one click. Turning back on needs the confirm box. Each flip is audited.">
        <ul className="divide-y divide-white/[0.06]">{KILL_SWITCHES.map((k) => { const st = killState(k, stored); return (
          <li key={k.id} className="flex flex-col gap-2 py-3 sm:flex-row sm:items-center sm:justify-between">
            <div className="min-w-0"><p className="flex flex-wrap items-center gap-2 text-sm font-medium">{k.label}<Badge tone={st === "killed" ? "red" : "green"}>{st === "killed" ? "stopped" : "running"}</Badge></p><p className="font-mono text-[11px] text-slate-500">{k.key}</p><p className="text-xs text-slate-400">{k.what}</p></div>
            {can.kill ? (
              <form action={adminCyrusKill} className="flex flex-wrap items-center gap-2">
                <Hidden name="id" value={k.id} /><Hidden name="kill" value={st === "killed" ? "0" : "1"} />
                <input name="note" placeholder="Why" className="input w-32 text-xs" />
                {st === "killed" ? <label className="flex items-center gap-1 text-xs"><input type="checkbox" name="confirm" value="1" required /> confirm</label> : null}
                <button className={`${st === "killed" ? "btn-secondary" : "btn-danger"} text-xs`}>{st === "killed" ? "Resume" : "Stop"}</button>
              </form>
            ) : null}
          </li>
        ); })}</ul>
      </Section>

      <Section title="Feature switches (settings)" sub={<>Live without a restart. Risky ones ask for a confirm when turned on. Numbers and the rest: <Link className="underline" href="/admin/cyrus/audit">Audit &amp; settings</Link>.</>}>
        <ul className="divide-y divide-white/[0.06]">{boolDefs.map((s) => { const cur = stored[s.key]; const on = (cur ?? s.default) === "true"; return (
          <li key={s.key} className="flex flex-col gap-2 py-2.5 sm:flex-row sm:items-center sm:justify-between">
            <div className="min-w-0 sm:max-w-[60%]"><p className="flex flex-wrap items-center gap-2 text-sm">{s.label}<Badge tone={on ? "green" : "slate"}>{on ? "on" : "off"}</Badge>{s.risky ? <Badge tone="amber">risky</Badge> : null}</p><p className="font-mono text-[11px] text-slate-500">{s.key}{cur === undefined ? " · default" : ""}</p></div>
            {s.editAt ? <Link className="btn-ghost self-start text-xs" href={s.editAt}>Edit on {s.editAt.replace("/admin/", "")}</Link> : can.set ? (
              <form action={adminCyrusSetSetting} className="flex flex-wrap items-center gap-2">
                <Hidden name="key" value={s.key} /><Hidden name="back" value="/admin/cyrus/flags" /><Hidden name="value" value={on ? "false" : "true"} />
                {s.risky && !on ? <Confirm required label="confirm" /> : null}
                <button className="btn-secondary text-xs">{on ? "Turn off" : "Turn on"}</button>
              </form>
            ) : null}
          </li>
        ); })}</ul>
      </Section>

      <Section title="Server switches (environment)" sub="CYRUS_* environment variables on this server, read-only: changing one is an env edit plus a restart through the deploy runbook (docs/CYRUS-DEPLOY-RUNBOOK.md). Secrets only show set / unset.">
        <div className="grid min-w-0 gap-4 lg:grid-cols-2">{groups.map((g) => (
          <div key={g} className="min-w-0">
            <p className="mb-1 text-xs font-medium text-slate-400">{ENV_GROUP_LABEL[g]}</p>
            <ul className="space-y-1">{env.filter((f) => f.group === g).map((f) => (
              <li key={f.key} className="flex items-start justify-between gap-2 text-xs">
                <span className="min-w-0"><span className="font-mono">{f.key}</span>{f.risky ? <span className="ml-1 text-amber-400">risky</span> : null}<span className="block text-slate-500">{f.what}</span></span>
                <Badge tone={f.state === "on" || f.state === "set" || f.state === "value" ? "green" : "slate"}>{f.state === "value" ? f.value : f.state}</Badge>
              </li>
            ))}</ul>
          </div>
        ))}</div>
      </Section>

      <Section title="Change history" sub="The latest 40 switch and setting changes (all of them: Audit & settings).">
        {history.length === 0 ? <Empty>No switch has been changed from the admin yet.</Empty> : (
          <TableWrap>
            <table className="w-full text-xs">
              <thead><tr className={thCls}><th>When</th><th>Who</th><th>What</th><th>Before</th><th>After</th></tr></thead>
              <tbody>{history.map((h) => { const d = readAuditDetail(h.detail); return (
                <tr key={h.id} className={tdRow}><td className="whitespace-nowrap">{when(h.createdAt)}</td><td className="max-w-[160px] truncate">{emails.get(h.userId ?? "") ?? "system"}</td><td><span className="font-mono">{h.action.replace(CYRUS_AUDIT_PREFIX, "")}</span> <span className="break-all text-slate-500">{h.target ?? ""}</span></td><td className="max-w-[200px] break-all">{d.text ? d.text.slice(0, 120) : short(d.before)}</td><td className="max-w-[200px] break-all">{d.text ? "" : short(d.after)}</td></tr>
              ); })}</tbody>
            </table>
          </TableWrap>
        )}
      </Section>
    </div>
  );
}
EOF
