// ── (3) flags and kill switches ────────────────────────────────────────────
import { CYRUS_ENV_FLAGS, KILL_SWITCHES, LAUNCH_CONFIRM_OFF, LAUNCH_CONFIRM_ON, envFlagState, killState, killWrite, launchPairFlip, launchPairState } from "../lib/cyrus/admin/flags";
import { CYRUS_SETTINGS, validateSettingValue } from "../lib/cyrus/admin/settings-catalog";

describe("r40 flags: env flags, launch pair, kill switches", () => {
  it("a secret never shows a value; modes show only short safe values; switches read 1/true/on", () => {
    const sec = CYRUS_ENV_FLAGS.find((f) => f.kind === "secret")!;
    assert.deepEqual([envFlagState(sec, { [sec.key]: "sk-live-abc" }).state, envFlagState(sec, { [sec.key]: "sk-live-abc" }).value], ["set", null]);
    const mode = CYRUS_ENV_FLAGS.find((f) => f.key === "CYRUS_LIBRARY_STORE")!;
    assert.equal(envFlagState(mode, { CYRUS_LIBRARY_STORE: "s3" }).value, "s3");
    assert.equal(envFlagState(mode, { CYRUS_LIBRARY_STORE: "https://user:pw@host/x" }).value, "(set)");
    const sw = CYRUS_ENV_FLAGS.find((f) => f.key === "CYRUS_DELIVERY")!;
    assert.equal(envFlagState(sw, { CYRUS_DELIVERY: "1" }).state, "on");
    assert.equal(envFlagState(sw, { CYRUS_DELIVERY: "0" }).state, "off");
    assert.equal(envFlagState(sw, {}).state, "off");
    assert.equal(new Set(CYRUS_ENV_FLAGS.map((f) => f.key)).size, CYRUS_ENV_FLAGS.length);
  });
  it("launch pair: moves together, typed confirmation per direction, out-of-step detected", () => {
    assert.equal(launchPairFlip(true, "yes").ok, false);
    assert.equal(launchPairFlip(true, LAUNCH_CONFIRM_OFF).ok, false);
    const on = launchPairFlip(true, LAUNCH_CONFIRM_ON);
    assert.ok(on.ok && on.writes.length === 2 && on.writes.every((w) => w.value === "true"));
    const off = launchPairFlip(false, LAUNCH_CONFIRM_OFF);
    assert.ok(off.ok && off.writes.every((w) => w.value === null));
    assert.deepEqual(launchPairState({ cyrus_studio_public_enabled: "true" }), { studioPublic: true, tokensLive: false, consistent: false, on: false });
    // neither half can be edited alone through the generic setting form
    assert.equal(validateSettingValue("cyrus_tok_live", "true").ok, false);
    assert.equal(validateSettingValue("cyrus_studio_public_enabled", "true").ok, false);
  });
  it("kill switches: stop is one click, resume needs the confirm; networking is killed when unset", () => {
    const b = KILL_SWITCHES.find((k) => k.id === "builds")!, net = KILL_SWITCHES.find((k) => k.id === "networking")!;
    assert.deepEqual(killWrite(b, true, false), { ok: true, key: "cyrus_builds_paused", value: "true" });
    assert.equal(killWrite(b, false, false).ok, false);
    assert.deepEqual(killWrite(b, false, true), { ok: true, key: "cyrus_builds_paused", value: null });
    assert.deepEqual(killWrite(net, true, false), { ok: true, key: "cyrus_mod_networking_enabled", value: null });
    assert.equal(killState(net, {}), "killed");
    assert.equal(killState(b, {}), "running");
    assert.equal(killState(b, { cyrus_builds_paused: "true" }), "killed");
  });
  it("every cyrus_ switch is in the settings catalog once", () => {
    const keys = CYRUS_SETTINGS.map((s) => s.key);
    assert.equal(new Set(keys).size, keys.length);
    for (const k of ["cyrus_builds_paused", "cyrus_ai_gw_kill", "cyrus_studio_public_enabled", "cyrus_tok_live", "cyrus_public_enabled", "cyrus_passrate_enabled", "cyrus_model_studio_enabled", "cyrus_ai_gateway_enabled"]) assert.ok(keys.includes(k), k);
  });
});
EOF
