//   x-cyrus-telemetry-timestamp  unix seconds when the collector signed (accepted within +-300 s)
//   x-cyrus-telemetry-batch      a fresh random batch id (16-64 of A-Z a-z 0-9 _ -), single use
//   x-cyrus-telemetry-signature  hex HMAC-SHA256(CYRUS_HEALTH_TELEMETRY_SECRET, "cyrus-telemetry.v2\\n<ts>\\n<batch>\\n<raw body>")
// A batch id seen before (within the freshness window) is refused 409 and nothing is stored. The body is read as a
// stream and the read stops at the cap (no full buffering of an oversized body); a per-IP limit runs before the read.
// Fail closed at every step:
//   CYRUS_HEALTH_TELEMETRY=1 and a secret of 24+ chars (else 404) -> declared size (413) -> per-IP rate (429) -> capped
//   read (413) -> headers + signature (401) -> freshness (401) -> replay (409) -> JSON / count (400/413) -> EVERY signal
//   valid by the strict schema, or the whole batch is refused (422) -> days only inside the raw retention window (422)
//   -> storage present (the DRAFT tables of prisma/manual-migrations/2026-10-10-cyrus-mod-health-telemetry.sql are NOT
//   applied: until they are, 503 and nothing stored) -> upsert by (day, serverKey, buildId, mcVersion, event, key),
//   counts capped at 10000.
import { createHmac, randomBytes, timingSafeEqual } from "node:crypto";
import { TELEMETRY_FLAG, validateSignal, type HealthSignal } from "./schema";
import { TELEMETRY_SECRET_ENV, dayOf } from "./collect";
import { RETENTION } from "./aggregate";

type Env = Record<string, string | undefined>;
export const INGEST_MAX_BYTES = 256 * 1024;
export const INGEST_MAX_SIGNALS = 500;
export const SIGNATURE_HEADER = "x-cyrus-telemetry-signature";
export const TIMESTAMP_HEADER = "x-cyrus-telemetry-timestamp";
export const BATCH_HEADER = "x-cyrus-telemetry-batch";
export const MAX_SKEW_SEC = 300;
export const IP_LIMIT = { max: 60, windowMs: 60_000 };

export interface SignalStore {
  /** The draft tables exist (the migration was applied together with their models). */
  available(): Promise<boolean>;
  upsert(signals: HealthSignal[]): Promise<number>;
}
/** Single-use batch ids. `claim` returns false when the id was already used (then the batch is a replay). */
export interface ReplayGuard { claim(batchId: string, expiresAtMs: number, nowMs: number): Promise<boolean> }
export type IngestDeps = { env: Env; store: SignalStore; now?: () => Date; replay?: ReplayGuard; rateLimit?: (key: string) => boolean; clientIp?: string | null };

/** In-process replay guard (one instance; a multi-instance deployment needs a shared store: AC O-11). Bounded. */
export function memoryReplayGuard(cap = 50_000): ReplayGuard {
  const seen = new Map<string, number>();
  return {
    async claim(id, exp, now) {
      if (seen.size >= cap) for (const [k, e] of seen) { if (e <= now || seen.size >= cap) seen.delete(k); if (seen.size < cap * 0.9) break; }
      const prev = seen.get(id);
      if (prev !== undefined && prev > now) return false;
      seen.set(id, exp);
      return true;
    },
  };
}
const defaultReplay = memoryReplayGuard();

const json = (status: number, body: unknown) => new Response(JSON.stringify(body), { status, headers: { "content-type": "application/json", "cache-control": "no-store" } });
export const signBatch = (secret: string, ts: number | string, batch: string, body: string) => createHmac("sha256", secret).update(`cyrus-telemetry.v2\\n${ts}\\n${batch}\\n${body}`).digest("hex");

/** Read at most `max` bytes of the body; null when it is larger (the stream is cancelled, never fully buffered). */
export async function readCapped(req: Request, max: number): Promise<string | null> {
  if (!req.body) return "";
  const reader = req.body.getReader();
  const chunks: Uint8Array[] = [];
  let n = 0;
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    n += value.byteLength;
    if (n > max) { await reader.cancel().catch(() => {}); return null; }
    chunks.push(value);
  }
  return Buffer.concat(chunks.map((c) => Buffer.from(c))).toString("utf8");
}

export async function handleTelemetryIngest(req: Request, d: IngestDeps): Promise<Response> {
  const secret = d.env[TELEMETRY_SECRET_ENV] ?? "";
  if (d.env[TELEMETRY_FLAG] !== "1" || secret.length < 24) return json(404, { error: "Not found" });
  const len = Number(req.headers.get("content-length") || "0");
  if (len > INGEST_MAX_BYTES) return json(413, { error: "too large", code: "too_large" });
  if (d.rateLimit && !d.rateLimit(`cyrus-telemetry:ip:${d.clientIp || "unknown"}`)) return json(429, { error: "slow down", code: "rate_limited" });
  const raw = await readCapped(req, INGEST_MAX_BYTES);
  if (raw === null) return json(413, { error: "too large", code: "too_large" });
  const sig = req.headers.get(SIGNATURE_HEADER) ?? "";
  const tsRaw = req.headers.get(TIMESTAMP_HEADER) ?? "";
  const batch = req.headers.get(BATCH_HEADER) ?? "";
  const formatOk = /^[0-9a-f]{64}$/.test(sig) && /^\\d{9,11}$/.test(tsRaw) && /^[A-Za-z0-9_-]{16,64}$/.test(batch);
  const want = Buffer.from(signBatch(secret, tsRaw, batch, raw), "hex");
  const got = formatOk ? Buffer.from(sig, "hex") : randomBytes(32);
  if (!timingSafeEqual(want, got) || !formatOk) return json(401, { error: "bad signature", code: "bad_signature" });
  const now = (d.now ?? (() => new Date()))();
  const ts = Number(tsRaw);
  if (Math.abs(now.getTime() / 1000 - ts) > MAX_SKEW_SEC) return json(401, { error: "stale or future timestamp", code: "stale" });
  if (!(await (d.replay ?? defaultReplay).claim(batch, (ts + MAX_SKEW_SEC) * 1000 + 1000, now.getTime()))) return json(409, { error: "batch already received: nothing was stored", code: "replay" });
  let body: unknown;
  try { body = JSON.parse(raw); } catch { return json(400, { error: "not JSON", code: "bad_body" }); }
  const signals = (body as { signals?: unknown })?.signals;
  if (!Array.isArray(signals) || !signals.length) return json(400, { error: "send { signals: [...] }", code: "bad_body" });
  if (signals.length > INGEST_MAX_SIGNALS) return json(413, { error: `at most ${INGEST_MAX_SIGNALS} signals per batch`, code: "too_many" });
  const problems = signals.map((s, i) => ({ i, p: validateSignal(s) })).filter((x) => x.p.length);
  if (problems.length) return json(422, { error: "invalid signals: nothing was stored", code: "invalid", problems: problems.slice(0, 10).map((x) => ({ index: x.i, problems: x.p.slice(0, 5) })) });
  const oldest = dayOf(new Date(now.getTime() - RETENTION.rawDays * 86_400_000)), today = dayOf(now);
  const outOfWindow = (signals as HealthSignal[]).findIndex((s) => s.day <= oldest || s.day > today);
  if (outOfWindow >= 0) return json(422, { error: "a signal is outside the retention window: nothing was stored", code: "out_of_window", index: outOfWindow });
  if (!(await d.store.available().catch(() => false))) return json(503, { error: "telemetry storage is not set up (draft migration not applied): nothing was stored", code: "storage_absent" });
  const n = await d.store.upsert(signals as HealthSignal[]);
  return json(200, { stored: n });
}

