        )}
      </Section>

      <Section title="Caps and alerts" sub="USD of AI cost. 0 = off (the default). Caps refuse NEW builds only (running builds finish); a cap that cannot be checked refuses the build.">
        <ul className="divide-y divide-white/[0.06]">{(Object.entries(COST_SETTINGS) as [keyof typeof caps, string][]).map(([k, key]) => { const d = cyrusSettingDef(key)!; return (
          <li key={key} className="flex flex-col gap-2 py-2.5 sm:flex-row sm:items-center sm:justify-between">
            <div className="min-w-0 sm:max-w-[60%]"><p className="text-sm">{d.label} <span className="font-semibold">{caps[k] ? usd(caps[k]) : "off"}</span></p><p className="text-xs text-slate-500">{d.description}</p></div>
            {canSet ? (
              <form action={adminCyrusSetSetting} className="flex items-center gap-2">
                <Hidden name="key" value={key} /><Hidden name="back" value="/admin/cyrus/cost" />
                <input name="value" type="number" min={0} step="0.01" defaultValue={caps[k] || ""} placeholder="0" className="input w-28 py-1 text-xs" aria-label={d.label} />
                {d.risky ? <label className="flex items-center gap-1 text-xs"><input type="checkbox" name="confirm" value="1" /> confirm</label> : null}
                <button className="btn-secondary px-2 py-1 text-xs">Save</button>
              </form>
            ) : null}
          </li>
        ); })}</ul>
      </Section>

      <Section title="Margin per plan, 30 days" sub="Revenue = plan invoices paid in the window (live mode, from the token ledger). Spend = AI cost of builds by that plan's current subscribers. List price = your cyrus_tok_plan_*_cents setting.">
        <TableWrap>
          <table className="w-full text-sm">
            <thead><tr className={thCls}><th>Plan</th><th className="text-right">List price</th><th className="text-right">Subscribers</th><th className="text-right">Revenue</th><th className="text-right">AI spend</th><th className="text-right">Margin</th><th className="text-right">Spend / subscriber</th></tr></thead>
            <tbody>{margins.map((m) => (
              <tr key={m.tier} className={tdRow}><td className="capitalize">{m.tier === "all" ? "All models" : m.tier}</td><td className="text-right tabular-nums">{m.listCents === null ? "–" : usd(m.listCents / 100)}</td><td className="text-right tabular-nums">{n(m.subscribers)}</td><td className="text-right tabular-nums">{usd(m.revenueUsd)}</td><td className="text-right tabular-nums">{usd(m.spendUsd, 3)}</td><td className={`text-right tabular-nums ${m.marginUsd < 0 ? "text-red-400" : ""}`}>{usd(m.marginUsd)} <span className="text-xs text-slate-500">{pct(m.marginPct)}</span></td><td className="text-right tabular-nums">{m.spendPerSubscriberUsd === null ? "–" : usd(m.spendPerSubscriberUsd, 3)}</td></tr>
            ))}</tbody>
          </table>
        </TableWrap>
        <p className="mt-2 text-xs text-slate-500">Top-up and per-model margin (tokens charged vs AI cost): Overview.</p>
      </Section>

      <div className="grid min-w-0 gap-0 xl:grid-cols-2 xl:gap-6">
        <Section title="Spend by underlying model, 30 days" sub="From each build's recorded AI calls (internal names, never shown to customers). Unpriced = calls without a cost.">
          {models.length === 0 ? <Empty>No AI calls recorded in 30 days.</Empty> : (
            <TableWrap>
              <table className="w-full text-sm">
                <thead><tr className={thCls}><th>Model</th><th className="text-right">Calls</th><th className="text-right">Cost</th><th className="text-right">Unpriced</th></tr></thead>
                <tbody>{models.map((m) => <tr key={m.model} className={tdRow}><td className="font-mono text-xs">{m.model}</td><td className="text-right tabular-nums">{n(m.calls)}</td><td className="text-right tabular-nums">{usd(m.costUsd, 3)}</td><td className="text-right tabular-nums">{n(m.unpriced)}</td></tr>)}</tbody>
              </table>
            </TableWrap>
          )}
        </Section>
        <Section title="Spend by account, 30 days" sub="Top 25 by AI cost.">
          {top.length === 0 ? <Empty>No spend in 30 days.</Empty> : (
            <TableWrap>
              <table className="w-full text-sm">
                <thead><tr className={thCls}><th>Account</th><th className="text-right">24 h</th><th className="text-right">7 d</th><th className="text-right">30 d</th><th className="text-right">Builds</th></tr></thead>
                <tbody>{top.map((u) => <tr key={u.userId} className={tdRow}><td className="max-w-[200px] truncate"><UserLink id={u.userId} email={emails.get(u.userId)} /></td><td className={`text-right tabular-nums ${caps.userDailyCapUsd && u.d1 >= caps.userDailyCapUsd ? "text-red-400" : ""}`}>{usd(u.d1, 3)}</td><td className="text-right tabular-nums">{usd(u.d7, 3)}</td><td className="text-right tabular-nums">{usd(u.d30, 3)}</td><td className="text-right tabular-nums">{n(u.builds30)}</td></tr>)}</tbody>
              </table>
            </TableWrap>
          )}
        </Section>
      </div>
    </div>
  );
}
