  it("caps default off; bad values are off; decision order platform > daily > monthly", () => {
    const off = parseCostCaps({});
    assert.deepEqual(Object.values(off), [0, 0, 0, 0, 0]);
    assert.equal(parseCostCaps({ cyrus_cost_user_daily_cap_usd: "-3" }).userDailyCapUsd, 0);
    assert.deepEqual(spendCapDecision({ caps: off, userTodayUsd: 1e6, userMonthUsd: 1e6, platformTodayUsd: 1e6 }), { ok: true });
    const caps = parseCostCaps({ cyrus_cost_user_daily_cap_usd: "2", cyrus_cost_user_monthly_cap_usd: "10", cyrus_cost_platform_daily_cap_usd: "50" });
