    assert.deepEqual(u.map((x) => [x.userId, x.d1, x.d7, x.d30, x.builds30]), [["a", 1, 3, 7, 3]]);
    const calls = callsOfResult({ ai: { calls: [{ model: "claude-sonnet-5-20260101", costUsd: 0.5 }, { model: "x", resolvedModel: "claude-sonnet-5", costUsd: 0.25 }, { model: "y" }] } });
    const m = spendByModel(calls);
    assert.deepEqual(m.map((x) => [x.model, x.calls, x.costUsd, x.unpriced]), [["claude-sonnet-5", 2, 0.75, 0], ["y", 1, 0, 1]]);
    assert.deepEqual(callsOfResult(null), []);
  });
