    const r = planMargins({ tiers: ["katara", "saka"], plans: [{ userId: "a", tier: "saka", status: "active", livemode: true }, { userId: "b", tier: "saka", status: "canceled", livemode: true }, { userId: "c", tier: "saka", status: "active", livemode: false }], payments: [{ userId: "a", tier: "saka", cents: 1999 }], spend: new Map([["a", 3], ["b", 100]]), listCents: { saka: 1999 } });
    assert.deepEqual(r.find((x) => x.tier === "saka"), { tier: "saka", listCents: 1999, subscribers: 1, revenueUsd: 19.99, spendUsd: 3, marginUsd: 16.99, marginPct: 16.99 / 19.99, spendPerSubscriberUsd: 3 });
    assert.deepEqual(r.find((x) => x.tier === "katara"), { tier: "katara", listCents: null, subscribers: 0, revenueUsd: 0, spendUsd: 0, marginUsd: 0, marginPct: null, spendPerSubscriberUsd: null });
  });
  it("anomalies: spike vs own baseline, outlier build, owner alerts", () => {
    const rows = [
      ...Array.from({ length: 29 }, (_, i) => ({ id: `a${i}`, userId: "a", costUsd: 0.1, createdAt: h(24 * (i + 1) + 1) })),
      { id: "spike", userId: "a", costUsd: 3, createdAt: h(1) },
      ...["b", "c", "d", "e"].map((u) => ({ id: u, userId: u, costUsd: 0.1, createdAt: h(2) })),
    ];
    const users = spendByUser(rows, now);
    const caps = parseCostCaps({ cyrus_cost_alert_platform_daily_usd: "1" });
    const f = costAnomalies({ users, builds: rows, caps, platformTodayUsd: 3.4, now });
    assert.ok(f.some((x) => x.code === "user_spike" && x.userId === "a"));
    assert.ok(f.some((x) => x.code === "build_outlier" && x.buildId === "spike"));
    assert.ok(f.some((x) => x.code === "platform_alert"));
    assert.deepEqual(costAnomalies({ users: [], builds: [], caps: parseCostCaps({}), platformTodayUsd: 0, now }), []);
  });
});
