// Cyrus admin r40: reconciliation. PURE checks (unit-tested in test/cyrus-admin-r40.test.ts) + a raw-SQL view of the
// webhook outbox table (CyrusWebhookOutbox, SQL proposal prisma/manual-migration-cyrus-api-v1.sql, NOT applied: until
// it exists the page says so and replay is refused).
//   walletDrift     Nxeon wallet charges for Cyrus top-ups (reference cwt:<user>:<key>) vs Cyrus token ledger rows
//   tokenDrift      ledger invariants per account: balance = SUM(lot.remaining), reserved = SUM(held reservations),
//                   balance = the newest ledger row's balanceAfter
//   planDrift       CyrusPlan.tier vs the tier of the newest paid plan invoice in the ledger (entitlement follows money)

export type WalletMove = { userId: string; reference: string; cents: number; at: Date };
export type WalletDriftRow = { reference: string; userId: string; cents: number; at: Date; state: "charged_not_credited" | "credited_not_charged" | "refunded" | "ok" };

/** `credited`: idemKeys of ledger rows with the cwt: prefix (method wallet). Charges are negative cents. */
export function walletDrift(moves: WalletMove[], credited: { idemKey: string; userId: string; createdAt: Date; paidCents: number | null }[]): { rows: WalletDriftRow[]; problems: number } {
  const charges = new Map<string, WalletMove>(), refunds = new Set<string>();
  for (const m of moves) {
    if (m.reference.endsWith(":refund") && m.cents > 0) refunds.add(m.reference.slice(0, -":refund".length));
    else if (m.cents < 0) charges.set(m.reference, m);
  }
  const creditedBy = new Map(credited.map((c) => [c.idemKey, c]));
  const rows: WalletDriftRow[] = [];
  for (const [ref, m] of charges) {
    const state = creditedBy.has(ref) ? "ok" : refunds.has(ref) ? "refunded" : "charged_not_credited";
    rows.push({ reference: ref, userId: m.userId, cents: -m.cents, at: m.at, state });
  }
  for (const c of credited) if (!charges.has(c.idemKey)) rows.push({ reference: c.idemKey, userId: c.userId, cents: c.paidCents ?? 0, at: c.createdAt, state: "credited_not_charged" });
  rows.sort((a, b) => b.at.getTime() - a.at.getTime());
  return { rows, problems: rows.filter((r) => r.state === "charged_not_credited" || r.state === "credited_not_charged").length };
}

export type AccountFacts = { userId: string; balance: number; reserved: number; lotsRemaining: number; heldSum: number; lastBalanceAfter: number | null; staleLots: number };
export type TokenDriftRow = { userId: string; issues: string[] };

export function tokenDrift(accounts: AccountFacts[]): TokenDriftRow[] {
  const out: TokenDriftRow[] = [];
  for (const a of accounts) {
    const issues: string[] = [];
    if (a.balance !== a.lotsRemaining) issues.push(`balance ${a.balance} but lots hold ${a.lotsRemaining}${a.staleLots ? ` (${a.staleLots} lot(s) past expiry wait for the next operation)` : ""}`);
    if (a.reserved !== a.heldSum) issues.push(`reserved ${a.reserved} but held reservations total ${a.heldSum}`);
    if (a.lastBalanceAfter !== null && a.lastBalanceAfter !== a.balance) issues.push(`balance ${a.balance} but the newest ledger row says ${a.lastBalanceAfter}`);
    if (a.balance < 0 || a.reserved < 0) issues.push("negative balance or reserved");
    if (issues.length) out.push({ userId: a.userId, issues });
  }
  return out;
}

export type PlanDriftRow = { userId: string; planTier: string; paidTier: string | null; status: string };

export function planDrift(plans: { userId: string; tier: string; status: string; livemode: boolean }[], newestPaidTier: Map<string, string>): PlanDriftRow[] {
  return plans
    .filter((p) => p.livemode && (p.status === "active" || p.status === "trialing" || p.status === "past_due"))
    .map((p) => ({ userId: p.userId, planTier: p.tier, paidTier: newestPaidTier.get(p.userId) ?? null, status: p.status }))
    .filter((r) => r.paidTier !== r.planTier);
}

// ---------------------------------------------------------------------------
// Webhook outbox (raw SQL over the proposed table; same row shape as lib/cyrus/api/v1/webhooks.ts OutboxRow)
// ---------------------------------------------------------------------------

type RawDb = { $queryRawUnsafe<T = unknown>(q: string, ...v: unknown[]): Promise<T>; $executeRawUnsafe(q: string, ...v: unknown[]): Promise<number> };
export type OutboxAdminRow = { id: string; type: string; subject: string | null; attempts: number; status: string; lastError: string | null; nextAttemptAt: Date; createdAt: Date };

export function sqlOutboxAdmin(db: RawDb) {
  return {
    async available(): Promise<boolean> {
      const r = await db.$queryRawUnsafe<{ t: string | null }[]>(`SELECT to_regclass('public."CyrusWebhookOutbox"')::text AS t`);
      return !!r[0]?.t;
    },
    async counts(): Promise<Record<string, number>> {
      const r = await db.$queryRawUnsafe<{ status: string; n: bigint | number }[]>(`SELECT "status", COUNT(*) AS n FROM "CyrusWebhookOutbox" GROUP BY "status"`);
      return Object.fromEntries(r.map((x) => [x.status, Number(x.n)]));
    },
    async list(status: "dead" | "pending", limit = 100): Promise<OutboxAdminRow[]> {
      return db.$queryRawUnsafe<OutboxAdminRow[]>(`SELECT "id","type","subject","attempts","status","lastError","nextAttemptAt","createdAt" FROM "CyrusWebhookOutbox" WHERE "status" = $1 ORDER BY "createdAt" DESC LIMIT $2`, status, Math.min(500, limit));
    },
    /** Put a DEAD event back in the queue (attempts reset, due now). Only dead rows move; returns rows changed. */
    async replay(id: string): Promise<number> {
      return db.$executeRawUnsafe(`UPDATE "CyrusWebhookOutbox" SET "status" = 'pending', "attempts" = 0, "nextAttemptAt" = now(), "lastError" = NULL WHERE "id" = $1 AND "status" = 'dead'`, id);
    },
    async replayAllDead(): Promise<number> {
      return db.$executeRawUnsafe(`UPDATE "CyrusWebhookOutbox" SET "status" = 'pending', "attempts" = 0, "nextAttemptAt" = now(), "lastError" = NULL WHERE "status" = 'dead'`);
    },
  };
}

/** Server reader of the per-account ledger facts (Cyrus' own tables). */
export async function accountFacts(db: RawDb, limit = 5000): Promise<AccountFacts[]> {
  const rows = await db.$queryRawUnsafe<{ userId: string; balance: number; reserved: number; lots: bigint | number | null; held: bigint | number | null; last: number | null; stale: bigint | number | null }[]>(`
    SELECT a."userId", a."balance", a."reserved",
      (SELECT COALESCE(SUM(l."remaining"),0) FROM "CyrusTokenLot" l WHERE l."userId" = a."userId") AS lots,
      (SELECT COALESCE(SUM(r."amount"),0) FROM "CyrusTokenReservation" r WHERE r."userId" = a."userId" AND r."status" = 'held') AS held,
      (SELECT g."balanceAfter" FROM "CyrusTokenLedger" g WHERE g."userId" = a."userId" ORDER BY g."createdAt" DESC, g."id" DESC LIMIT 1) AS last,
      (SELECT COUNT(*) FROM "CyrusTokenLot" l WHERE l."userId" = a."userId" AND l."remaining" > 0 AND l."expiresAt" IS NOT NULL AND l."expiresAt" <= now()) AS stale
    FROM "CyrusTokenAccount" a ORDER BY a."updatedAt" DESC LIMIT $1`, limit);
  return rows.map((r) => ({ userId: r.userId, balance: r.balance, reserved: r.reserved, lotsRemaining: Number(r.lots ?? 0), heldSum: Number(r.held ?? 0), lastBalanceAfter: r.last === null ? null : Number(r.last), staleLots: Number(r.stale ?? 0) }));
}

