"use server";

/**
 * Cyrus admin r40: reconciliation writes (run the wallet top-up reconcile, replay dead webhooks). Same contract as
 * lib/actions-cyrus-admin.ts (role area, preview list, never impersonating, audited, redirect back with ?ok= / ?err=).
 * The wallet reconcile is the existing idempotent sweep (lib/cyrus/tokens/purchase.ts reconcileWalletTopups): it only
 * credits a referenced wallet charge that has no ledger row and no refund, exactly once.
 */
import { notFound, redirect } from "next/navigation";
import type { User } from "@prisma/client";
import { impersonating, realUser } from "./auth";
import { requireArea } from "./rbac";
import { isPreviewUser } from "./preview-access";
import { CYRUS_ADMIN_ACTIONS, CYRUS_ADMIN_BASE, type CyrusAdminAction } from "./cyrus/admin/perms";
import { cyrusAudit } from "./cyrus/admin/audit";
import { reconcileWalletTopups, walletPayEnabled } from "./cyrus/tokens/purchase";
import { sqlOutboxAdmin } from "./cyrus/admin/reconcile";
import { cyrusDb } from "./cyrus/db";

const str = (fd: FormData, k: string, max = 300) => String(fd.get(k) ?? "").trim().slice(0, max);

function go(path: string, kind: "ok" | "err", msg: string): never {
  redirect(`${path}?${new URLSearchParams({ [kind]: msg.slice(0, 300) }).toString()}`);
}

async function guard(action: CyrusAdminAction): Promise<User> {
  const admin = await requireArea(CYRUS_ADMIN_ACTIONS[action]);
  if (await impersonating()) redirect("/dashboard");
  if (!(await isPreviewUser(await realUser(), "modbuilder"))) notFound();
  return admin;
}

const REC = `${CYRUS_ADMIN_BASE}/reconcile`;

export async function adminCyrusReconcileWallet(fd: FormData) {
  const admin = await guard("reconcile.wallet");
  if (!walletPayEnabled()) go(REC, "err", "Wallet top-ups are off (CYRUS_WALLET_PAY): nothing to reconcile.");
  const days = Math.min(30, Math.max(1, Math.floor(Number(fd.get("days"))) || 7));
  const r = await reconcileWalletTopups({ sinceMs: Date.now() - days * 86_400_000 });
  await cyrusAudit({ actorId: admin.id, action: "reconcile.wallet", target: "wallet:cwt", after: { ...r, days }, note: str(fd, "note") });
  go(REC, "ok", `Checked ${r.checked} wallet charge(s) from the last ${days} day(s); credited ${r.credited} that had no tokens.`);
}

export async function adminCyrusReplayWebhook(fd: FormData) {
  const admin = await guard("webhook.replay");
  const ob = sqlOutboxAdmin(cyrusDb);
  if (!(await ob.available().catch(() => false))) go(REC, "err", "The webhook outbox table is not created yet (prisma/manual-migration-cyrus-api-v1.sql).");
  const all = fd.get("all") === "1";
  const id = str(fd, "id", 160);
  if (!all && !/^[A-Za-z0-9_:.-]{1,160}$/.test(id)) go(REC, "err", "Bad event id.");
  const n = all ? await ob.replayAllDead() : await ob.replay(id);
  await cyrusAudit({ actorId: admin.id, action: "webhook.replay", target: all ? "webhook:dead:*" : `webhook:${id}`, after: { requeued: n } });
  go(REC, "ok", n ? `${n} event(s) back in the queue; the worker sends them on its next pass.` : "Nothing to replay (only dead events can be replayed).");
}
