// Cyrus in-app bell (r40): unread badge + the latest notifications, mark read, link to the preference center.
// Renders only when the layout mounts it (CYRUS_NOTIFY=1). Black/white with the blue -> violet accent.
import { useCallback, useEffect, useRef, useState } from "react";

type Item = { id: string; event: string; title: string; body: string; href: string | null; readAt: string | null; createdAt: string };

export function NotificationBell({ prefsHref = "/dashboard/cyrus/notifications" }: { prefsHref?: string }) {
  const [open, setOpen] = useState(false);
  const [items, setItems] = useState<Item[]>([]);
  const [unread, setUnread] = useState(0);
  const box = useRef<HTMLDivElement>(null);
  const load = useCallback(async () => {
    try {
      const r = await fetch("/api/cyrus/notifications", { cache: "no-store" });
      if (!r.ok) return;
      const j = (await r.json()) as { unread: number; items: Item[] };
      setItems(j.items); setUnread(j.unread);
    } catch { /* offline: keep what we have */ }
  }, []);
  useEffect(() => { void load(); const t = setInterval(load, 60_000); return () => clearInterval(t); }, [load]);
  useEffect(() => {
    if (!open) return;
    const close = (e: MouseEvent | KeyboardEvent) => { if (e instanceof KeyboardEvent ? e.key === "Escape" : !box.current?.contains(e.target as Node)) setOpen(false); };
    document.addEventListener("mousedown", close); document.addEventListener("keydown", close);
    return () => { document.removeEventListener("mousedown", close); document.removeEventListener("keydown", close); };
  }, [open]);
