    await fetch("/api/cyrus/notifications", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body) }).catch(() => {});
    void load();
  };
  return (
    <div ref={box} className="relative" data-cyrus-bell>
      <button type="button" onClick={() => setOpen((o) => !o)} aria-label={unread ? `Notifications, ${unread} unread` : "Notifications"} aria-expanded={open}
        className="relative grid h-10 w-10 place-items-center rounded-full border border-white/10 bg-black/70 text-white backdrop-blur hover:border-white/30 focus-visible:outline focus-visible:outline-2 focus-visible:outline-[#3d7bff]">
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" aria-hidden="true"><path d="M6 8a6 6 0 1 1 12 0c0 7 3 9 3 9H3s3-2 3-9" /><path d="M10.3 21a1.94 1.94 0 0 0 3.4 0" /></svg>
        {unread ? <span className="absolute -right-0.5 -top-0.5 min-w-[18px] rounded-full bg-gradient-to-r from-[#3d7bff] to-[#8b5cff] px-1 text-center text-[10px] font-semibold leading-[18px] text-white">{unread > 99 ? "99+" : unread}</span> : null}
      </button>
      {open ? (
        <div role="dialog" aria-label="Notifications" className="absolute right-0 z-50 mt-2 w-[min(22rem,calc(100vw-2rem))] overflow-hidden rounded-2xl border border-white/10 bg-[#07070c] text-white shadow-2xl">
          <div className="flex items-center justify-between border-b border-white/10 px-4 py-3">
            <p className="text-sm font-semibold">Notifications</p>
            {unread ? <button type="button" onClick={() => mark({ all: true })} className="text-xs text-[#9cc0ff] hover:underline">Mark all read</button> : null}
          </div>
          {items.length === 0 ? <p className="px-4 py-6 text-center text-sm text-white/50">Nothing yet.</p> : (
            <ul className="max-h-[60vh] divide-y divide-white/[0.06] overflow-y-auto">{items.map((i) => (
              <li key={i.id} className={i.readAt ? "opacity-60" : ""}>
                <a href={i.href ?? prefsHref} onClick={() => { if (!i.readAt) void mark({ id: i.id }); }} className="block px-4 py-3 hover:bg-white/[0.04]">
                  <p className="flex items-center gap-2 text-sm font-medium">{!i.readAt ? <span className="h-1.5 w-1.5 shrink-0 rounded-full bg-[#3d7bff]" aria-label="unread" /> : null}{i.title}</p>
                  <p className="mt-0.5 line-clamp-2 text-xs text-white/60">{i.body}</p>
                  <p className="mt-1 text-[10px] uppercase tracking-wider text-white/35">{new Date(i.createdAt).toLocaleString()}</p>
                </a>
              </li>
            ))}</ul>
          )}
          <a href={prefsHref} className="block border-t border-white/10 px-4 py-2.5 text-center text-xs text-white/60 hover:text-white">Notification settings</a>
        </div>
      ) : null}
    </div>
  );
}
