import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { getHost } from "@/lib/cyrus/host";
import { NOTIFY_EVENTS, notifyEmailEnabled, notifyEnabled, wants } from "@/lib/cyrus/notify/events";
import { listNotifications, loadPrefs } from "@/lib/cyrus/notify";
import { markAllNotificationsRead, saveNotifyPrefs } from "@/lib/cyrus/notify/actions";

export const dynamic = "force-dynamic";
export const metadata: Metadata = { title: "Cyrus notifications", robots: { index: false, follow: false } };

/** Cyrus r40: the ONE preference center (bell + email per event) and the full notification list. */
export default async function CyrusNotifications({ searchParams }: { searchParams: Promise<Record<string, string | string[] | undefined>> }) {
  if (!notifyEnabled()) notFound();
  const u = await getHost().builds.accessUser();
  if (!u) notFound();
  const sp = await searchParams;
  const [prefs, items] = await Promise.all([loadPrefs(u.id), listNotifications(u.id, 100)]);
  const emailOn = notifyEmailEnabled();
  return (
    <main className="mx-auto w-full max-w-3xl px-4 py-8 text-white sm:px-6">
      <h1 className="text-2xl font-semibold tracking-tight">Notifications</h1>
      <p className="mt-1 text-sm text-white/60">Choose what Cyrus tells you, and where. Email comes from a cyrus.my address.</p>
      {sp.saved ? <p role="status" className="mt-4 rounded-xl border border-[#3d7bff]/40 bg-[#3d7bff]/10 px-4 py-2 text-sm">Saved.</p> : null}
      {sp.err ? <p role="alert" className="mt-4 rounded-xl border border-red-400/40 bg-red-500/10 px-4 py-2 text-sm">Could not save right now. Please try again.</p> : null}
      {items === null ? <p className="mt-4 rounded-xl border border-white/10 px-4 py-3 text-sm text-white/60">Notifications are not set up on this server yet.</p> : null}

      <form action={saveNotifyPrefs} className="mt-6 overflow-hidden rounded-2xl border border-white/10">
        <div className="hidden grid-cols-[1fr_5rem_5rem] gap-2 border-b border-white/10 px-4 py-2 text-xs uppercase tracking-wider text-white/40 sm:grid"><span>Event</span><span className="text-center">In app</span><span className="text-center">Email</span></div>
        <ul className="divide-y divide-white/[0.06]">{NOTIFY_EVENTS.map((e) => (
          <li key={e.id} className="grid gap-2 px-4 py-3 sm:grid-cols-[1fr_5rem_5rem] sm:items-center">
            <div><p className="text-sm font-medium">{e.label}</p><p className="text-xs text-white/50">{e.what}</p></div>
            {(["inApp", "email"] as const).map((ch) => { const req = e.required?.includes(ch); return (
              <label key={ch} className="flex items-center gap-2 text-xs text-white/70 sm:justify-center">
                <input type="checkbox" name={`${e.id}:${ch}`} value="1" defaultChecked={wants(prefs, e.id, ch)} disabled={req} className="h-4 w-4 accent-[#3d7bff]" />
                <span className="sm:hidden">{ch === "inApp" ? "In app" : "Email"}</span>{req ? <span className="text-white/40">(always)</span> : null}
              </label>
            ); })}
          </li>
        ))}</ul>
        <div className="flex flex-wrap items-center justify-between gap-3 border-t border-white/10 px-4 py-3">
          <p className="text-xs text-white/40">{emailOn ? "Email is on for this server." : "Email sending is not switched on yet; your choices are kept for when it is."}</p>
          <button className="rounded-xl bg-gradient-to-r from-[#3d7bff] to-[#8b5cff] px-4 py-2 text-sm font-semibold text-white">Save</button>
        </div>
      </form>

      <section className="mt-8">
        <div className="mb-2 flex items-center justify-between"><h2 className="text-sm font-semibold">Latest</h2>{items?.some((i) => !i.readAt) ? <form action={markAllNotificationsRead}><button className="text-xs text-[#9cc0ff] hover:underline">Mark all read</button></form> : null}</div>
        {!items?.length ? <p className="rounded-2xl border border-white/10 px-4 py-6 text-center text-sm text-white/50">Nothing yet.</p> : (
          <ul className="divide-y divide-white/[0.06] overflow-hidden rounded-2xl border border-white/10">{items.map((i) => (
            <li key={i.id} className={`px-4 py-3 ${i.readAt ? "opacity-60" : ""}`}>
              <a href={i.href ?? "#"} className="block"><p className="text-sm font-medium">{i.title}</p><p className="text-xs text-white/60">{i.body}</p><p className="mt-1 text-[10px] uppercase tracking-wider text-white/35">{i.createdAt.toISOString().slice(0, 16).replace("T", " ")} UTC</p></a>
            </li>
          ))}</ul>
        )}
      </section>
    </main>
  );
}
