mkdir -p app/admin/cyrus/notify; cat > app/admin/cyrus/notify/page.tsx <<'EOF'
import type { Metadata } from "next";
import { db } from "@/lib/db";
import { realUser } from "@/lib/auth";
import { requireCyrusAdmin, cyrusAdminMetadata } from "@/lib/cyrus/admin/gate";
import { canCyrusAdmin } from "@/lib/cyrus/admin/perms";
import { MAIL_FROM_SETTING, NOTIFY_EVENTS, notifyEmailEnabled, notifyEnabled, validCyrusSender } from "@/lib/cyrus/notify/events";
import { renderNotification, SAMPLE_DATA } from "@/lib/cyrus/notify/templates";
import { cyrusDb } from "@/lib/cyrus/db";
import { adminCyrusSetSetting } from "@/lib/actions-cyrus-admin";
import { Badge } from "@/components/ui/primitives";
import { Empty, Flash, Hidden, Kv, Section, TableWrap, n, tdRow, thCls } from "@/components/admin/cyrus/ui";

export const dynamic = "force-dynamic";
export async function generateMetadata(): Promise<Metadata> {
  return cyrusAdminMetadata("Notifications");
}

/** Cyrus r40: the one notification system, staff side: switches, sender, what was sent, template previews. */
export default async function CyrusNotifyAdmin({ searchParams }: { searchParams: Promise<Record<string, string | string[] | undefined>> }) {
  await requireCyrusAdmin("notify");
  const me = (await realUser())!;
  const sp = await searchParams;
  const since = new Date(Date.now() - 30 * 86_400_000);
  const [fromRow, byEvent] = await Promise.all([
    db.setting.findUnique({ where: { key: MAIL_FROM_SETTING } }),
    cyrusDb.cyrusNotification.groupBy({ by: ["event", "email"], where: { createdAt: { gt: since } }, _count: { _all: true } }).catch(() => null),
  ]);
  const from = fromRow?.value ?? "";
  const pick = typeof sp.t === "string" && NOTIFY_EVENTS.some((e) => e.id === sp.t) ? (sp.t as (typeof NOTIFY_EVENTS)[number]["id"]) : "build.finished";
  const base = (process.env.CYRUS_PUBLIC_BASE || process.env.APP_URL || "https://nxeon.cloud").replace(/\/$/, "");
  const preview = renderNotification(pick, SAMPLE_DATA[pick], { appBase: base, prefsUrl: `${base}/dashboard/cyrus/notifications` });
  const canSet = canCyrusAdmin(me.role, "notify.sender");
  return (
    <div>
      <Flash sp={sp} />
      <Section title="Status" sub="One system for every Cyrus notification: in-app bell + email, one preference center per person (/dashboard/cyrus/notifications).">
        <Kv rows={[
          ["CYRUS_NOTIFY (bell + records)", notifyEnabled() ? <Badge key="a" tone="green">on</Badge> : <Badge key="a" tone="slate">off</Badge>],
          ["CYRUS_NOTIFY_EMAIL (sending)", notifyEmailEnabled() ? <Badge key="b" tone="green">on</Badge> : <Badge key="b" tone="slate">off</Badge>],
          ["Sender", from ? (validCyrusSender(from) ? from : `${from} (not a cyrus.my address: email is skipped)`) : "not set (email is skipped)"],
          ["Mail stack", "Nxeon's mailer (same relay, EmailLog rows, open/click tracking)"],
          ["DNS for cyrus.my", "SPF / DKIM / DMARC checklist: docs/DOCUMENTATION.md, Cyrus email sender (written, not applied)"],
        ]} />
        {canSet ? (
          <form action={adminCyrusSetSetting} className="mt-3 flex flex-wrap items-center gap-2">
            <Hidden name="key" value={MAIL_FROM_SETTING} /><Hidden name="back" value="/admin/cyrus/notify" />
            <input name="value" defaultValue={from} placeholder="Cyrus <hello@cyrus.my>" className="input text-sm sm:w-72" aria-label="Sender" />
            <label className="flex items-center gap-1 text-xs"><input type="checkbox" name="confirm" value="1" /> DNS checklist done</label>
            <button className="btn-secondary text-sm">Save sender</button>
          </form>
        ) : null}
      </Section>

      <Section title="Last 30 days" sub="Recorded notifications per event and what happened to the email.">
        {byEvent === null ? <Empty>The notification tables are not migrated yet (prisma/manual-migrations/2026-10-11-cyrus-notifications.sql).</Empty> : byEvent.length === 0 ? <Empty>Nothing recorded yet.</Empty> : (
          <TableWrap>
            <table className="w-full text-sm">
              <thead><tr className={thCls}><th>Event</th><th>Email</th><th className="text-right">Count</th></tr></thead>
              <tbody>{byEvent.map((r) => <tr key={`${r.event}:${r.email}`} className={tdRow}><td className="font-mono text-xs">{r.event}</td><td className="text-xs">{r.email ?? "not attempted"}</td><td className="text-right tabular-nums">{n(r._count._all)}</td></tr>)}</tbody>
            </table>
          </TableWrap>
        )}
      </Section>

      <Section title="Templates" sub="Rendered from sample data (never sent). Copy is built from the event's own data only.">
        <nav className="mb-3 flex flex-wrap gap-2" aria-label="Template">{NOTIFY_EVENTS.map((e) => <a key={e.id} href={`/admin/cyrus/notify?t=${e.id}`} aria-current={e.id === pick ? "page" : undefined} className={`rounded-full border px-3 py-1 text-xs ${e.id === pick ? "border-white/30 bg-white/10" : "border-white/10 text-slate-400"}`}>{e.label}</a>)}</nav>
        <p className="mb-2 text-sm"><span className="text-slate-500">Subject</span> {preview.subject}</p>
        <iframe title={`${pick} email preview`} sandbox="" srcDoc={preview.html} className="h-[480px] w-full rounded-lg border border-white/10 bg-black" />
        <details className="mt-2"><summary className="cursor-pointer text-xs text-slate-400">Plain-text part</summary><pre className="mt-1 whitespace-pre-wrap text-xs text-slate-300">{preview.text}</pre></details>
      </Section>
    </div>
  );
}
EOF
