// ── (6) notifications + email ──────────────────────────────────────────────
import { NOTIFY_EVENTS, parsePrefs, prefsFromForm, refFor, validCyrusSender, wants } from "../lib/cyrus/notify/events";
import { renderNotification, SAMPLE_DATA } from "../lib/cyrus/notify/templates";
import { notify } from "../lib/cyrus/notify";
import { getHost, setHost, type CyrusHost } from "../lib/cyrus/host";

describe("r40 notifications", () => {
  it("preferences: defaults, stored overrides, required channels always on, form keeps only differences", () => {
    assert.equal(wants({}, "build.finished", "inApp"), true);
    assert.equal(wants({}, "build.finished", "email"), false);
    const p = parsePrefs({ "build.finished": { email: true, inApp: "x" }, "takedown": { email: false }, nope: { email: true } });
    assert.deepEqual(p, { "build.finished": { email: true }, takedown: { email: false } });
    assert.equal(wants(p, "takedown", "email"), true, "takedown email cannot be turned off");
    const form = new Map([["build.finished:inApp", "1"], ["build.finished:email", "1"], ["install.result:inApp", "1"]]);
    const saved = prefsFromForm((k) => form.get(k) ?? null);
    assert.deepEqual(saved["build.finished"], { email: true });
    assert.deepEqual(saved["install.result"], { email: false });
    assert.equal(saved.takedown, undefined);
  });
  it("dedupe refs and the cyrus.my sender rule", () => {
    assert.equal(refFor("build.finished", { buildId: "b1", status: "failed" }), "b1:failed");
    assert.equal(refFor("tokens.low", { at: Date.UTC(2026, 9, 11, 15) }), "2026-10-11");
    assert.equal(validCyrusSender("Cyrus <hello@cyrus.my>"), true);
    assert.equal(validCyrusSender("hello@cyrus.my"), true);
    assert.equal(validCyrusSender("Cyrus <hello@nxeon.cloud>"), false);
    assert.equal(validCyrusSender("x@cyrus.my\r\nBcc: a@b.c"), false);
  });
  it("templates escape data, keep links on the app origin, carry the Cyrus palette", () => {
    for (const e of NOTIFY_EVENTS) {
      const r = renderNotification(e.id, SAMPLE_DATA[e.id], { appBase: "https://cyrus.my", prefsUrl: "https://cyrus.my/dashboard/cyrus/notifications" });
      assert.ok(r.subject && r.text.includes("notifications"), e.id);
      assert.ok(r.html.includes("#050508") && r.html.includes("#3d7bff") && r.html.includes("#8b5cff"), e.id);
    }
    const evil = renderNotification("build.finished", { name: "<script>alert(1)</script>", status: "succeeded", buildId: "x\"><img src=x>" }, { appBase: "https://cyrus.my", prefsUrl: "https://cyrus.my/p" });
    assert.ok(!evil.html.includes("<script>alert"));
    assert.ok(!/href="[^"]*<img/.test(evil.html));
    assert.ok(evil.href!.startsWith("https://cyrus.my/"));
  });
  it("notify(): off does nothing; on records once (dedupe), email only with flag + sender + mailer + preference", async () => {
    const rows = new Map<string, Record<string, unknown>>(); const sent: { to: string; from: string }[] = [];
    const key = (d: Record<string, unknown>) => `${d.userId}|${d.event}|${d.ref}`;
    const fakeDb = {
      cyrusNotificationPref: { findUnique: async () => null },
      cyrusNotification: {
        create: async ({ data }: { data: Record<string, unknown> }) => { if ([...rows.values()].some((r) => key(r) === key(data))) throw Object.assign(new Error("dup"), { code: "P2002" }); rows.set(String(data.id), { ...data }); return data; },
        update: async ({ where, data }: { where: { id: string }; data: Record<string, unknown> }) => { Object.assign(rows.get(where.id)!, data); return rows.get(where.id); },
      },
    };
    let from = "";
    const prev = getHost();
    const restore = setHost({ ...prev, db: fakeDb as never, settings: { ...prev.settings, get: async () => from }, users: { ...prev.users, get: async (id: string) => ({ id, email: `${id}@example.com` }) }, mail: { send: async (m: { to: string; from: string }) => { sent.push(m); return true; } } } as unknown as CyrusHost);
    try {
      assert.equal((await notify("u1", "install.result", { jobId: "j1", ok: true }, {})).reason, "off");
      const ON = { CYRUS_NOTIFY: "1" };
      const a = await notify("u1", "install.result", { jobId: "j1", ok: true, name: "M" }, ON);
      assert.deepEqual(a, { recorded: true, email: "skipped:email_off" });
      assert.equal((await notify("u1", "install.result", { jobId: "j1", ok: true }, ON)).reason, "duplicate");
      const EM = { CYRUS_NOTIFY: "1", CYRUS_NOTIFY_EMAIL: "1" };
      assert.equal((await notify("u1", "install.result", { jobId: "j2", ok: false }, EM)).email, "skipped:no_sender");
      from = "Cyrus <hello@cyrus.my>";
      assert.equal((await notify("u1", "install.result", { jobId: "j3", ok: true }, EM)).email, "sent");
      assert.equal((await notify("u1", "build.finished", { buildId: "b1", status: "succeeded" }, EM)).email, "skipped:preference");
      assert.deepEqual(sent.map((s) => [s.to, s.from]), [["u1@example.com", "Cyrus <hello@cyrus.my>"]]);
      assert.equal(rows.size, 4);
    } finally { restore(); }
  });
});
