// the staff account, the customer and an expiry; the page refuses a missing, foreign or expired grant. PURE + node:crypto.
import { createHmac, timingSafeEqual } from "node:crypto";

export const VIEW_GRANT_MS = 30 * 60_000;

function key(secret: string) {
  return createHmac("sha256", secret).update("cyrus-admin-viewas-v1").digest();
}

export function mintViewGrant(secret: string, adminId: string, userId: string, nowMs: number): string {
  const exp = nowMs + VIEW_GRANT_MS;
  const mac = createHmac("sha256", key(secret)).update(`${adminId}\n${userId}\n${exp}`).digest("base64url");
  return `${exp}.${mac}`;
}

export function checkViewGrant(secret: string, grant: string, adminId: string, userId: string, nowMs: number): boolean {
  const m = /^(\d{13})\.([A-Za-z0-9_-]{43})$/.exec(grant);
