cd /tank/dev-worktrees/cyrus-r40; mkdir -p "app/admin/cyrus/view/[userId]"; cat > "app/admin/cyrus/view/[userId]/page.tsx" <<'EOF'
import type { Metadata } from "next";
import Link from "next/link";
import { notFound } from "next/navigation";
import { db } from "@/lib/db";
import { realUser } from "@/lib/auth";
import { requireArea } from "@/lib/rbac";
import { isPreviewUser } from "@/lib/preview-access";
import { CYRUS_ADMIN_ACTIONS, canCyrusAdmin } from "@/lib/cyrus/admin/perms";
import { checkViewGrant } from "@/lib/cyrus/admin/viewas";
import { cyrusAdminMetadata } from "@/lib/cyrus/admin/gate";
import { flightLabel } from "@/lib/cyrus/admin/ops";
import { tokenSummary } from "@/lib/cyrus/tokens/ledger";
import { listNotifications } from "@/lib/cyrus/notify";
import { loadSuspensions } from "@/lib/cyrus/suspensions";
import { getHost } from "@/lib/cyrus/host";
import { Badge, StatCard } from "@/components/ui/primitives";
import { Empty, Section, TableWrap, n, tdRow, thCls, usd, when } from "@/components/admin/cyrus/ui";

export const dynamic = "force-dynamic";
export async function generateMetadata(): Promise<Metadata> {
  return cyrusAdminMetadata("View as (read-only)");
}

/**
 * Cyrus r40: a READ-ONLY staff view of one customer's Cyrus account. Reached only through the audited "View their Cyrus"
 * action (lib/actions-cyrus-admin-core.ts), which mints a 30-minute grant bound to this staff account and this customer.
 * No form on this page writes anything, and nothing here acts as the customer.
 */
export default async function CyrusViewAs({ params, searchParams }: { params: Promise<{ userId: string }>; searchParams: Promise<Record<string, string | string[] | undefined>> }) {
  const staff = await requireArea(CYRUS_ADMIN_ACTIONS["user.viewas"]);
  const me = await realUser();
  if (!me || me.id !== staff.id || !(await isPreviewUser(me, "modbuilder")) || !canCyrusAdmin(me.role, "user.viewas")) notFound();
  const { userId } = await params;
  const sp = await searchParams;
  const g = typeof sp.g === "string" ? sp.g : "";
  if (!/^[A-Za-z0-9_-]{1,64}$/.test(userId) || !checkViewGrant(process.env.AUTH_SECRET ?? "", g, me.id, userId, Date.now())) {
    return <Section title="View as"><Empty>This view has expired or was not started from the account page. Start it again from Users &amp; tokens (every view is audited).</Empty></Section>;
  }
  const user = await db.user.findUnique({ where: { id: userId }, select: { id: true, email: true, name: true, role: true, suspended: true } });
  if (!user || user.role !== "CUSTOMER") notFound();
  const [summary, plan, projects, builds, pages, notes, servers, susp] = await Promise.all([
    tokenSummary(user.id).catch(() => null),
    db.cyrusPlan.findUnique({ where: { userId: user.id } }),
    db.cyrusProject.findMany({ where: { userId: user.id }, orderBy: { updatedAt: "desc" }, take: 20 }).catch(() => []),
    db.modBuild.findMany({ where: { userId: user.id }, orderBy: { createdAt: "desc" }, take: 25, select: { id: true, status: true, errorCode: true, pluginName: true, version: true, mcVersion: true, prompt: true, changeRequest: true, costUsd: true, createdAt: true, cyrus: true } }),
    db.cyrusModPage.findMany({ where: { userId: user.id }, orderBy: { updatedAt: "desc" }, take: 20, select: { id: true, slug: true, title: true, hiddenAt: true, hiddenReason: true } }).catch(() => []),
    listNotifications(user.id, 20),
    getHost().servers.listForUser(user.id).catch(() => []),
    loadSuspensions(),
  ]);
  const s = susp.find((x) => x.userId === user.id);
  return (
    <div>
      <div role="status" className="mb-5 flex flex-wrap items-center gap-2 rounded-xl border border-amber-400/30 bg-amber-500/10 px-4 py-3 text-sm">
        <Badge tone="amber">read-only</Badge>
        <span>Viewing Cyrus as <b>{user.email}</b>. Nothing on this page acts as them. This view was audited and ends in 30 minutes.</span>
        <Link className="ml-auto underline" href={`/admin/cyrus/users?u=${encodeURIComponent(user.id)}`}>Back to the account</Link>
      </div>
      <div className="mb-6 grid grid-cols-2 gap-3 lg:grid-cols-4">
        <StatCard label="Available tokens" value={summary ? n(summary.available) : "–"} delta={summary ? `${n(summary.reserved)} held` : "no account"} />
        <StatCard label="Plan" value={plan ? plan.priceTier : "none"} delta={plan ? `${plan.status}${plan.livemode ? "" : " · test"}` : "no subscription"} />
        <StatCard label="Builds (latest 25)" value={n(builds.length)} />
        <StatCard label="Standing" value={user.suspended ? "Nxeon suspended" : s ? "Cyrus suspended" : "ok"} deltaGood={!user.suspended && !s} delta={s ? s.reason : ""} />
      </div>
      <div className="grid min-w-0 xl:grid-cols-2 xl:gap-6">
        <Section title="Projects">
          {!projects.length ? <Empty>No projects.</Empty> : <ul className="space-y-1 text-sm">{projects.map((p) => { const r = p as unknown as { id: string; name?: string | null; title?: string | null; updatedAt: Date }; return <li key={r.id} className="flex justify-between gap-2"><span className="truncate">{r.name ?? r.title ?? r.id}</span><span className="shrink-0 text-xs text-slate-500">{when(r.updatedAt)}</span></li>; })}</ul>}
        </Section>
        <Section title="Servers they can install to">
          {!servers.length ? <Empty>No game servers.</Empty> : <ul className="space-y-1 text-sm">{servers.map((x) => <li key={x.id} className="flex justify-between gap-2"><span className="truncate">{x.label ?? x.hostname}</span><span className="text-xs text-slate-500">{x.status}</span></li>)}</ul>}
        </Section>
      </div>
      <Section title="Builds" sub="What they see on their build list (prompts included).">
        {!builds.length ? <Empty>No builds.</Empty> : (
          <TableWrap>
            <table className="w-full text-sm">
              <thead><tr className={thCls}><th>When</th><th>Mod</th><th>Status</th><th>Flight</th><th className="text-right">AI cost</th></tr></thead>
              <tbody>{builds.map((b) => <tr key={b.id} className={tdRow}><td className="whitespace-nowrap text-xs">{when(b.createdAt)}</td><td className="max-w-[320px]"><Link className="underline" href={`/admin/cyrus/builds/${b.id}`}>{b.pluginName ?? b.id}</Link>{b.version ? ` v${b.version}` : ""} <span className="text-xs text-slate-500">{b.mcVersion}</span><div className="truncate text-xs text-slate-500">{(b.changeRequest || b.prompt).slice(0, 120)}</div></td><td>{b.status}{b.errorCode ? ` (${b.errorCode})` : ""}</td><td className="text-xs">{flightLabel(b.cyrus) ?? "–"}</td><td className="text-right tabular-nums">{usd(b.costUsd, 3)}</td></tr>)}</tbody>
            </table>
          </TableWrap>
        )}
      </Section>
      <div className="grid min-w-0 xl:grid-cols-2 xl:gap-6">
        <Section title="Mod pages">
          {!pages.length ? <Empty>No mod pages.</Empty> : <ul className="space-y-1 text-sm">{pages.map((p) => <li key={p.id} className="flex justify-between gap-2"><span className="truncate">{p.title}</span>{p.hiddenAt ? <Badge tone="red">taken down</Badge> : <Badge tone="green">live</Badge>}</li>)}</ul>}
        </Section>
        <Section title="Their notifications">
          {!notes?.length ? <Empty>{notes === null ? "Notifications are not set up yet." : "None."}</Empty> : <ul className="space-y-1.5 text-sm">{notes.map((x) => <li key={x.id}><p className="font-medium">{x.title}</p><p className="text-xs text-slate-500">{when(x.createdAt)}{x.readAt ? " · read" : " · unread"}</p></li>)}</ul>}
        </Section>
      </div>
    </div>
  );
}
EOF
