/**
 * Cookie-consent state, shared between the banner and the two floating widgets
 * it used to sit on top of.
 *
 * The banner (`components/marketing/CookieConsent.tsx`), the chat bubble
 * (`components/ChatWidget.tsx`) and the feedback button
 * (`components/FeedbackWidget.tsx`) all occupy the bottom of the viewport. On a
 * first visit the banner is the only one of the three the visitor must act on,
 * so it wins the stacking order — and the other two get out of its way until a
 * choice exists. That needs one definition of "has a choice been made", plus a
 * way for the widgets to hear about the choice the moment it is made rather than
 * on the next page load.
 *
 * Browser-only module: no imports, safe in any client component.
 */

export const CONSENT_COOKIE = "nxeon_cookie_consent";
export const CONSENT_MAX_AGE = 60 * 60 * 24 * 365;

/** Fired on `window` when a visitor accepts or declines, so widgets re-measure. */
export const CONSENT_EVENT = "nxeon:cookie-consent";

/** True once the visitor has chosen. SSR-safe: assumes chosen, so nothing moves. */
export function hasCookieConsent(): boolean {
  if (typeof document === "undefined") return true;
  try {
    return document.cookie.split("; ").some((c) => c.startsWith(`${CONSENT_COOKIE}=`));
  } catch {
    // Cookies blocked entirely — treat as decided so we never pin a banner-shaped
    // hole in the corner of a page whose banner will never appear.
    return true;
  }
}

export function setCookieConsent(value: "all" | "necessary") {
  document.cookie = `${CONSENT_COOKIE}=${value}; path=/; max-age=${CONSENT_MAX_AGE}; SameSite=Lax`;
}

/**
 * The visitor's actual choice: "all" (accepted analytics + marketing cookies),
119:  // Cyrus host (cyrus.my, CYRUS_DOMAIN_MODE): middleware only lets /dashboard/cyrus through there; it gets the Cyrus

    ],
  },
];

/* viewport-fit=cover lets the portal's bottom tab bar and drawer pad themselves
   with env(safe-area-inset-*) on notched phones; only this subtree uses env(). */
export const viewport = { width: "device-width", initialScale: 1, viewportFit: "cover" } as const;

export default async function DashboardLayout({ children }: { children: React.ReactNode }) {
  // Cyrus host (cyrus.my, CYRUS_DOMAIN_MODE): middleware only lets /dashboard/cyrus through there; it gets the Cyrus
  // brand chrome instead of the portal's. The marker header is set solely by middleware (stripped from requests).
  if ((await headers()).get(CYRUS_HOST_HEADER) === "1") return <CyrusHostShell>{children}</CyrusHostShell>;
  const user = await currentUser();
  if (!user) {
    // Where they were actually headed — critically, a marketing "Deploy"
    // button's full query string (game/plan/addon selection, see
    // lib/deploy-intent.ts), not just the bare path. Without this, EVERY
    // logged-out visit to any /dashboard/* route lost its destination on this
    // redirect, silently dropping the selection a Deploy click had just
    // encoded. `x-pathname`/`x-search` come from middleware.ts (Server
    // Components can't read the current URL directly); `safeNext` is the
    // same single-slash-absolute-path allowlist every other `?next=`
    // producer already uses (lib/safe-next.ts), so this is never a second
    // validation rule to keep in sync.
    const h = await headers();
    const dest = safeNext(`${h.get("x-pathname") ?? "/dashboard"}${h.get("x-search") ?? ""}`);
    // mkt-011 (flag growth_guest_configurator, default off): a logged-out visitor to the
    // deploy wizard — which is where EVERY marketing "Deploy" button lands — gets the public
    // configurator with their selection carried in the same query, instead of a login wall.
    // They sign up at its Payment step and resume here.
    if (dest && (dest === "/dashboard/deploy" || dest.startsWith("/dashboard/deploy?")) && (await getSettingBool("growth_guest_configurator", false))) {

import { redirect } from "next/navigation";
import { headers } from "next/headers";
import { currentUser } from "@/lib/auth";
import { bridgeConfig } from "@/lib/cyrus/bridge/config";
import { safeCyrusNext } from "@/lib/cyrus/bridge/routing";
import { CyrusWordmark } from "@/components/cyrus/brand/CyrusBrand";
import { CyrusTokenChip } from "@/components/cyrus-tokens";

/**
 * The Cyrus-host (cyrus.my) chrome: Cyrus' own brand bar around the SAME studio pages Nxeon serves at
 * /dashboard/cyrus (no copied components). Chosen by app/dashboard/layout.tsx when middleware marked the request as
 * Cyrus-host (CYRUS_DOMAIN_MODE). Signed-out visitors go to the Cyrus sign-in, which delegates to the Nxeon identity.
 */
export async function CyrusHostShell({ children }: { children: React.ReactNode }) {
  const user = await currentUser();
  if (!user) {
    const h = await headers();
    const next = safeCyrusNext(`${h.get("x-pathname") ?? "/studio"}${h.get("x-search") ?? ""}`);
    redirect(`/sign-in?next=${encodeURIComponent(next)}`);
  }
  const nxeon = bridgeConfig().nxeonOrigin;
  return (
    <div className="cyrus-host flex h-dvh flex-col bg-[#05060a] text-white">
      <header className="flex h-12 shrink-0 items-center gap-4 border-b border-white/10 px-4">
        <a href="/studio" aria-label="Cyrus studio"><CyrusWordmark height={20} /></a>
        <span className="text-xs text-white/50">A Nxeon product</span>
        <div className="ml-auto flex items-center gap-3 text-sm">
          <CyrusTokenChip compact beta={false} />
          <a className="text-white/70 hover:text-white" href={`${nxeon}/dashboard/servers`}>My servers</a>
          <a className="text-white/70 hover:text-white" href={`${nxeon}/dashboard/billing`}>Wallet</a>
          <span className="hidden text-white/50 sm:inline">{user.name || user.email}</span>
          <form method="post" action="/auth/logout"><button className="text-white/70 hover:text-white" type="submit">Sign out</button></form>
        </div>
      </header>
      <main className="min-h-0 flex-1">{children}</main>
    </div>
  );
}
