export type Attribution = { ref?: string; utm?: { source?: string; medium?: string; campaign?: string; content?: string; term?: string }; click?: { fbclid?: string; gclid?: string }; landing?: string; at?: number };

const REF = /^[A-Za-z0-9_-]{2,32}$/;
const UTM = /^[A-Za-z0-9 ._+:/-]{1,80}$/;
const CLICK = /^[A-Za-z0-9._-]{8,200}$/;
const PATH = /^\/[A-Za-z0-9/_-]{0,80}$/;

/** What a landing URL carries (everything validated; anything odd is dropped, never stored). */
export function parseLanding(params: URLSearchParams | Record<string, string | undefined>, path = "/"): Attribution {
  const get = (k: string) => (params instanceof URLSearchParams ? params.get(k) : params[k]) ?? undefined;
  const a: Attribution = {};
  const ref = get("ref") ?? get("partner");
  if (ref && REF.test(ref)) a.ref = ref;
  const utm: NonNullable<Attribution["utm"]> = {};
  for (const k of ["source", "medium", "campaign", "content", "term"] as const) { const v = get(`utm_${k}`); if (v && UTM.test(v)) utm[k] = v; }
  if (Object.keys(utm).length) a.utm = utm;
  const click: NonNullable<Attribution["click"]> = {};
  for (const k of ["fbclid", "gclid"] as const) { const v = get(k); if (v && CLICK.test(v)) click[k] = v; }
  if (Object.keys(click).length) a.click = click;
  if (PATH.test(path)) a.landing = path;
  return a;
}

/** Keep only what the person consented to (no consent = nothing). */
export function allowedAttribution(a: Attribution, c: Consent | null): Attribution | null {
  if (!c || (!c.analytics && !c.marketing)) return null;
  const out: Attribution = {};
  if (c.analytics) { if (a.ref) out.ref = a.ref; if (a.utm) out.utm = a.utm; if (a.landing) out.landing = a.landing; }
  if (c.marketing && a.click) out.click = a.click;
  if (!Object.keys(out).length) return null;
  out.at = a.at ?? Date.now();
  return out;
}

/** First touch wins for 30 days, except a NEW referral code (an explicit partner link) replaces the old one. */
export function mergeAttribution(prev: Attribution | null, next: Attribution | null, nowMs: number): Attribution | null {
  if (!next) return prev;
