"use client";
// cyrus.my cookie consent (r40, flag CYRUS_CONSENT). Necessary cookies only until the person chooses; "Reject all" is
// as prominent as "Accept all"; "Choose" offers analytics and marketing separately. On a choice it also stores the
// landing attribution the person allowed (CYRUS_ATTRIBUTION). Rules: lib/cyrus/analytics/consent.ts.
import { useEffect, useState } from "react";
import { ATTR_MAX_AGE_S, CONSENT_MAX_AGE_S, CYRUS_ATTR_COOKIE, CYRUS_CONSENT_COOKIE, allowedAttribution, decodeAttribution, encodeAttribution, mergeAttribution, parseConsent, parseLanding, serializeConsent } from "@/lib/cyrus/analytics/consent";

const read = (name: string) => { try { return document.cookie.split("; ").find((c) => c.startsWith(`${name}=`))?.slice(name.length + 1) ?? null; } catch { return null; } };
const write = (name: string, value: string, maxAge: number) => { document.cookie = `${name}=${value}; path=/; max-age=${maxAge}; SameSite=Lax${location.protocol === "https:" ? "; Secure" : ""}`; };

export function ConsentBanner({ attribution = false }: { attribution?: boolean }) {
  const [show, setShow] = useState(false);
  const [choose, setChoose] = useState(false);
  const [a, setA] = useState(false);
  const [m, setM] = useState(false);
  useEffect(() => {
    setShow(!parseConsent(read(CYRUS_CONSENT_COOKIE)));
    const reopen = () => { setShow(true); setChoose(true); };
    window.addEventListener("cyrus:cookie-settings", reopen);
    return () => window.removeEventListener("cyrus:cookie-settings", reopen);
  }, []);
  const decide = (analytics: boolean, marketing: boolean) => {
    const v = serializeConsent({ analytics, marketing }, Date.now());
    write(CYRUS_CONSENT_COOKIE, v, CONSENT_MAX_AGE_S);
    const c = parseConsent(v);
    if (attribution) {
      const next = allowedAttribution(parseLanding(new URLSearchParams(location.search), location.pathname), c);
      const merged = mergeAttribution(decodeAttribution(read(CYRUS_ATTR_COOKIE)), next, Date.now());
      const allowed = merged ? allowedAttribution(merged, c) : null;
      const enc = allowed ? encodeAttribution(allowed) : null;
      if (enc) write(CYRUS_ATTR_COOKIE, enc, ATTR_MAX_AGE_S); else write(CYRUS_ATTR_COOKIE, "", 0);
    }
    window.dispatchEvent(new CustomEvent("cyrus:cookie-consent", { detail: { analytics, marketing } }));
    setShow(false);
  };
  if (!show) return null;
  return (
    <div role="dialog" aria-modal="false" aria-labelledby="cyrus-consent-title" className="fixed inset-x-3 bottom-3 z-[60] mx-auto max-w-xl rounded-2xl border border-white/10 bg-[#07070c]/95 p-4 text-white shadow-2xl backdrop-blur sm:inset-x-6 sm:bottom-6">
      <p id="cyrus-consent-title" className="text-sm font-semibold">Cookies on Cyrus</p>
      <p className="mt-1 text-xs leading-relaxed text-white/60">We use necessary cookies to sign you in and keep you safe. With your permission we also measure visits (analytics) and which ads or partner links brought you here (marketing). Nothing optional is set until you choose.</p>
      {choose ? (
        <div className="mt-3 space-y-2 text-xs">
          <label className="flex items-center gap-2 text-white/50"><input type="checkbox" checked disabled className="h-4 w-4" /> Necessary (always on)</label>
          <label className="flex items-center gap-2"><input type="checkbox" checked={a} onChange={(e) => setA(e.target.checked)} className="h-4 w-4 accent-[#3d7bff]" /> Analytics: visits, referral code and campaign tags</label>
          <label className="flex items-center gap-2"><input type="checkbox" checked={m} onChange={(e) => setM(e.target.checked)} className="h-4 w-4 accent-[#8b5cff]" /> Marketing: ad click ids for Meta and Google conversion measurement</label>
        </div>
      ) : null}
      <div className="mt-3 grid grid-cols-2 gap-2 sm:flex sm:justify-end">
        {choose ? <button type="button" onClick={() => decide(a, m)} className="col-span-2 rounded-xl border border-white/20 px-3 py-2 text-xs font-semibold hover:bg-white/10">Save choices</button> : <button type="button" onClick={() => setChoose(true)} className="col-span-2 rounded-xl px-3 py-2 text-xs text-white/70 underline-offset-2 hover:underline sm:col-span-1">Choose</button>}
        <button type="button" onClick={() => decide(false, false)} className="rounded-xl border border-white/20 px-3 py-2 text-xs font-semibold hover:bg-white/10">Reject all</button>
        <button type="button" onClick={() => decide(true, true)} className="rounded-xl border border-white/20 px-3 py-2 text-xs font-semibold hover:bg-white/10">Accept all</button>
      </div>
    </div>
  );
}
