// ── (8) analytics + consent ─────────────────────────────────────────────────
import { allowedAttribution, conversionPayload, decodeAttribution, encodeAttribution, mergeAttribution, parseConsent, parseLanding, serializeConsent } from "../lib/cyrus/analytics/consent";

describe("r40 analytics and consent", () => {
  const now = Date.UTC(2026, 9, 11, 12);
  it("consent cookie round trip; unknown versions ask again", () => {
    const v = serializeConsent({ analytics: true, marketing: false }, now);
    assert.deepEqual(parseConsent(v), { v: 1, analytics: true, marketing: false, at: Math.floor(now / 1000) * 1000 });
    assert.equal(parseConsent("v2.a1.m1.1760000000"), null);
    assert.equal(parseConsent("all"), null);
    assert.equal(parseConsent(null), null);
  });
  it("landing params are validated; consent decides what may be kept", () => {
    const a = parseLanding(new URLSearchParams("ref=KOBBI&utm_source=youtube&utm_campaign=launch%20week&fbclid=IwAR0abcdefgh&gclid=<script>&evil=1"), "/mods");
    assert.deepEqual(a, { ref: "KOBBI", utm: { source: "youtube", campaign: "launch week" }, click: { fbclid: "IwAR0abcdefgh" }, landing: "/mods" });
    assert.equal(allowedAttribution(a, null), null);
    assert.equal(allowedAttribution(a, parseConsent(serializeConsent({ analytics: false, marketing: false }, now))), null);
    const onlyA = allowedAttribution({ ...a, at: now }, parseConsent(serializeConsent({ analytics: true, marketing: false }, now)))!;
    assert.equal(onlyA.click, undefined); assert.equal(onlyA.ref, "KOBBI");
    const onlyM = allowedAttribution({ ...a, at: now }, parseConsent(serializeConsent({ analytics: false, marketing: true }, now)))!;
    assert.deepEqual(Object.keys(onlyM).sort(), ["at", "click"]);
  });
  it("first touch wins for 30 days; a new referral code replaces; encode/decode re-validates", () => {
    const first = { ref: "A1", utm: { source: "x" }, at: now - 86_400_000 };
    assert.equal(mergeAttribution(first, { ref: "B2", at: now }, now)!.ref, "B2");
    assert.equal(mergeAttribution(first, { utm: { source: "y" }, at: now }, now)!.utm!.source, "x");
    assert.equal(mergeAttribution({ ...first, at: now - 31 * 86_400_000 }, { utm: { source: "y" }, at: now }, now)!.utm!.source, "y");
    const enc = encodeAttribution({ ref: "A1", click: { gclid: "Cj0KCQjw-abc" }, at: now })!;
    assert.deepEqual(decodeAttribution(enc), { ref: "A1", click: { gclid: "Cj0KCQjw-abc" }, at: now });
    const forged = Buffer.from(JSON.stringify({ ref: "<img>", click: { fbclid: "x" } })).toString("base64url");
    assert.equal(decodeAttribution(forged), null);
    assert.equal(decodeAttribution("not base64!"), null);
  });
  it("conversion payloads: none without marketing consent; hashed email only; value only for purchases", () => {
    const yes = parseConsent(serializeConsent({ analytics: false, marketing: true }, now));
    assert.equal(conversionPayload({ id: "purchase", eventId: "plan:in_123", atMs: now, consent: parseConsent(serializeConsent({ analytics: true, marketing: false }, now)), attribution: null, valueCents: 1999 }), null);
    const p = conversionPayload({ id: "purchase", eventId: "plan:in_123", atMs: now, consent: yes, attribution: { click: { fbclid: "IwAR0abcdefgh", gclid: "Cj0KCQjw-abc" } }, valueCents: 1999, emailSha256: "a".repeat(64) })!;
    assert.equal(p.meta.event_name, "Purchase");
    assert.deepEqual(p.meta.custom_data, { value: 19.99, currency: "USD" });
    assert.deepEqual((p.meta.user_data as { em: string[] }).em, ["a".repeat(64)]);
    assert.equal(p.google.gclid, "Cj0KCQjw-abc");
    const s = conversionPayload({ id: "sign_up", eventId: "signup:u_1", atMs: now, consent: yes, attribution: null, valueCents: 500, emailSha256: "raw@example.com" })!;
    assert.equal(s.meta.custom_data, undefined);
    assert.deepEqual(s.meta.user_data, {});
  });
});
