import { SignJWT } from "jose";
import { db } from "../../lib/db";

const url = process.env.DATABASE_URL ?? "";
if (!/@127\.0\.0\.1:5433\/wt_[a-z0-9_]+/.test(url)) { console.error("refusing: not the devhost throwaway database"); process.exit(2); }
const H = 3600_000, now = Date.now();
const at = (h: number) => new Date(now - h * H);

async function main() {
  const admin = await db.user.upsert({ where: { email: "cyrus-admin@example.test" }, update: { role: "ADMIN" }, create: { id: "usr_cadmin", email: "cyrus-admin@example.test", name: "Cyrus Admin", role: "ADMIN", passwordHash: "x", emailVerifiedAt: new Date() } as never });
  await db.setting.upsert({ where: { key: "preview_access_emails_modbuilder" }, update: { value: admin.email! }, create: { key: "preview_access_emails_modbuilder", value: admin.email! } });
  const custs = [
    { id: "usr_cfix_a", email: "maya@example.test", name: "Maya" },
    { id: "usr_cfix_b", email: "jonas@example.test", name: "Jonas" },
  ];
  for (const c of custs) await db.user.upsert({ where: { id: c.id }, update: {}, create: { ...c, role: "CUSTOMER", passwordHash: "x", emailVerifiedAt: new Date() } as never });
  const flight = (verdict: string) => ({ testFlight: { schema: 1, gate: "g1", state: "done", version: "1.21.11", verdict, label: verdict === "passed" ? "boot-tested on Paper 1.21.11" : null, checks: [{ id: "compile", status: "pass", detail: "ok" }, { id: "boot", status: verdict === "passed" ? "pass" : "fail", detail: verdict === "passed" ? "Done (4.1s)" : "NoClassDefFoundError" }], flights: 1, busyRetries: 0, at: at(1).toISOString() }, model: "saka" });
  const builds = [
    ["mb_fix_1", "usr_cfix_a", "succeeded", null, 0.42, 3, flight("passed"), "FrostBlades"],
    ["mb_fix_2", "usr_cfix_a", "failed", "compile", 0.61, 5, null, "SkyIsles"],
    ["mb_fix_3", "usr_cfix_b", "succeeded", null, 0.38, 20, flight("failed"), "PetCompanions"],
    ["mb_fix_4", "usr_cfix_b", "failed", "refused", 0.05, 30, null, null],
    ["mb_fix_5", "usr_cfix_b", "succeeded", null, 0.29, 50, flight("passed"), "QuestBoard"],
  ] as const;
  for (const [id, userId, status, errorCode, cost, h, cyrus, name] of builds) {
    await db.modBuild.upsert({ where: { id }, update: {}, create: { id, userId, status, errorCode, costUsd: cost, prompt: "A sword that freezes mobs on hit, with a cooldown and a frost particle trail.", mcVersion: "1.21.11", pluginName: name, createdAt: at(h), durationMs: 95_000, cyrus: (cyrus ?? { model: "katara" }) as never, result: { ai: { route: null, calls: [{ kind: "generate", route: null, model: "claude-sonnet-5", costUsd: cost * 0.8 }, { kind: "repair", route: null, model: "claude-haiku-4-5-20251001", costUsd: cost * 0.2 }] } } as never } as never });
  }
  for (const c of custs) {
    await db.cyrusTokenAccount.upsert({ where: { userId: c.id }, update: {}, create: { userId: c.id, balance: c.id.endsWith("a") ? 1800 : 60, reserved: 0, lifetimeGranted: 3500 } });
    await db.cyrusTokenLot.create({ data: { userId: c.id, source: "plan", amount: 3500, remaining: c.id.endsWith("a") ? 1800 : 60 } }).catch(() => {});
    await db.cyrusTokenLedger.create({ data: { userId: c.id, kind: "purchase", delta: 3500, balanceAfter: c.id.endsWith("a") ? 1800 : 60, idemKey: `plan:in_fix_${c.id}`, source: "plan", meta: { amountPaid: 1999, tier: "saka", livemode: true } } }).catch(() => {});
    await db.cyrusPlan.upsert({ where: { userId: c.id }, update: {}, create: { userId: c.id, stripeCustomerId: `cus_fix_${c.id}`, stripeSubscriptionId: `sub_fix_${c.id}`, tier: "saka", priceTier: "saka", status: "active", livemode: true } });
  }
  await db.cyrusTokenLedger.create({ data: { userId: "usr_cfix_a", kind: "purchase", delta: 1000, balanceAfter: 1800, idemKey: "topup:cs_fix_1", source: "topup", meta: { paidCents: 1000, livemode: true } } }).catch(() => {});
  await db.cyrusLegalCase.upsert({ where: { id: "lc_fixture01" }, update: {}, create: { id: "lc_fixture01", kind: "dmca", status: "counter_received", target: `library:${"a".repeat(64)}`, entryId: "a".repeat(64), claimant: "Example Studio Ltd", claimantContact: "legal@example.test", work: "Crate texture from our asset pack", noticeAt: at(24 * 20), takedownAt: at(24 * 19), counterAt: at(24 * 16), counterBy: "contributor", counterStatement: "I painted this texture myself in the Texture Studio.", restoreEligibleAt: at(-24), history: [{ at: at(24 * 20).toISOString(), by: "owner:usr_cadmin", event: "notice", note: null }] } }).catch((e) => console.error("legal", e.message));
  await db.cyrusNotification.create({ data: { id: "cn_" + "0".repeat(20), userId: "usr_cfix_a", event: "build.finished", ref: "mb_fix_1:succeeded", title: "FrostBlades is built", body: "Your build finished.", href: "/dashboard/cyrus/mb_fix_1", email: "skipped:email_off" } }).catch(() => {});
  const t = await db.user.findUnique({ where: { id: admin.id } });
  const token = await new SignJWT({ sub: admin.id, sv: (t as { sessionVersion?: number } | null)?.sessionVersion ?? 0, typ: "session" }).setProtectedHeader({ alg: "HS256" }).setIssuedAt().setExpirationTime("1d").sign(new TextEncoder().encode(process.env.AUTH_SECRET!));
  console.log(JSON.stringify({ token, admin: admin.id, customer: "usr_cfix_a" }));
}
main().then(() => process.exit(0), (e) => { console.error(e); process.exit(1); });
EOF
