cat > scripts/cyrus/admin-shots.mjs <<'EOF'
// Cyrus r40 admin screenshots (run ON node-2 against `devhost dev`): dark desktop + phone per page.
//   devhost run -- node scripts/cyrus/admin-shots.mjs   (env: BASE, OUT, TOKEN, ONLY=comma list of names)
import { createRequire } from "node:module";
import { mkdirSync } from "node:fs";
const require = createRequire(import.meta.url);
const { chromium } = require("playwright");
const BASE = process.env.BASE ?? "http://127.0.0.1:4444";
const OUT = process.env.OUT ?? ".shots";
const TOKEN = process.env.TOKEN ?? "";
mkdirSync(OUT, { recursive: true });
const PAGES = [
  ["overview", "/admin/cyrus"], ["builds", "/admin/cyrus/builds"], ["build", "/admin/cyrus/builds/mb_fix_3"], ["users", "/admin/cyrus/users?u=usr_cfix_a"],
  ["cost", "/admin/cyrus/cost"], ["reconcile", "/admin/cyrus/reconcile"], ["holds", "/admin/cyrus/library/holds"], ["legal", "/admin/cyrus/library/legal"],
  ["lists", "/admin/cyrus/library/lists"], ["notify", "/admin/cyrus/notify"], ["flags", "/admin/cyrus/flags"],
];
const ONLY = process.env.ONLY ? process.env.ONLY.split(",") : null;
const browser = await chromium.launch();
for (const [vname, view] of [["dark", { width: 1440, height: 900 }], ["phone", { width: 390, height: 844, mobile: true }]]) {
  const ctx = await browser.newContext({ viewport: { width: view.width, height: view.height }, isMobile: !!view.mobile, hasTouch: !!view.mobile, colorScheme: "dark" });
  await ctx.addCookies([{ name: "nxeon_session", value: TOKEN, url: BASE }, { name: "nxeon_cookie_consent", value: "all", url: BASE }]);
  for (const [name, path] of PAGES) {
    if (ONLY && !ONLY.includes(name)) continue;
    const page = await ctx.newPage();
    const errs = [];
    page.on("pageerror", (e) => errs.push(String(e).slice(0, 160)));
    const r = await page.goto(BASE + path, { waitUntil: "load", timeout: 300000 }).catch((e) => { errs.push("goto " + e); return null; });
    await page.waitForTimeout(1200);
    const overflow = await page.evaluate((w) => document.documentElement.scrollWidth - w, view.width).catch(() => 0);
    await page.screenshot({ path: `${OUT}/cadmin-${name}-${vname}.png`, fullPage: true });
    console.log(`cadmin-${name}-${vname}.png status=${r?.status()}`, overflow > 1 ? `OVERFLOW ${overflow}px` : "", errs.join(" | "));
    await page.close();
  }
  await ctx.close();
}
await browser.close();
EOF
